    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُمۡ\nلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ قَالُوٓاْ إِنَّمَا نَحۡنُ مُصۡلِحُونَ\u{a0}١١\n\u{2}  \n       \u{a0}\n\u{1}\u{2}9\u{2}\u{2}أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَٰكِن لَّا يَشۡعُرُونَ\u{a0}١٢\u{2}      \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ\nلَهُمۡ ءَامِنُواْ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓاْ أَنُؤۡمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُۗ\nأَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعۡلَمُونَ\u{a0}١٣\u{2} \n         \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَوۡ كَصَيِّبٖ مِّنَ ٱلسَّمَآءِ فِيهِ\nظُلُمَٰتٞ وَرَعۡدٞ وَبَرۡقٞ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ\nحَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ\u{a0}١٩\u{2}    \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}يَكَادُ ٱلۡبَرۡقُ يَخۡطَفُ\nأَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ\nوَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ\nشَيۡءٖ قَدِيرٞ\u{a0}٢٠\u{2}  \n         \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ\nوَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ\u{a0}٢١\u{2}     \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا\nفَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ\nإِن كُنتُمۡ صَٰدِقِينَ\u{a0}٢٣\u{2}       \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ\nٱلنَّارَ ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ\u{a0}٢٤\n\u{2}     \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتٖ\nتَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةٖ\nرِّزۡقٗا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهٗاۖ\nوَلَهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَهُمۡ فِيهَا خَٰلِدُونَ\u{a0}٢٥\n\u{2}       \n        \n         \n      \u{a0}\n\u{1}\u{2}5\u{2}\u{2}۞ إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا\nفَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن\nرَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ\nبِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ\nوَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ\u{a0}٢٦\u{2}         \n       \n       \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَنقُضُونَ عَهۡدَ\nٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ\nوَيُفۡسِدُونَ فِي ٱلۡأَرۡضِۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ\u{a0}٢٧\n\u{2}  \n          \n     \u{a0}\n\u{1}\u{2}12\u{2}\u{2}كَيۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتٗا فَأَحۡيَٰكُمۡۖ\nثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ\u{a0}٢٨\u{2}     \n      \u{a0}\u{1}\u{2}\u{2}\u{2}هُوَ\nٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ ٱسۡتَوَىٰٓ إِلَى\nٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتٖۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ\u{a0}٢٩\n\u{2}\n         \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ\nقَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ\nنُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ\u{a0}٣٠\n\u{2}        \n        \n         \u{a0}\n\u{1}\u{2}4\u{2}\u{2}وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ\nفَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}٣١\u{2}       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ\nسُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ\u{a0}٣٢\n\u{2}\n          \u{a0}\n\u{1}\u{2}7\u{2}\u{2}قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ\nأَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا\nتُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ\u{a0}٣٣\u{2}       \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ\nلِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ\u{a0}٣٤\n\u{2}   \n        \u{a0}\n\u{1}\u{2}11\u{2}\u{2}وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا\nحَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ\u{a0}٣٥\n\u{2}        \n        \u{a0}\n\u{1}\u{2}13\u{2}\u{2}فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ\nبَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ\u{a0}٣٦\n\u{2}        \n         \u{a0}\n\u{1}\u{2}15\u{2}\u{2}فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ\u{a0}٣٧\n\u{2}          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَءَامِنُواْ بِمَآ أَنزَلۡتُ\nمُصَدِّقٗا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي\nثَمَنٗا قَلِيلٗا وَإِيَّٰيَ فَٱتَّقُونِ\u{a0}٤١\u{2}  \n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ\nوَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ\u{a0}٤٢\u{2}   \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ\nٱلزَّكَوٰةَ وَٱرۡكَعُواْ مَعَ ٱلرَّٰكِعِينَ\u{a0}٤٣\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ\nوَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ\u{a0}٤٤\n\u{2}  \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا\nيُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ وَلَا هُمۡ يُنصَرُونَ\u{a0}٤٨\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{2}\u{2}10\u{2}وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم\nبِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ\nخَيۡرٞ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ\u{a0}٥٤\n\u{2}       \n       \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةٗ\nفَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ\u{a0}٥٥\u{2}         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ بَعَثۡنَٰكُم مِّنۢ\nبَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}٥٦\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَظَلَّلۡنَا عَلَيۡكُمُ\nٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا\nرَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ\u{a0}٥٧\n\u{2} \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا\nوَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُولُواْ حِطَّةٞ نَّغۡفِرۡ لَكُمۡ خَطَٰيَٰكُمۡۚ\nوَسَنَزِيدُ ٱلۡمُحۡسِنِينَ\u{a0}٥٨\u{2}         \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ قَوۡلًا\nغَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ رِجۡزٗا مِّنَ\nٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ\u{a0}٥٩\u{2}   \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ\nلِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ\nٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۖ كُلُواْ\nوَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ\u{a0}٦٠\n\u{2}  \n      \n        \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ فَٱدۡعُ لَنَا رَبَّكَ\nيُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا\nوَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ\nبِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ\nوَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ\nٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ\nٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ\u{a0}٦١\n\u{2}          \n        \n      \n        \n      \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ\nمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَهُمۡ أَجۡرُهُمۡ\nعِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ\u{a0}٦٢\u{2}      \n        \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ\nأَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم\nبِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ\u{a0}٦٣\u{2}\n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ تَوَلَّيۡتُم مِّنۢ\nبَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ\nٱلۡخَٰسِرِينَ\u{a0}٦٤\u{2}  \n        \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ\nمُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا\nهُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ\u{a0}٦٧\u{2} \n         \n       \u{a0}\u{1}\u{2}11\u{2}13\u{2}قَالُواْ\nٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ\nوَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ\u{a0}٦٨\n\u{2}\n             \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ\nإِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ\u{a0}٦٩\n\u{2}          \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ\nيَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ\nوَهُمۡ يَعۡلَمُونَ\u{a0}٧٥\u{2}       \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا\nوَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ\nٱللَّهُ عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ\u{a0}٧٦\n\u{2}     \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ قُلۡ\nأَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدٗا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ تَقُولُونَ\nعَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ\u{a0}٨٠\u{2}       \n         \n    \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ\nأَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ\nإِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ\nلِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ\nتَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ\u{a0}٨٣\n\u{2}\n        \n     \n      \n     \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ أَنتُمۡ هَٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقٗا\nمِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ\nوَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ\nإِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ\nبِبَعۡضٖۚ فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيٞ\nفِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ\nوَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ\u{a0}٨٥\u{2}      \n      \n      \n    \n        \n        \n    \u{a0}\u{1}\u{2}\u{2}11\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ\nٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ\nيُنصَرُونَ\u{a0}٨٦\u{2}  \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ\nبَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ\nبِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ\nٱسۡتَكۡبَرۡتُمۡ فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ\u{a0}٨٧\u{2}     \n       \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالُواْ\nقُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ\u{a0}٨٨\n\u{2}\n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ وَكَانُواْ\nمِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم\nمَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ\u{a0}٨٩\n\u{2}         \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ\nٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ\nفَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ\u{a0}٩٠\n\u{2}       \n           \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ\nأُنزِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقٗا\nلِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم\nمُّؤۡمِنِينَ\u{a0}٩١\u{2}         \n       \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ\nثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ\u{a0}٩٢\n\u{2}   \n      \u{a0}\n\u{1}\u{2}12\u{2}\u{2}وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ\nمَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا\nوَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ\nبِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ\u{a0}٩٣\n\u{2}      \n      \n     \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن\nدُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}٩٤\n\u{2}         \n      \u{a0}\n\u{1}\u{2}3\u{2}\u{2}وَلَن يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ\u{a0}٩٥\n\u{2}        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٖ وَمِنَ ٱلَّذِينَ\nأَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةٖ وَمَا هُوَ بِمُزَحۡزِحِهِۦ\nمِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ\u{a0}٩٦\u{2}      \n         \n       \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ\nمَن كَانَ عَدُوّٗا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ\nمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ\u{a0}٩٧\n\u{2}\n         \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَمَّا جَآءَهُمۡ رَسُولٞ مِّنۡ عِندِ ٱللَّهِ\nمُصَدِّقٞ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ\nكِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ\u{a0}١٠١\n\u{2}     \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ\nسُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ\nٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ\nوَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ\nفَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ\nوَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَتَعَلَّمُونَ\nمَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ\nمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ\nأَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ\u{a0}١٠٢\u{2}        \n     \n       \n          \n       \n         \n       \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡ أَنَّهُمۡ ءَامَنُواْ\nوَٱتَّقَوۡاْ لَمَثُوبَةٞ مِّنۡ عِندِ ٱللَّهِ خَيۡرٞۚ لَّوۡ كَانُواْ يَعۡلَمُونَ\u{a0}١٠٣\n\u{2}  \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ\nٱنظُرۡنَا وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٞ\u{a0}١٠٤\n\u{2}      \n    \u{a0}\n\u{1}\u{2}13\u{2}\u{2}مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ\nأَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرٖ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ\nبِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ\u{a0}١٠٥\n\u{2}        \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ\nأَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ\u{a0}١٠٦\u{2}          \n       \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ\nمُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن\nوَلِيّٖ وَلَا نَصِيرٍ\u{a0}١٠٧\u{2}    \n        \n  \u{a0}\u{1}\u{1}\u{2}\u{2}9\u{2}وَدَّ كَثِيرٞ مِّنۡ أَهۡلِ\nٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدٗا\nمِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ\nوَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}١٠٩\n\u{2}   \n       \n         \n          \u{a0}\n\u{1}\u{2}\u{2}11\u{2}وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم\nمِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ\u{a0}١١٠\n\u{2}      \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ\nتِلۡكَ أَمَانِيُّهُمۡۗ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ\nصَٰدِقِينَ\u{a0}١١١\u{2}         \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ\nفَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ\u{a0}١١٢\n\u{2}      \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ وَقَالَتِ ٱلنَّصَٰرَىٰ\nلَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءٖ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ كَذَٰلِكَ قَالَ\nٱلَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ\nفِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ\u{a0}١١٣\u{2}       \n        \n         \n   \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ\nٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ أُوْلَٰٓئِكَ مَا كَانَ\nلَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ\nوَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ\u{a0}١١٤\u{2}    \n          \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ\nفَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٞ\u{a0}١١٥\n\u{2}  \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِينَ\nلَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ كَذَٰلِكَ\nقَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ قُلُوبُهُمۡۗ\nقَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ لِقَوۡمٖ يُوقِنُونَ\u{a0}١١٨\u{2} \n        \n       \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ\nهُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي جَآءَكَ\nمِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ\u{a0}١٢٠\u{2}          \n         \n         \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ءَاتَيۡنَٰهُمُ\nٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ وَمَن يَكۡفُرۡ بِهِۦ\nفَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ\u{a0}١٢١\u{2} \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ\nأَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ\u{a0}١٢٢\u{2}    \n     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ\nفَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا\nيَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ\u{a0}١٢٤\u{2}    \n          \n  \u{a0}\u{1}\u{2}\u{2}13\u{2}وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ\nوَأَمۡنٗا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ\nوَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ\nٱلسُّجُودِ\u{a0}١٢٥\u{2}    \n        \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ\nأَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ\nفَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ\u{a0}١٢٦\n\u{2}        \n           \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا\nمِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ\nوَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}١٢٩\u{2}   \n      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن يَرۡغَبُ عَن\nمِّلَّةِ إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ\nوَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ\u{a0}١٣٠\u{2}  \n         \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ\nوَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا\nوَأَنتُم مُّسۡلِمُونَ\u{a0}١٣٢\u{2}   \n         \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا\nمَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ\u{a0}١٣٤\n\u{2}    \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ\nأُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ\nوَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ\nمِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ\u{a0}١٣٦\n\u{2}   \n        \n       \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا\nهُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\u{a0}١٣٧\n\u{2}          \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ\nوَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ\u{a0}١٣٩\u{2}      \n      \u{a0}\u{1}\u{2}10\u{2}\u{2}أَمۡ\nتَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ\nوَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ\nوَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ\nبِغَٰفِلٍ عَمَّا تَعۡمَلُونَ\u{a0}١٤٠\u{2}\n     \n         \n         \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ\nعَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ\nمُّسۡتَقِيمٖ\u{a0}١٤٢\u{2}         \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ\nشُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا\nجَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ\nمِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ\nهَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ\nلَرَءُوفٞ رَّحِيمٞ\u{a0}١٤٣\u{2}    \n       \n         \n         \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ\nفَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ\nٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ\nأُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ\nعَمَّا يَعۡمَلُونَ\u{a0}١٤٤\u{2}     \n      \n        \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ\nءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم\nبِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ\nمَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ\u{a0}١٤٥\n\u{2}     \n         \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ\nفَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ\u{a0}١٤٦\u{2}       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلۡحَقُّ مِن\nرَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ\u{a0}١٤٧\u{2} \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ\nفَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ\nإِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}١٤٨\u{2}   \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ\nوَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا\nٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ\u{a0}١٤٩\u{2}   \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ\nشَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ\nشَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ\nمِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ\nتَهۡتَدُونَ\u{a0}١٥٠\u{2}    \n       \n        \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ\nيَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ\nوَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ\u{a0}١٥١\u{2}    \n     \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَٱذۡكُرُونِيٓ\nأَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ\u{a0}١٥٢\u{2}\n    \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ\u{a0}١٥٣\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ\nفَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ\nبِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ\u{a0}١٥٨\u{2}     \n         \n       \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ\nعَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ\u{a0}١٦٠\u{2}      \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ\nوَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ\nمِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا\nمِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ\nبَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ\u{a0}١٦٤\u{2}       \n          \n          \n      \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنَ\nٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ\nوَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ\nٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ\u{a0}١٦٥\n\u{2}\n         \n          \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ\nءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا\nيَهۡتَدُونَ\u{a0}١٧٠\u{2}            \n       \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّمَا حَرَّمَ\nعَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ\nلِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ\nغَفُورٞ رَّحِيمٌ\u{a0}١٧٣\u{2} \n       \n            \n \u{a0}\u{1}'
    '\u{1}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ\nبِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ\u{a0}١٧٦\n\u{2}    \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ\nٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ\nوَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ\nوَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ\nٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ\nوَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ\nصَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ\u{a0}١٧٧\u{2}        \n       \n       \n      \n      \n       \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ\nيَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ\u{a0}١٧٩\u{2}   \n   \u{a0}\u{1}\u{2}\u{2}\u{2}كُتِبَ عَلَيۡكُمۡ\nإِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ\nوَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ\u{a0}١٨٠\u{2} \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَمَنۢ بَدَّلَهُۥ\nبَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ\u{a0}١٨١\n\u{2} \n           \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ\nعَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ\u{a0}١٨٢\u{2}          \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم\nمَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ\nيُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ\nلَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\u{a0}١٨٤\u{2}    \n         \n        \n       \u{a0}\u{1}\u{2}7\u{2}\u{2}شَهۡرُ\nرَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ\nوَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ\nفَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ\nأَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ\nٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا\nهَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}١٨٥\u{2}\n      \n       \n        \n        \n      \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ\nلَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ\nأَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ\nوَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ\nٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ\nإِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ\nتِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ\nلِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ\u{a0}١٨٧\u{2}        \n        \n      \n         \n         \n       \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم\nبِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ\nأَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ\u{a0}١٨٨\u{2}   \n       \n    \u{a0}\u{1}\u{2}10\u{2}\u{2}۞ يَسۡـَٔلُونَكَ\nعَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ\nبِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ\nوَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ\nتُفۡلِحُونَ\u{a0}١٨٩\u{2}\n        \n        \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ\nوَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ\u{a0}١٩٠\n\u{2}     \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ\nفَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ\nٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ\nمِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ\nفَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ\nإِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي\nٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ\u{a0}١٩٦\n\u{2}   \n          \n           \n            \n            \n          \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ\nوَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ\nيَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ\nيَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ\u{a0}١٩٧\u{2}        \n         \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن\nتَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ\nعَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ\nوَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ\nلَمِنَ ٱلضَّآلِّينَ\u{a0}١٩٨\u{2}   \n      \n     \n      \n \u{a0}\u{1}\u{1}\u{2}\u{2}13\u{2}فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ\nءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن\nيَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ\nخَلَٰقٖ\u{a0}٢٠٠\u{2}     \n      \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا\nحَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ\u{a0}٢٠١\n\u{2}      \n      \u{a0}\n\u{1}\u{2}15\u{2}\u{2}أُوْلَٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ\u{a0}٢٠٢\n\u{2}       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي\nيَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ\nوَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ\u{a0}٢٠٣\u{2}       \n          \n     \u{a0}\u{1}\u{2}3\u{2}\u{2}وَمِنَ\nٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ\nعَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ\u{a0}٢٠٤\u{2}\n        \n      \u{a0}\u{1}\u{2}5\u{2}\u{2}وَإِذَا تَوَلَّىٰ سَعَىٰ\nفِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ\nلَا يُحِبُّ ٱلۡفَسَادَ\u{a0}٢٠٥\u{2}  \n       \n  \u{a0}\u{1}\u{2}\u{2}8\u{2}وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ\nبِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ\u{a0}٢٠٦\u{2}      \n    \u{a0}\u{1}\u{2}8\u{2}\u{2}وَمِنَ\nٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ\nرَءُوفُۢ بِٱلۡعِبَادِ\u{a0}٢٠٧\u{2}\n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ\nفِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ\nإِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ\u{a0}٢٠٨\u{2}   \n      \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}زُيِّنَ لِلَّذِينَ\nكَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ\nٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ\u{a0}٢١٢\n\u{2} \n       \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ\nوَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ\nفِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ\nمَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ\nلِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ\nصِرَٰطٖ مُّسۡتَقِيمٍ\u{a0}٢١٣\u{2}       \n       \n          \n        \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا\nيَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ\nوَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ\nأَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ\u{a0}٢١٤\u{2}     \n        \n         \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ\nشَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ\nوَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ\u{a0}٢١٦\u{2}        \n          \n    \u{a0}\u{1}\u{2}\u{2}\u{2}يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ\nٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ\nوَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ\nعِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ\nحَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن يَرۡتَدِدۡ\nمِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرٞ فَأُوْلَٰٓئِكَ حَبِطَتۡ\nأَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ\nهُمۡ فِيهَا خَٰلِدُونَ\u{a0}٢١٧\u{2}  \n          \n       \n        \n       \n       \n      \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ\nوَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ\nأَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ\nكَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ\u{a0}٢١٩\n\u{2}  \n       \n       \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ\nمِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ\nيُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَٰٓئِكَ\nيَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ\nوَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ\u{a0}٢٢١\u{2}       \n       \n        \n        \n    \u{a0}\u{1}\u{2}8\u{2}\u{2}وَيَسۡـَٔلُونَكَ\nعَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ\nوَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ\nأَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ\u{a0}٢٢٢\n\u{2}\n        \n        \n       \u{a0}\n\u{1}\u{2}\u{2}13\u{2}نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ\nوَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ\u{a0}٢٢٣\n\u{2}        \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ\nبِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ\nأَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ\nفِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ\nوَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ\u{a0}٢٢٨\u{2} \n           \n         \n         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلطَّلَٰقُ مَرَّتَانِۖ\nفَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن\nتَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ\nٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ\nبِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ\nهُمُ ٱلظَّٰلِمُونَ\u{a0}٢٢٩\u{2} \n        \n         \n           \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ\nزَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن\nيُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ\u{a0}٢٣٠\n\u{2}        \n           \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ\nسَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ\nذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ\nنِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ\nيَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ\u{a0}٢٣١\n\u{2}       \n       \n         \n        \n         \u{a0}\n\u{1}\u{2}6\u{2}\u{2}وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ\nأَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ\nمِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ\nيَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ\u{a0}٢٣٢\u{2}        \n         \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ\nحَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ\nوَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ\nوَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ\nفَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ\nأَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ\nءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ\u{a0}٢٣٣\n\u{2}  \n          \n        \n         \n          \n         \n         \u{a0}\n\u{1}'
    '\u{1}\u{1}\u{2}\u{2}11\u{2}لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ\nمَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ\nقَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ\u{a0}٢٣٦\n\u{2}     \n         \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ\nلَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ\nٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ\nوَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ\u{a0}٢٣٧\n\u{2}       \n         \n       \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ\nلِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ\nفَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن\nمَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ\u{a0}٢٤٠\u{2}     \n       \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ أَلَمۡ تَرَ\nإِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ\nفَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى\nٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ\u{a0}٢٤٣\n\u{2} \n        \n          \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ\u{a0}٢٤٤\n\u{2}        \u{a0}\n\u{1}\u{2}14\u{2}\u{2}مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا\nكَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ\u{a0}٢٤٥\n\u{2}         \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ\nلِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ\nهَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ\nقَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا\nمِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ\nإِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ\u{a0}٢٤٦\u{2}           \n         \n       \n         \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ\nلَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ\nقَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ\nمِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ\nعَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ\nيُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ\u{a0}٢٤٧\n\u{2}\n        \n        \n         \n      \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}7\u{2}فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم\nبِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ\nمِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا\nمِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ\nلَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ\nيَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ\nغَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ\u{a0}٢٤٩\n\u{2}       \n         \n         \n       \n       \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ\nعَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ\nٱلۡكَٰفِرِينَ\u{a0}٢٥٠\u{2}      \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ\nدَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ\nوَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم\nبِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو\nفَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ\u{a0}٢٥١\u{2}   \n     \n       \n     \n  \u{a0}\u{1}\u{2}\u{2}\u{2}تِلۡكَ ءَايَٰتُ ٱللَّهِ\nنَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ\u{a0}٢٥٢\n\u{2}  \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ\nوَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ\nوَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ\nمِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ\nفَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ\nوَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ\u{a0}٢٥٣\u{2}         \n       \n        \n        \n          \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ\nٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا\nفِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ\nأَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا\nشَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ\nوَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ\u{a0}٢٥٥\u{2}    \n           \n           \n         \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ\nمِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ\nٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ\u{a0}٢٥٦\n\u{2}      \n       \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَوۡ كَٱلَّذِي مَرَّ\nعَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ\nبَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ\nقَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ\nفَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ\nحِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى\nٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا\nتَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٢٥٩\n\u{2}  \n          \n          \n          \n       \n     \n      \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ\nأَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ\nلِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ\u{a0}٢٦١\u{2}        \n         \n    \u{a0}\u{1}\u{2}\u{2}9\u{2}ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ\nفِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ\nأَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ\u{a0}٢٦٢\n\u{2}  \n           \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ\nأَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ\u{a0}٢٦٣\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ\nصَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ\nوَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ\nتُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ\nشَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ\u{a0}٢٦٤\n\u{2}    \n       \n        \n       \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ\nلَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ\nفِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ\nفَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ\nلَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ\u{a0}٢٦٦\u{2}   \n         \n        \n       \n   \u{a0}\u{1}\u{2}\u{2}11\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا\nلَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم\nبِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ\u{a0}٢٦٧\n\u{2} \n       \n        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِن تُبۡدُواْ\nٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ\nفَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ\nوَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ\u{a0}٢٧١\u{2} \n      \n      \n   \u{a0}\u{1}\u{2}\u{2}8\u{2}۞ لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ\nوَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ\nفَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ\nوَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ\u{a0}٢٧٢\n\u{2}  \n        \n      \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ\nلَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ\nٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ\nلَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ\nفَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ\u{a0}٢٧٣\u{2}     \n     \n     \n       \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي\nيَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ\nمِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ\nمِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ\nفَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ\u{a0}٢٧٥\u{2}        \n        \n         \n          \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ\nفَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ\nٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ\nءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ\u{a0}٢٨٣\u{2}        \n        \n       \n     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ\nإِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ\nوَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا\nوَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ\u{a0}٢٨٥\u{2}   \n        \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}لَا يُكَلِّفُ\nٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ\nرَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ\nعَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا\nتُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ\nأَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ\u{a0}٢٨٦\n\u{2} \n         \n         \n         \n          \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مِن\nقَبۡلُ هُدٗى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ لَهُمۡ\nعَذَابٞ شَدِيدٞۗ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ\u{a0}٤\u{2}\n          \n     \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ\nشَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ\u{a0}٥\u{2}    \n     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}هُوَ\nٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ\nوَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ\nمِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ\nوَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ\nإِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ\u{a0}٧\u{2}\n         \n         \n         \n           \n  \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ\nلَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ\u{a0}٨\u{2}       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}رَبَّنَآ إِنَّكَ جَامِعُ\nٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ\u{a0}٩\n\u{2}  \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}كَدَأۡبِ ءَالِ\nفِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ\nوَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ\u{a0}١١\u{2} \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ\nوَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ\u{a0}١٢\u{2}   \n    \u{a0}\u{1}\u{2}5\u{2}\u{2}قَدۡ كَانَ\nلَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةٞ تُقَٰتِلُ فِي سَبِيلِ ٱللَّهِ\nوَأُخۡرَىٰ كَافِرَةٞ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ ٱلۡعَيۡنِۚ وَٱللَّهُ\nيُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي\nٱلۡأَبۡصَٰرِ\u{a0}١٣\u{2} \n         \n      \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ\nوَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ\nوَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ\nٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ\u{a0}١٤\u{2}     \n     \n     \n     \u{a0}\u{1}\u{2}\u{2}\u{2}۞ قُلۡ\nأَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّٰتٞ\nتَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ\nوَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ\u{a0}١٥\n\u{2}\n        \n       \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا\nعَذَابَ ٱلنَّارِ\u{a0}١٦\u{2}        \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}شَهِدَ\nٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ\nلَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}١٨\u{2}\n          \n     \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلدِّينَ عِندَ\nٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ\nبَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ\nٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ\u{a0}١٩\u{2}  \n        \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ\nوَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ\nءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا\nعَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ\u{a0}٢٠\u{2}   \n        \n       \n    \u{a0}\u{1}\u{2}11\u{2}\u{2}إِنَّ ٱلَّذِينَ يَكۡفُرُونَ\nبِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ\nٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم\nبِعَذَابٍ أَلِيمٍ\u{a0}٢١\u{2}  \n      \n     \n \u{a0}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ أَعۡمَٰلُهُمۡ\nفِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ\u{a0}٢٢\n\u{2}   \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ\nفِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ\u{a0}٢٤\u{2}         \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ\nمَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ\nمَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٢٦\u{2}     \n         \n        \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن\nيَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ\nتُقَىٰةٗۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ\u{a0}٢٨\u{2}        \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ\nإِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي\nٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٢٩\n\u{2}\n           \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ\nمِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ\nٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ\u{a0}٣٠\u{2}          \n         \n    \u{a0}\u{1}\u{2}\u{2}4\u{2}قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ\nفَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ\u{a0}٣١\n\u{2}    \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ\nوَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ\u{a0}٣٣\u{2}      \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ\nمَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\u{a0}٣٥\u{2}       \n         \u{a0}\u{1}\u{2}9\u{2}\u{2}فَلَمَّا\nوَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ\nوَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ\nوَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ\u{a0}٣٦\u{2}\n         \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمٞ\nيُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ\nٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ\u{a0}٣٩\u{2}   \n         \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ\nإِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ\nمَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ\u{a0}٤٤\u{2}    \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَتِ\nٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ\nعِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ\u{a0}٤٥\n\u{2} \n        \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ\nأَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ\nفَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ\nوَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ\nفِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ\u{a0}٤٩\n\u{2}         \n        \n      \n        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ\nٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ\nأَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ\u{a0}٥٢\n\u{2}   \n        \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}3\u{2}وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ\nٱلۡمَٰكِرِينَ\u{a0}٥٤\u{2}    \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ\nإِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ\nفَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ\nفَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ\u{a0}٥٥\u{2}      \n       \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَمَّا ٱلَّذِينَ\nكَفَرُواْ فَأُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا\nلَهُم مِّن نَّٰصِرِينَ\u{a0}٥٦\u{2} \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ\u{a0}٥٧\n\u{2}   \n      \u{a0}\n\u{1}\u{2}10\u{2}\u{2}ذَٰلِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ\u{a0}٥٨\u{2}      \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ\nمَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ\nلَهُۥ كُن فَيَكُونُ\u{a0}٥٩\u{2}\n          \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ\nأَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ\nثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ\u{a0}٦١\n\u{2}           \n     \n      \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ\nأَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا\nبَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا\nمُسۡلِمُونَ\u{a0}٦٤\u{2}        \n          \n         \n\u{a0}\u{1}\u{2}\u{2}8\u{2}يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ\nإِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا\nتَعۡقِلُونَ\u{a0}٦٥\u{2}    \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ\nعِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ\nلَا تَعۡلَمُونَ\u{a0}٦٦\u{2}     \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ\nحَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ\u{a0}٦٧\u{2}       \n     \u{a0}\u{1}'
    '\u{2}11\u{2}\u{2}إِنَّ أَوۡلَى ٱلنَّاسِ\nبِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ\nٱلۡمُؤۡمِنِينَ\u{a0}٦٨\u{2}  \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ\nوَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ\u{a0}٦٩\u{2}      \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ\nٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ\nعِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ\nعَلِيمٞ\u{a0}٧٣\u{2}       \n          \n           \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ\nيُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا\nمَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ\nسَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ\u{a0}٧٥\n\u{2}      \n          \n          \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ\u{a0}٧٦\u{2}        \u{a0}\u{1}\u{2}12\u{2}\u{2}إِنَّ\nٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ لَا\nخَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيۡهِمۡ\nيَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ\u{a0}٧٧\n\u{2}\n        \n         \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ\nمِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ\nمِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ\nوَهُمۡ يَعۡلَمُونَ\u{a0}٧٨\u{2}      \n       \n           \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ\nوَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادٗا لِّي مِن\nدُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ\nوَبِمَا كُنتُمۡ تَدۡرُسُونَ\u{a0}٧٩\u{2}      \n        \n        \n  \u{a0}\u{1}\u{2}\u{2}8\u{2}وَلَا يَأۡمُرَكُمۡ أَن تَتَّخِذُواْ ٱلۡمَلَٰٓئِكَةَ\nوَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ\u{a0}٨٠\n\u{2}    \n       \u{a0}\n\u{1}\u{2}\u{2}12\u{2}وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ\nوَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ\nبِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ\nقَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ\u{a0}٨١\n\u{2}        \n       \n       \n       \u{a0}\n\u{1}\u{2}\u{2}13\u{2}فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ\u{a0}٨٢\n\u{2}      \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَإِلَيۡهِ يُرۡجَعُونَ\u{a0}٨٣\n\u{2}        \n    \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ\nوَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ\nمُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ\nمِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ\u{a0}٨٤\u{2}         \n     \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ\nدِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ\u{a0}٨٥\n\u{2}   \n        \u{a0}\n\u{1}\u{2}6\u{2}\u{2}كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ\nأَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ\nٱلظَّٰلِمِينَ\u{a0}٨٦\u{2}       \n        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ كُلُّ ٱلطَّعَامِ كَانَ حِلّٗا لِّبَنِيٓ\nإِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ\nٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}٩٣\n\u{2}    \n          \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ\nفَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ\u{a0}١٠٠\n\u{2}    \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}7\u{2}وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ\nوَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ\nفَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ\nفَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ\u{a0}١٠٣\n\u{2}     \n         \n        \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ\nوَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ\u{a0}١٠٤\u{2}       \n     \u{a0}\u{1}\u{2}9\u{2}\u{2}وَلَا\nتَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ\nوَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ\u{a0}١٠٥\u{2}\n        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ\nوَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ\nأَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ\nوَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ\u{a0}١١٠\u{2}      \n      \n      \n \u{a0}\u{1}\u{2}\u{2}\u{2}لَن يَضُرُّوكُمۡ إِلَّآ أَذٗىۖ\nوَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ\u{a0}١١١\u{2}   \n      \u{a0}\u{1}\u{2}\u{2}\u{2}ضُرِبَتۡ\nعَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ\nوَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ\nبِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ\nحَقّٖۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ\u{a0}١١٢\u{2}\n           \n       \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}۞ لَيۡسُواْ سَوَآءٗۗ\nمِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ\nوَهُمۡ يَسۡجُدُونَ\u{a0}١١٣\u{2} \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ\nوَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ\nفِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ\u{a0}١١٤\u{2}   \n     \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا يَفۡعَلُواْ\nمِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ\u{a0}١١٥\n\u{2} \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم\nمِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ\u{a0}١١٦\n\u{2}        \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}11\u{2}هَٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ\nوَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ\nمِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\u{a0}١١٩\n\u{2}       \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ\nبِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ\nإِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ\u{a0}١٢٠\u{2}       \n       \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى\nٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\u{a0}١٢٢\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ\nأَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}١٢٣\u{2}    \n    \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا\nٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ\u{a0}١٢٦\u{2}         \n      \u{a0}\u{1}\u{2}\u{2}\u{2}لِيَقۡطَعَ طَرَفٗا\nمِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ\u{a0}١٢٧\u{2} \n      \u{a0}\u{1}'
    '\u{2}9\u{2}10\u{2}لَيۡسَ لَكَ\nمِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ\u{a0}١٢٨\n\u{2} \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ\nوَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ\u{a0}١٢٩\u{2}         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ\nلَعَلَّكُمۡ تُفۡلِحُونَ\u{a0}١٣٠\u{2} \n       \n \u{a0}\u{1}\u{2}\u{2}14\u{2}وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ\u{a0}١٣١\n\u{2}    \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا\nٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ\u{a0}١٣٣\u{2}      \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ إِذَا\nفَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ\nلِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ\nمَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ\u{a0}١٣٥\u{2} \n       \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ\nمِّن رَّبِّهِمۡ وَجَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ\nفِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ\u{a0}١٣٦\u{2}  \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ\nفَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ\u{a0}١٣٧\n\u{2}    \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ\nوَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ\nءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ\u{a0}١٤٠\n\u{2}       \n       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ\nلِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ\nثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ\nمِنۡهَاۚ وَسَنَجۡزِي ٱلشَّٰكِرِينَ\u{a0}١٤٥\u{2} \n         \n        \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ قَوۡلَهُمۡ\nإِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ\nأَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ\u{a0}١٤٧\u{2}  \n          \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَـَٔاتَىٰهُمُ ٱللَّهُ\nثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ\u{a0}١٤٨\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ\nوَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ\nوَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم\nمَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم\nمَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ\nوَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ\u{a0}١٥٢\n\u{2}  \n      \n       \n      \n      \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ\nوَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ\nغَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ\nوَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}١٥٣\n\u{2}     \n    \n      \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ\nيَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا\nكَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ\u{a0}١٥٥\u{2}   \n       \n        \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا\nٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا\nضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا\nقُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ\nوَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ\u{a0}١٥٦\u{2}\n        \n           \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ\nأَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ\u{a0}١٥٧\n\u{2}    \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}فَبِمَا رَحۡمَةٖ مِّنَ\nٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ\nفَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ\nفَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ\u{a0}١٥٩\u{2}  \n          \n        \n      \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ\nٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ\u{a0}١٦٢\n\u{2}  \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ\u{a0}١٦٣\n\u{2}       \u{a0}\n\u{1}\u{2}11\u{2}\u{2}لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ\nيَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ\nوَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ\u{a0}١٦٤\n\u{2}          \n     \n       \u{a0}\n\u{1}\u{2}14\u{2}\u{2}أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ\nقُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}١٦٥\n\u{2}        \n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ\nأَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ\nيَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ\nفِي قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ\u{a0}١٦٧\u{2}         \n        \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ\nوَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ\nٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}١٦٨\u{2}  \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي\nسَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ\u{a0}١٦٩\u{2}    \n       \u{a0}\u{1}\u{2}\u{2}\u{2}فَرِحِينَ\nبِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ\nبِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ\u{a0}١٧٠\n\u{2}\n        \n        \u{a0}\n\u{1}\u{2}11\u{2}\u{2}۞ يَسۡتَبۡشِرُونَ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ\nٱلۡمُؤۡمِنِينَ\u{a0}١٧١\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ\nأَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ\u{a0}١٧٢\n\u{2}      \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ\nٱللَّهَ شَيۡـٔٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ\u{a0}١٧٧\u{2}      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ\nأَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ\nوَلَهُمۡ عَذَابٞ مُّهِينٞ\u{a0}١٧٨\u{2}   \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ\nأَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ\nعَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ\nوَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمٞ\u{a0}١٧٩\u{2}      \n          \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا\nيَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا\nلَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ\nوَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ\u{a0}١٨٠\n\u{2}\n         \n          \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ قَالُوٓاْ إِنَّ\nٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ\nتَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلٞ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ\nوَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}١٨٣\n\u{2}  \n        \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلٞ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ\nوَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ\u{a0}١٨٤\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ\nوَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ\nعَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ\nإِلَّا مَتَٰعُ ٱلۡغُرُورِ\u{a0}١٨٥\u{2}   \n      \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ\nوَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ\nمِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ\nوَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ\u{a0}١٨٦\n\u{2}  \n     \n      \n       \u{a0}\n\u{1}\u{1}'
    '\u{2}\u{2}\u{2}لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ\nبِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم\nبِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ\u{a0}١٨٨\u{2}   \n         \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا\nعَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ\u{a0}١٩٤\n\u{2}   \n         \u{a0}\n\u{1}\u{2}\u{2}5\u{2}فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن\nذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ\nمِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ\nعَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا\nٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ\u{a0}١٩٥\n\u{2}         \n        \n       \n      \n        \u{a0}\n\u{1}\u{2}\u{2}6\u{2}لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ\u{a0}١٩٦\u{2}      \u{a0}\u{1}\u{2}6\u{2}\u{2}مَتَٰعٞ قَلِيلٞ\nثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ\u{a0}١٩٧\u{2} \n    \u{a0}\u{1}\u{2}7\u{2}9\u{2}لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ\nرَبَّهُمۡ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا\nنُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ\u{a0}١٩٨\u{2}  \n        \n        \u{a0}\u{1}\u{2}9\u{2}13\u{2}وَإِنَّ مِنۡ\nأَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ\nأُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا\nقَلِيلًاۚ أُوْلَٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ\nسَرِيعُ ٱلۡحِسَابِ\u{a0}١٩٩\u{2} \n        \n        \n       \n \u{a0}\u{1}\u{2}13\u{2}14\u{1}\u{2}2\u{2}4\u{2}۞يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا\nزَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ\nبِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا\u{a0}١\u{2}          \n         \n      \u{a0}\u{1}\u{2}4\u{2}\u{2}وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ\nوَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ\nكَانَ حُوبٗا كَبِيرٗا\u{a0}٢\u{2}  \n         \n  \u{a0}\u{1}\u{2}6\u{2}8\u{2}وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ\nمَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ\nفَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ\u{a0}٣\u{2}      \n           \n        \u{a0}\u{1}\u{2}8\u{2}\u{2}وَءَاتُواْ\nٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ\nهَنِيٓـٔٗا مَّرِيٓـٔٗا\u{a0}٤\u{2}\n          \n \u{a0}\u{1}\u{2}\u{2}11\u{2}وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ\nقِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا\u{a0}٥\u{2}       \n       \u{a0}\u{1}\u{2}11\u{2}\u{2}وَٱبۡتَلُواْ\nٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ\nإِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ\nغَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا\nدَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا\u{a0}٦\n\u{2}\n         \n         \n       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا\nخَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا\u{a0}٩\n\u{2}       \n      \u{a0}\n\u{1}\u{2}7\u{2}\u{2}إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي\nبُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا\u{a0}١٠\u{2}        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}يُوصِيكُمُ ٱللَّهُ\nفِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ\nفَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا\nٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن\nكَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ\nفَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي\nبِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ\nنَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا\u{a0}١١\n\u{2} \n        \n         \n        \n           \n         \n         \n        \u{a0}\n\u{1}\u{2}\u{2}10\u{2}۞ وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن\nلَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا\nتَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ\nوَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ\nفَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ\nمِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ\nرَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ\nوَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ\nفَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ\nأَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ\u{a0}١٢\n\u{2}       \n        \n       \n        \n       \n        \n         \n       \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ\nيُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ\nخَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}١٣\n\u{2}      \n     \n    \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ\nنَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ\u{a0}١٤\n\u{2}      \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ\nعَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي\nٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا\u{a0}١٥\n\u{2}     \n      \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا\nوَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا\u{a0}١٦\n\u{2}     \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ\nثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ\nٱللَّهُ عَلِيمًا حَكِيمٗا\u{a0}١٧\u{2}       \n        \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}5\u{2}وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ\nبَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا\nغَلِيظٗا\u{a0}٢١\u{2}   \n     \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ\nٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا\nوَسَآءَ سَبِيلًا\u{a0}٢٢\u{2}     \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ\nوَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ\nٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِيٓ أَرۡضَعۡنَكُمۡ\nوَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ\nوَرَبَٰٓئِبُكُمُ ٱلَّٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ\nٱلَّٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ\nفَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ\nمِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ\nإِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا\u{a0}٢٣\n\u{2}  \n    \n     \n    \n     \n       \n     \n     \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ\nكِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ\nبِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ\nمِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ\nفِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا\nحَكِيمٗا\u{a0}٢٤\u{2}      \n         \n      \n      \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ\nٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن\nفَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ\nبَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ\nبِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ\nأَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ\nمَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ\nٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ\u{a0}٢٥\n\u{2}      \n      \n      \n     \n     \n       \n       \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن\nتَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ\nإِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا\u{a0}٢٩\u{2} \n       \n       \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ\nعَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّٰلِحَٰتُ\nقَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّٰتِي تَخَافُونَ\nنُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ\nوَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ\nإِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا\u{a0}٣٤\u{2}       \n      \n       \n    \n      \n    \u{a0}\u{1}\u{2}\u{2}8\u{2}وَإِنۡ خِفۡتُمۡ شِقَاقَ\nبَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن\nيُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا\u{a0}٣٥\n\u{2}  \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ\nإِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ\nذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ\nوَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن\nكَانَ مُخۡتَالٗا فَخُورًا\u{a0}٣٦\u{2}      \n     \n     \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ\nٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ\nمِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا\u{a0}٣٧\n\u{2}  \n     \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ\nبِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ\nقَرِينٗا\u{a0}٣٨\u{2}      \n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ\nوَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي\nسَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ\nأَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ\nفَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ\nٱللَّهَ كَانَ عَفُوًّا غَفُورًا\u{a0}٤٣\u{2}     \n         \n          \n         \n      \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ\nجُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ\nكَانَ عَزِيزًا حَكِيمٗا\u{a0}٥٦\u{2}        \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ\nسَنُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ\nلَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا\u{a0}٥٧\u{2}   \n        \n      \u{a0}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ\nٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ\nٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا\nبَصِيرٗا\u{a0}٥٨\u{2}\n         \n            \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ\nحَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ\nفِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا\u{a0}٦٥\n\u{2}   \n       \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن\nلَّدُنَّآ أَجۡرًا عَظِيمٗا\u{a0}٦٧\u{2}  \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم\nمِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَۚ وَحَسُنَ\nأُوْلَٰٓئِكَ رَفِيقٗا\u{a0}٦٩\u{2}         \n     \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ\nفَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ\nشَهِيدٗا\u{a0}٧٢\u{2}   \n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن\nلَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ\nفَوۡزًا عَظِيمٗا\u{a0}٧٣\u{2}      \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}۞ فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ\nيَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي\nسَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا\u{a0}٧٤\n\u{2}    \n      \n        \u{a0}\n\u{1}\u{2}\u{2}4\u{2}وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ\nوَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ\nٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ\nنَصِيرًا\u{a0}٧٥\u{2}         \n        \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ\nيُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ\nٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا\u{a0}٧٦\u{2}       \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ\nوَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ\nمِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ\nكَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا\nقَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا\u{a0}٧٧\u{2}       \n         \n          \n          \n       \u{a0}\u{1}\u{2}\u{2}\u{2}أَيۡنَمَا\nتَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ\nحَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ\nهَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ\nيَفۡقَهُونَ حَدِيثٗا\u{a0}٧٨\u{2}\n         \n         \n            \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن\nسَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا\u{a0}٧٩\n\u{2}        \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ\nعِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ\nمَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا\u{a0}٨١\n\u{2}    \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ\nفِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا\u{a0}٨٢\u{2}         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ\nأَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي\nٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ\nٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا\u{a0}٨٣\n\u{2}    \n         \n       \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ\nفِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ\nأَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا\u{a0}٨٨\u{2}   \n        \n        \u{a0}\u{1}\u{2}\u{2}\u{2}وَدُّواْ لَوۡ\nتَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ\nحَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ\nحَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا\u{a0}٨٩\n\u{2} \n        \n        \n       \u{a0}\n\u{1}\u{2}8\u{2}\u{2}إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ\nحَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ\nٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ\nوَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا\u{a0}٩٠\n\u{2}         \n        \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ\nمَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ\nٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ\nثَقِفۡتُمُوهُمۡۚ وَأُوْلَٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا\u{a0}٩١\n\u{2}       \n          \n     \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ\nمُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ\nأَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ\nوَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ\nمِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ\nإِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ\nفَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ\nٱللَّهُ عَلِيمًا حَكِيمٗا\u{a0}٩٢\u{2}         \n       \n         \n      \n      \n       \n      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن يَقۡتُلۡ مُؤۡمِنٗا\nمُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ\nٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا\u{a0}٩٣\u{2}  \n     \n      \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا\nٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ\nلِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ\nعَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ\nكَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ\nفَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا\u{a0}٩٤\n\u{2}\n         \n      \n      \n      \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَأُوْلَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا\u{a0}٩٩\n\u{2}         \u{a0}\n\u{1}\u{2}11\u{2}\u{2}۞ وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ\nوَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ\nفَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا\u{a0}١٠٠\u{2}          \n          \n        \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا ضَرَبۡتُمۡ\nفِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ\nأَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا\u{a0}١٠١\n\u{2} \n          \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ\nمِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ\nمِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ\nفَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ\nكَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ\nعَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ\nأَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ\nوَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا\u{a0}١٠٢\n\u{2}       \n      \n      \n      \n      \n        \n        \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَهِنُواْ\nفِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا\nتَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا\nحَكِيمًا\u{a0}١٠٤\u{2} \n        \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ\nٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا\u{a0}١٠٥\n\u{2}      \n       \u{a0}\n\u{1}\u{1}\u{1}'
    '\u{2}\u{2}\u{2}يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ\nمِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ\nٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا\u{a0}١٠٨\u{2}    \n           \n   \u{a0}\u{1}\u{2}\u{2}\u{2}هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ جَٰدَلۡتُمۡ\nعَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ\nٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا\u{a0}١٠٩\u{2}  \n        \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا\nثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا\u{a0}١١٢\u{2}    \n        \u{a0}\u{1}\u{2}11\u{2}\u{2}وَلَوۡلَا\nفَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن\nيُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن\nشَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ\nمَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا\u{a0}١١٣\n\u{2}\n       \n       \n      \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ\nأَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ\nٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا\u{a0}١١٤\u{2}         \n        \n      \u{a0}\u{1}\u{1}\u{2}\u{2}7\u{2}إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ\nذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا\u{a0}١١٦\n\u{2}         \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ\nمِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا\u{a0}١١٨\u{2}   \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ\nوَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ\nفَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا\nمِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا\u{a0}١١٩\n\u{2} \n    \n      \n      \u{a0}\n\u{1}\u{2}14\u{2}\u{2}يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا\u{a0}١٢٠\n\u{2}      \u{a0}\n\u{1}\u{2}15\u{2}\u{2}أُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا\u{a0}١٢١\n\u{2}      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ\nجَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ\nٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا\u{a0}١٢٢\u{2}    \n        \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلِلَّهِ مَا\nفِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ\nمُّحِيطٗا\u{a0}١٢٦\u{2} \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ\nفِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ\nٱلَّٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ\nوَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ\nبِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا\u{a0}١٢٧\n\u{2}     \n        \n        \n     \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ\nعَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ\nٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ\nبِمَا تَعۡمَلُونَ خَبِيرٗا\u{a0}١٢٨\u{2}         \n       \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ\nبَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ\nفَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ\nكَانَ غَفُورٗا رَّحِيمٗا\u{a0}١٢٩\u{2}   \n       \n      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا\nمِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا\u{a0}١٣٠\u{2}    \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَلِلَّهِ مَا فِي\nٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ\nمِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ\nمَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا\u{a0}١٣١\n\u{2}  \n        \n         \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ\nٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا\u{a0}١٣٤\n\u{2}     \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ\nوَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا\nأَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن\nتَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا\u{a0}١٣٥\u{2}       \n        \n          \n        \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ\nثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ\nسَبِيلَۢا\u{a0}١٣٧\u{2}      \n           \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}4\u{2}ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ\nنَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ\nعَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ\nٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا\u{a0}١٤١\n\u{2}          \n        \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى\nٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا\nقَلِيلٗا\u{a0}١٤٢\u{2}        \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِۚ\nوَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا\u{a0}١٤٣\u{2}        \n      \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nلَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ\nأَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا\u{a0}١٤٤\u{2}  \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلۡمُنَٰفِقِينَ\nفِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا\u{a0}١٤٥\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ\nٱللَّهُ سَمِيعًا عَلِيمًا\u{a0}١٤٨\u{2}          \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ يَكۡفُرُونَ\nبِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ\nوَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ\nأَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا\u{a0}١٥٠\u{2}  \n       \n     \n    \u{a0}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ\nحَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا\u{a0}١٥١\u{2}  \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَامَنُواْ\nبِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَٰٓئِكَ سَوۡفَ\nيُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا\u{a0}١٥٢\u{2} \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}يَسۡـَٔلُكَ\nأَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ\nمُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ\nٱلصَّٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ\nٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا\u{a0}١٥٣\n\u{2}\n         \n        \n        \n       \u{a0}\n\u{1}\u{2}14\u{2}\u{2}وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا\nوَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا\u{a0}١٥٤\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ\nبُهۡتَٰنًا عَظِيمٗا\u{a0}١٥٦\u{2}   \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ\nرَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ\nٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ\nوَمَا قَتَلُوهُ يَقِينَۢا\u{a0}١٥٧\u{2}      \n          \n            \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ\nبِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا\u{a0}١٦١\u{2}       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}لَّٰكِنِ\nٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ\nأُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ\nوَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا\u{a0}١٦٢\n\u{2}\n         \n      \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ\nوَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ\nوَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ\nوَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا\u{a0}١٦٣\u{2}         \n     \n     \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ\nلِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا\u{a0}١٦٥\n\u{2}    \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}لَّٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ\nوَٱلۡمَلَٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا\u{a0}١٦٦\u{2}       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ\nكَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا\u{a0}١٦٧\n\u{2} \n        \u{a0}\n\u{1}'
    '\u{2}11\u{2}\u{2}إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا\nلِيَهۡدِيَهُمۡ طَرِيقًا\u{a0}١٦٨\u{2}         \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ\nوَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا\u{a0}١٦٩\u{2}     \n    \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ\nٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ\nفَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا\u{a0}١٧٠\n\u{2}   \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ\nعَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ\nٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ\nوَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ\nوَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ\nوَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا\u{a0}١٧١\u{2}       \n         \n        \n         \n         \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ\nفِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا\u{a0}١٧٥\n\u{2}      \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ\nلَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ\nإِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ\nوَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ\nيُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ\u{a0}١٧٦\n\u{2}        \n          \n           \n        \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ\nٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ\nيَحۡكُمُ مَا يُرِيدُ\u{a0}١\u{2}       \n           \n  \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ\nوَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ\nٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ\nوَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ\nٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ\nعَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ\u{a0}٢\n\u{2}      \n         \n        \n       \n        \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ\nبِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ\nٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ\nبِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ\nفَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ\nعَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي\nمَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ\u{a0}٣\n\u{2}         \n      \n         \n        \n       \n        \n       \u{a0}\n\u{1}\u{2}8\u{2}\u{2}يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم\nمِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ\nعَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ\u{a0}٤\n\u{2}         \n         \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ\nلَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ\nمِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ\nمُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ\nبِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ\u{a0}٥\n\u{2}        \n       \n        \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ\nوُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ\nوَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ\nوَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ\nأَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا\nفَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ\nلِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ\nوَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}٦\n\u{2}       \n     \n      \n           \n        \n      \n      \n    \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم\nبِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ\nٱلصُّدُورِ\u{a0}٧\u{2}      \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ\nشُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ\nأَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ\nٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}٨\u{2}     \n      \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ\nإِسۡرَٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ\nإِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ\nوَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا\nحَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ\nجَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ\nذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ\u{a0}١٢\u{2}    \n       \n      \n     \n    \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَبِمَا\nنَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ\nيُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّٗا مِّمَّا\nذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٖ مِّنۡهُمۡ إِلَّا قَلِيلٗا مِّنۡهُمۡۖ\nفَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ\u{a0}١٣\n\u{2}\n     \n      \n          \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ\nفَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ\nوَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ\nبِمَا كَانُواْ يَصۡنَعُونَ\u{a0}١٤\u{2}      \n       \n      \n  \u{a0}\u{1}\u{2}\u{2}8\u{2}يَٰٓأَهۡلَ ٱلۡكِتَٰبِ\nقَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرٗا مِّمَّا\nكُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن\nكَثِيرٖۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ وَكِتَٰبٞ\nمُّبِينٞ\u{a0}١٥\u{2} \n      \n     \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ\nسُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى\nٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ\u{a0}١٦\n\u{2}     \n     \n     \u{a0}\n\u{1}\u{2}11\u{2}\u{2}لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ\nٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ\nأَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي\nٱلۡأَرۡضِ جَمِيعٗاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nوَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}١٧\n\u{2}       \n         \n       \n     \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰقَوۡمِ ٱدۡخُلُواْ\nٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ\nفَتَنقَلِبُواْ خَٰسِرِينَ\u{a0}٢١\u{2} \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ\nوَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا\nفَإِنَّا دَٰخِلُونَ\u{a0}٢٢\u{2}     \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ\nأَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ\nفَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ\u{a0}٢٣\n\u{2}    \n       \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ رَبِّ\nإِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ\nٱلۡفَٰسِقِينَ\u{a0}٢٥\u{2} \n         \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا\nفَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ\nقَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ\u{a0}٢٧\u{2}        \n        \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّمَا\nجَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ\nفَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ\nوَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ\nلَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ\u{a0}٣٣\n\u{2}\n       \n       \n       \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ\nلَعَلَّكُمۡ تُفۡلِحُونَ\u{a0}٣٥\u{2}  \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ\nلَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ\nعَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ\u{a0}٣٦\n\u{2}    \n         \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}3\u{2}وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ\nأَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ\u{a0}٣٨\n\u{2}  \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ\nعَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ\u{a0}٣٩\u{2}        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ\nوَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٤٠\u{2}     \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ يَٰٓأَيُّهَا ٱلرَّسُولُ\nلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ\nقَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ\nهَادُواْۛ سَمَّٰعُونَ لِلۡكَذِبِ سَمَّٰعُونَ لِقَوۡمٍ\nءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ\nيَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ\nوَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ\nأُوْلَٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي\nٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ\u{a0}٤١\n\u{2} \n       \n       \n    \n       \n        \n         \n         \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ\nٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ\nوَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ\u{a0}٤٣\u{2}  \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا\nهُدٗى وَنُورٞۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ\nهَادُواْ وَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ\nٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ\nوَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ وَمَن لَّمۡ يَحۡكُم\nبِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ\u{a0}٤٤\u{2}   \n       \n      \n      \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَكَتَبۡنَا عَلَيۡهِمۡ\nفِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ\nبِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ\nقِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ وَمَن\nلَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ\u{a0}٤٥\n\u{2} \n      \n     \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ\nٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ\nيَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ\u{a0}٤٦\u{2}          \n        \n     \u{a0}\u{1}\u{2}3\u{2}\u{2}وَلۡيَحۡكُمۡ\nأَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ\nٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ\u{a0}٤٧\u{2}\n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ\nبِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا\nعَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ\nعَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ\nوَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ\nءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا\nفَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ\u{a0}٤٨\u{2}  \n       \n        \n        \n         \n      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ\nأَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ\nبَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم\nبِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ\u{a0}٤٩\u{2}   \n        \n            \n      \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ\nأَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ\nٱلظَّٰلِمِينَ\u{a0}٥١\u{2}        \n           \n\u{a0}\u{1}'
    '\u{2}\u{2}\u{2}فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ\nيَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ\nمِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ\u{a0}٥٢\n\u{2}      \n           \n        \u{a0}\n\u{1}\u{2}6\u{2}\u{2}وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ\nإِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ\u{a0}٥٣\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا\nٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ\nوَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي\nسَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ\nوَٱللَّهُ وَٰسِعٌ عَلِيمٌ\u{a0}٥٤\u{2}\n           \n        \n           \n  \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ\nيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ\u{a0}٥٥\u{2}      \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن يَتَوَلَّ ٱللَّهَ\nوَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ\u{a0}٥٦\u{2}  \n       \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ\nٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ\u{a0}٥٧\n\u{2} \n          \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا\nبِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ\u{a0}٥٩\u{2}        \n          \u{a0}\u{1}\u{2}3\u{2}\u{2}قُلۡ\nهَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ\nعَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَۚ أُوْلَٰٓئِكَ شَرّٞ\nمَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ\u{a0}٦٠\u{2}\n           \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا\nوَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ\u{a0}٦١\n\u{2}   \n           \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ\nبِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا\nمِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ\nوَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ\nوَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ\u{a0}٦٤\n\u{2}       \n         \n          \n         \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡ أَنَّهُمۡ أَقَامُواْ\nٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن\nفَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ\nسَآءَ مَا يَعۡمَلُونَ\u{a0}٦٦\u{2}  \n        \n        \n  \u{a0}\u{1}\u{2}\u{2}7\u{2}۞ يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ\nمِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ\nمِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ\u{a0}٦٧\u{2}     \n         \n       \u{a0}\u{1}\u{2}7\u{2}10\u{2}قُلۡ يَٰٓأَهۡلَ\nٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ\nوَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ\nإِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ\u{a0}٦٨\n\u{2} \n       \n         \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ\nمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَا خَوۡفٌ\nعَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ\u{a0}٦٩\u{2}      \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}لَقَدۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ\nإِسۡرَٰٓءِيلَ وَأَرۡسَلۡنَآ إِلَيۡهِمۡ رُسُلٗاۖ كُلَّمَا جَآءَهُمۡ رَسُولُۢ بِمَا\nلَا تَهۡوَىٰٓ أَنفُسُهُمۡ فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ\u{a0}٧٠\n\u{2}   \n       \n      \u{a0}\n\u{1}\u{2}\u{2}3\u{2}وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ\nعَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا\nيَعۡمَلُونَ\u{a0}٧١\u{2}        \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ\nٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱعۡبُدُواْ\nٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ\nٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ\u{a0}٧٢\n\u{2}      \n       \n          \n      \u{a0}\n\u{1}\u{2}7\u{2}9\u{2}لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٖۘ وَمَا مِنۡ\nإِلَٰهٍ إِلَّآ إِلَٰهٞ وَٰحِدٞۚ وَإِن لَّمۡ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ\nٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ\u{a0}٧٣\u{2}         \n         \n    \u{a0}\u{1}\u{2}\u{2}10\u{2}أَفَلَا يَتُوبُونَ\nإِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ\u{a0}٧٤\n\u{2} \n     \u{a0}\n\u{1}\u{2}11\u{2}14\u{2}مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ\nٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ\nٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ\nيُؤۡفَكُونَ\u{a0}٧٥\u{2}         \n     \n       \n\u{a0}\u{1}\u{2}14\u{2}15\u{2}قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا\nيَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\u{a0}٧٦\n\u{2}      \n        \u{a0}\n\u{1}121\u{2}1\u{2}3\u{2}قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ غَيۡرَ ٱلۡحَقِّ\nوَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ\nكَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ\u{a0}٧٧\u{2}        \n        \n    \u{a0}\u{1}\u{2}3\u{2}5\u{2}لُعِنَ ٱلَّذِينَ\nكَفَرُواْ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى\nٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ\u{a0}٧٨\n\u{2} \n       \n      \u{a0}\n\u{1}\u{2}6\u{2}7\u{2}كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ\nمَا كَانُواْ يَفۡعَلُونَ\u{a0}٧٩\u{2}      \n  \u{a0}\u{1}\u{2}7\u{2}9\u{2}تَرَىٰ كَثِيرٗا مِّنۡهُمۡ\nيَتَوَلَّوۡنَ ٱلَّذِينَ كَفَرُواْۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ\nأَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ وَفِي ٱلۡعَذَابِ هُمۡ خَٰلِدُونَ\u{a0}٨٠\n\u{2}  \n       \n       \u{a0}\n\u{1}\u{2}10\u{2}11\u{2}وَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ\nمَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ\u{a0}٨١\n\u{2}       \n      \u{a0}\n\u{1}\u{2}12\u{2}15\u{2}۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةٗ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ\nوَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ\nءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ\nقِسِّيسِينَ وَرُهۡبَانٗا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ\u{a0}٨٢\n\u{2}      \n     \n       \n    \u{a0}\n\u{1}122\u{2}1\u{2}3\u{2}وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ\nٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ\nٱلشَّٰهِدِينَ\u{a0}٨٣\u{2}         \n         \n\u{a0}\u{1}\u{2}3\u{2}4\u{2}وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلۡحَقِّ\nوَنَطۡمَعُ أَن يُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّٰلِحِينَ\u{a0}٨٤\u{2}        \n      \u{a0}\u{1}\u{2}4\u{2}6\u{2}فَأَثَٰبَهُمُ\nٱللَّهُ بِمَا قَالُواْ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ\nوَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ\u{a0}٨٥\u{2}\n         \n  \u{a0}\u{1}\u{2}6\u{2}7\u{2}وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ\nبِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ\u{a0}٨٦\u{2}  \n   \u{a0}\u{1}\u{2}7\u{2}9\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nلَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ\nلَا يُحِبُّ ٱلۡمُعۡتَدِينَ\u{a0}٨٧\u{2}  \n          \n  \u{a0}\u{1}\u{2}9\u{2}10\u{1}\u{2}10\u{2}15\u{1}123\u{2}1\u{2}2\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ\nمِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ\u{a0}٩٠\u{2}        \n     \u{a0}\u{1}\u{2}2\u{2}4\u{2}إِنَّمَا يُرِيدُ\nٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ\nوَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ\u{a0}٩١\u{2} \n        \n        \u{a0}\u{1}\u{2}4\u{2}6\u{2}وَأَطِيعُواْ\nٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ\nرَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ\u{a0}٩٢\u{2}\n        \n  \u{a0}\u{1}\u{2}6\u{2}\u{2}لَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nٱلصَّٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ\nٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ\u{a0}٩٣\n\u{2}    \n        \n         \u{a0}\n\u{1}\u{2}9\u{2}11\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ\nأَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ\nذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ\u{a0}٩٤\u{2}        \n         \n   \u{a0}\u{1}\u{2}11\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡتُلُواْ ٱلصَّيۡدَ\nوَأَنتُمۡ حُرُمٞۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدٗا فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ\nيَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ مِّنكُمۡ هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّٰرَةٞ طَعَامُ\nمَسَٰكِينَ أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا لِّيَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا\nسَلَفَۚ وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ\u{a0}٩٥\n\u{2}     \n           \n          \n          \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ\nعَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ\nتُحۡشَرُونَ\u{a0}٩٦\u{2}        \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}۞ جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ\nقِيَٰمٗا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡيَ وَٱلۡقَلَٰٓئِدَۚ ذَٰلِكَ لِتَعۡلَمُوٓاْ\nأَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ\nشَيۡءٍ عَلِيمٌ\u{a0}٩٧\u{2}    \n       \n           \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَسۡـَٔلُواْ\nعَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُواْ عَنۡهَا حِينَ يُنَزَّلُ\nٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ\u{a0}١٠١\u{2}    \n          \n        \u{a0}\u{1}\u{2}12\u{2}\u{2}قَدۡ\nسَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ\u{a0}١٠٢\n\u{2}\n       \u{a0}\n\u{1}\u{2}14\u{2}\u{2}مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٖ وَلَا سَآئِبَةٖ وَلَا وَصِيلَةٖ وَلَا حَامٖ وَلَٰكِنَّ\nٱلَّذِينَ كَفَرُواْ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِلُونَ\u{a0}١٠٣\n\u{2}           \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُواْ\nحَسۡبُنَا مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡلَمُونَ\nشَيۡـٔٗا وَلَا يَهۡتَدُونَ\u{a0}١٠٤\u{2}          \n         \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ\nبَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ ٱثۡنَانِ ذَوَا\nعَدۡلٖ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ\nفَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ\nفَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ\nوَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ\u{a0}١٠٦\u{2}   \n        \n          \n      \n           \n       \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِنۡ عُثِرَ عَلَىٰٓ\nأَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمٗا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ\nٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ فَيُقۡسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ\nمِن شَهَٰدَتِهِمَا وَمَا ٱعۡتَدَيۡنَآ إِنَّآ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ\u{a0}١٠٧\u{2}  \n       \n      \n       \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ\nأَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَٰدَةِ عَلَىٰ وَجۡهِهَآ أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَٰنُۢ بَعۡدَ\nأَيۡمَٰنِهِمۡۗ وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ\u{a0}١٠٨\n\u{2}\n           \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ يَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ\nلَنَآۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ\u{a0}١٠٩\u{2}         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ\nٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ\nٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ\nٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ\nمِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا\nبِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ\nٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَٰٓءِيلَ عَنكَ إِذۡ\nجِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ\nمُّبِينٞ\u{a0}١١٠\u{2}     \n       \n       \n     \n        \n      \n       \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي\nوَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ\u{a0}١١١\u{2}      \n     \u{a0}\u{1}'
    '\u{2}11\u{2}\u{2}إِذۡ قَالَ\nٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن\nيُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم\nمُّؤۡمِنِينَ\u{a0}١١٢\u{2} \n       \n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي\nوَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ\nأَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي\nنَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ\u{a0}١١٦\u{2}         \n          \n            \n         \u{a0}\u{1}\u{2}\u{2}\u{2}مَا\nقُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ\nعَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ\nعَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ\u{a0}١١٧\u{2}\n           \n         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ\nوَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}١١٨\u{2}   \n      \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ ٱللَّهُ هَٰذَا يَوۡمُ\nيَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ\nخَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}١١٩\n\u{2}   \n        \n          \u{a0}\n\u{1}\u{2}15\u{2}\u{2}لِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا فِيهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرُۢ\u{a0}١٢٠\n\u{2}          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَقَدۡ كَذَّبُواْ بِٱلۡحَقِّ\nلَمَّا جَآءَهُمۡ فَسَوۡفَ يَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\u{a0}٥\u{2}  \n        \u{a0}\u{1}\u{2}9\u{2}\u{2}أَلَمۡ\nيَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ\nنُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ\nتَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا\nءَاخَرِينَ\u{a0}٦\u{2}\n           \n       \n        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ\nبِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\u{a0}١٠\n\u{2}     \n      \u{a0}\n\u{1}\u{2}4\u{2}5\u{2}قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ\nٱلۡمُكَذِّبِينَ\u{a0}١١\u{2}        \n\u{a0}\u{1}\u{2}\u{2}\u{2}قُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ\nكَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ\nلَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ\u{a0}١٢\n\u{2}       \n       \n        \u{a0}\n\u{1}\u{2}8\u{2}\u{2}۞ وَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\u{a0}١٣\n\u{2}        \u{a0}\n\u{1}\u{2}9\u{2}\u{2}قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ\nوَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا\nتَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ\u{a0}١٤\u{2}         \n          \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}مَّن يُصۡرَفۡ عَنۡهُ يَوۡمَئِذٖ فَقَدۡ\nرَحِمَهُۥۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِينُ\u{a0}١٦\u{2}    \n   \u{a0}\u{1}\u{2}\u{2}15\u{2}وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ\nفَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ\nقَدِيرٞ\u{a0}١٧\u{2}   \n           \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا\nٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ\nءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِي بَرِيٓءٞ مِّمَّا\nتُشۡرِكُونَ\u{a0}١٩\u{2}            \n         \n            \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ\nأَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ\u{a0}٢٠\u{2}     \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَنۡ أَظۡلَمُ\nمِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ\u{a0}٢١\n\u{2} \n           \u{a0}\n\u{1}\u{2}7\u{2}8\u{2}وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُوٓاْ أَيۡنَ شُرَكَآؤُكُمُ\nٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ\u{a0}٢٢\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}9\u{2}ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ\nرَبِّنَا مَا كُنَّا مُشۡرِكِينَ\u{a0}٢٣\u{2}       \n   \u{a0}\u{1}\u{2}\u{2}10\u{2}ٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ\nعَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ\u{a0}٢٤\u{2}     \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ\nقُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ\nلَّا يُؤۡمِنُواْ بِهَاۖ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ\nإِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ\u{a0}٢٥\u{2}     \n          \n           \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن\nيُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ\u{a0}٢٦\u{2}     \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَى ٱلنَّارِ\nفَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ\u{a0}٢٧\n\u{2}     \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا\nلَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ\u{a0}٣٢\n\u{2}   \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيۡهِ\nيُرۡجَعُونَ\u{a0}٣٦\u{2}        \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكۡمٞ فِي ٱلظُّلُمَٰتِۗ مَن يَشَإِ ٱللَّهُ\nيُضۡلِلۡهُ وَمَن يَشَأۡ يَجۡعَلۡهُ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ\u{a0}٣٩\u{2}         \n      \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}بَلۡ إِيَّاهُ تَدۡعُونَ فَيَكۡشِفُ مَا\nتَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ\u{a0}٤١\u{2}    \n      \u{a0}\u{1}\u{2}\u{2}11\u{2}وَلَقَدۡ أَرۡسَلۡنَآ\nإِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ\u{a0}٤٢\n\u{2} \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ\nوَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ\u{a0}٤٣\u{2}       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَلَمَّا\nنَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ\nحَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ\u{a0}٤٤\n\u{2}\n        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ\nإِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمۡ يَتَّقُونَ\u{a0}٥١\n\u{2}     \n          \u{a0}\n\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ\nأَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ\u{a0}٥٦\n\u{2}            \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُلۡ إِنِّي عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا\nتَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ\nٱلۡفَٰصِلِينَ\u{a0}٥٧\u{2}          \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ\nٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّٰلِمِينَ\u{a0}٥٨\n\u{2}       \n     \u{a0}\n\u{1}\u{2}13\u{2}\u{2}۞ وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي\nٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ\nفِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ\u{a0}٥٩\n\u{2}         \n         \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ\nيَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلٞ مُّسَمّٗىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ\nثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\u{a0}٦٠\u{2}        \n       \n    \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ مَن يُنَجِّيكُم مِّن\nظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ\nلَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ\u{a0}٦٣\u{2}   \n         \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا\nمِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم\nبَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ\u{a0}٦٥\n\u{2}       \n          \n       \u{a0}\n\u{1}\u{2}12\u{2}\u{2}وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلٖ\u{a0}٦٦\u{2}        \u{a0}\u{1}\u{2}\u{2}\u{2}لِّكُلِّ\nنَبَإٖ مُّسۡتَقَرّٞۚ وَسَوۡفَ تَعۡلَمُونَ\u{a0}٦٧\u{2}\n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ\nءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ\nٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ\u{a0}٦٨\n\u{2}    \n         \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ\nدِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ\nأَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيّٞ\nوَلَا شَفِيعٞ وَإِن تَعۡدِلۡ كُلَّ عَدۡلٖ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَٰٓئِكَ\nٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ\nأَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ\u{a0}٧٠\u{2}  \n       \n          \n         \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ\nمَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ\nكَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ\nيَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ\nوَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ\u{a0}٧١\u{2}    \n           \n       \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ\nوَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ\u{a0}٧٢\u{2}  \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي\nخَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن\nفَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ\nعَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ\u{a0}٧٣\n\u{2} \n      \n        \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ\nأَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ\u{a0}٧٤\u{2}        \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ\nلَآ أُحِبُّ ٱلۡأٓفِلِينَ\u{a0}٧٦\u{2}           \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا\nتَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ\nسُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ\u{a0}٨١\n\u{2}    \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا\nهَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ\nوَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ\u{a0}٨٤\n\u{2}      \n       \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}13\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ\nفَإِن يَكۡفُرۡ بِهَا هَٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ\u{a0}٨٩\n\u{2}     \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ\nأَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ\u{a0}٩٠\n\u{2}       \n       \u{a0}\n\u{1}\u{2}\u{2}4\u{2}وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ\nقُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورٗا وَهُدٗى لِّلنَّاسِۖ\nتَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرٗاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ\nأَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ\u{a0}٩١\n\u{2}             \n          \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ\nأُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ\nوَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ\u{a0}٩٢\u{2}        \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى\nٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ\nمِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ\nوَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ\nتُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ\nوَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ\u{a0}٩٣\u{2}    \n            \n          \n     \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ\nكَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ\nوَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَٰٓؤُاْۚ\nلَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ\u{a0}٩٤\n\u{2}  \n        \n        \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ\nٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ\u{a0}٩٥\u{2}         \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِيٓ أَنزَلَ\nمِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ\nخَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا\nقِنۡوَانٞ دَانِيَةٞ وَجَنَّٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا\nوَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ\nلَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ\u{a0}٩٩\u{2}  \n         \n        \n       \n          \n  \u{a0}\u{1}\u{2}\u{2}14\u{2}وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ\nوَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا\nيَصِفُونَ\u{a0}١٠٠\u{2}    \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ\nوَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ\u{a0}١٠١\n\u{2}      \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ\nفَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ\u{a0}١٠٢\u{2}         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}لَّا تُدۡرِكُهُ\nٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ\u{a0}١٠٣\n\u{2} \n      \u{a0}\n\u{1}\u{2}4\u{2}\u{2}قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ\nفَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ\u{a0}١٠٤\u{2}         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَكَذَٰلِكَ نُصَرِّفُ\nٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمٖ يَعۡلَمُونَ\u{a0}١٠٥\n\u{2} \n     \u{a0}\n\u{1}\u{2}7\u{2}8\u{2}ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ\nٱلۡمُشۡرِكِينَ\u{a0}١٠٦\u{2}           \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ\nحَفِيظٗاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ\u{a0}١٠٧\u{2}       \n    \u{a0}\u{1}\u{2}\u{2}12\u{2}وَلَا تَسُبُّواْ ٱلَّذِينَ\nيَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ كَذَٰلِكَ زَيَّنَّا\nلِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ\nيَعۡمَلُونَ\u{a0}١٠٨\u{2}  \n          \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةٞ\nلَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا\nجَآءَتۡ لَا يُؤۡمِنُونَ\u{a0}١٠٩\u{2}      \n          \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا\nعَلَيۡهِمۡ كُلَّ شَيۡءٖ قُبُلٗا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ\nأَكۡثَرَهُمۡ يَجۡهَلُونَ\u{a0}١١١\u{2}       \n           \n \u{a0}\u{1}'
    '\u{2}\u{2}5\u{2}وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا\nشَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ\nٱلۡقَوۡلِ غُرُورٗاۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ\u{a0}١١٢\n\u{2}    \n       \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَفَغَيۡرَ ٱللَّهِ\nأَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ\nوَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ\nفَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ\u{a0}١١٤\u{2} \n       \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا\nوَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\u{a0}١١٥\u{2}   \n      \u{a0}\u{1}\u{2}11\u{2}\u{2}وَإِن\nتُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن\nيَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ\u{a0}١١٦\u{2}\n         \n      \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ رَبَّكَ هُوَ\nأَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ\u{a0}١١٧\n\u{2}  \n       \u{a0}\n\u{1}\u{2}15\u{2}\u{2}فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ\u{a0}١١٨\n\u{2}         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ\nلَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ\nبِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ\u{a0}١١٩\n\u{2}          \n          \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ\nٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ\nأَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ\u{a0}١٢١\n\u{2}    \n        \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا يَمۡشِي بِهِۦ فِي\nٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجٖ مِّنۡهَاۚ كَذَٰلِكَ\nزُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ\u{a0}١٢٢\u{2}         \n        \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا جَآءَتۡهُمۡ\nءَايَةٞ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ\nأَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ\nصَغَارٌ عِندَ ٱللَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ\u{a0}١٢٤\n\u{2} \n           \n      \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ\nأَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ\nفِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ\nلَا يُؤۡمِنُونَ\u{a0}١٢٥\u{2}         \n       \n       \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ\nوَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ\u{a0}١٢٧\u{2}    \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا\nيَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم\nمِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٖ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ\nأَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ\nرَبَّكَ حَكِيمٌ عَلِيمٞ\u{a0}١٢٨\u{2}  \n       \n        \n           \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا\nبِمَا كَانُواْ يَكۡسِبُونَ\u{a0}١٢٩\u{2}    \n  \u{a0}\u{1}\u{2}11\u{2}14\u{2}يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ\nرُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ\nيَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا\nوَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ\u{a0}١٣٠\u{2}    \n      \n        \n     \u{a0}\u{1}144\u{2}14\u{2}15\u{2}ذَٰلِكَ\nأَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا غَٰفِلُونَ\u{a0}١٣١\n\u{2}\n        \u{a0}\n\u{1}\u{2}1\u{2}2\u{2}وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا\nيَعۡمَلُونَ\u{a0}١٣٢\u{2}       \n\u{a0}\u{1}\u{2}2\u{2}4\u{2}وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ\nيُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ\nأَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ\u{a0}١٣٣\u{2}     \n      \n    \u{a0}\u{1}\u{2}4\u{2}5\u{2}إِنَّ مَا\nتُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعۡجِزِينَ\u{a0}١٣٤\u{2} \n    \u{a0}\u{1}\u{2}5\u{2}7\u{1}\u{2}8\u{2}\u{2}وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ\nنَصِيبٗا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ\nفَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ\nوَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ\nسَآءَ مَا يَحۡكُمُونَ\u{a0}١٣٦\u{2}      \n      \n      \n      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَكَذَٰلِكَ زَيَّنَ\nلِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ\nشُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ\nوَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ\u{a0}١٣٧\n\u{2} \n    \n    \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمٞ وَحَرۡثٌ حِجۡرٞ لَّا يَطۡعَمُهَآ إِلَّا مَن\nنَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمٞ لَّا يَذۡكُرُونَ\nٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ\nيَفۡتَرُونَ\u{a0}١٣٨\u{2}        \n       \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ\nخَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن\nمَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ\nحَكِيمٌ عَلِيمٞ\u{a0}١٣٩\u{2}     \n      \n      \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ\nسَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ\nقَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ\u{a0}١٤٠\u{2}    \n         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَهُوَ ٱلَّذِيٓ\nأَنشَأَ جَنَّٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ\nمُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ\nمُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ\nحَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ\u{a0}١٤١\n\u{2} \n      \n     \n        \n      \u{a0}\n\u{1}\u{2}14\u{2}\u{2}وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ\nٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ\u{a0}١٤٢\n\u{2}      \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُل لَّآ أَجِدُ\nفِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ\nمَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ\nفِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ\nرَبَّكَ غَفُورٞ رَّحِيمٞ\u{a0}١٤٥\u{2}  \n          \n         \n           \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا\nكُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ\nشُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا\nٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ\u{a0}١٤٦\n\u{2}   \n       \n        \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ\nيَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ\nمَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ\nلَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ\u{a0}١٥٠\u{2}   \n        \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}۞ قُلۡ\nتَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ\nشَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ\nإِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ\nمَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي\nحَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ\u{a0}١٥١\n\u{2}\n        \n      \n      \n        \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ\nعَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ\u{a0}١٥٦\n\u{2}    \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ\nفَقَدۡ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞۚ فَمَنۡ\nأَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ\nيَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ\u{a0}١٥٧\n\u{2}         \n       \n        \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ\nبَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا\nلَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ\nإِنَّا مُنتَظِرُونَ\u{a0}١٥٨\u{2}          \n           \n           \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ\nمِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ\u{a0}١٥٩\n\u{2}      \n           \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ\nإِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ\nٱلۡمُشۡرِكِينَ\u{a0}١٦١\u{2}   \n          \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ\nنَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ\nفَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ\u{a0}١٦٤\u{2}           \n           \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي جَعَلَكُمۡ\nخَلَٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَبۡلُوَكُمۡ\nفِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ\u{a0}١٦٥\n\u{2}  \n       \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}6\u{2}وَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ\u{a0}٤\n\u{2}         \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا\nظَٰلِمِينَ\u{a0}٥\u{2}          \n\u{a0}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ\nلِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّٰجِدِينَ\u{a0}١١\n\u{2}       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَوَسۡوَسَ\nلَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ\nمَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا\nمِنَ ٱلۡخَٰلِدِينَ\u{a0}٢٠\u{2}\n         \n           \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا\nيَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا\nعَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ\u{a0}٢٢\n\u{2}        \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ\nٱلۡخَٰسِرِينَ\u{a0}٢٣\u{2}          \n\u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي\nٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ\u{a0}٢٤\u{2}      \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسٗا\nيُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشٗاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ ذَٰلِكَ مِنۡ\nءَايَٰتِ ٱللَّهِ لَعَلَّهُمۡ يَذَّكَّرُونَ\u{a0}٢٦\u{2}     \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰبَنِيٓ ءَادَمَ لَا يَفۡتِنَنَّكُمُ\nٱلشَّيۡطَٰنُ كَمَآ أَخۡرَجَ أَبَوَيۡكُم مِّنَ ٱلۡجَنَّةِ يَنزِعُ عَنۡهُمَا لِبَاسَهُمَا\nلِيُرِيَهُمَا سَوۡءَٰتِهِمَآۚ إِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ\nإِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ\u{a0}٢٧\u{2}   \n        \n         \n      \u{a0}\u{1}\u{2}9\u{2}\u{2}وَإِذَا فَعَلُواْ\nفَٰحِشَةٗ قَالُواْ وَجَدۡنَا عَلَيۡهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ\nلَا يَأۡمُرُ بِٱلۡفَحۡشَآءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ\u{a0}٢٨\u{2} \n          \n        \u{a0}\u{1}\u{2}11\u{2}\u{2}قُلۡ\nأَمَرَ رَبِّي بِٱلۡقِسۡطِۖ وَأَقِيمُواْ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدٖ\nوَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ\u{a0}٢٩\u{2}\n       \n      \u{a0}\u{1}\u{2}13\u{2}\u{2}فَرِيقًا\nهَدَىٰ وَفَرِيقًا حَقَّ عَلَيۡهِمُ ٱلضَّلَٰلَةُۚ إِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ\nأَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ\u{a0}٣٠\n\u{2}\n       \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ\nوَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ\u{a0}٣١\u{2}        \n     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا\nبَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ\nسُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ\u{a0}٣٣\u{2}        \n           \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَلِكُلِّ أُمَّةٍ أَجَلٞۖ\nفَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ\u{a0}٣٤\n\u{2}  \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ\nكَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ\nفِيهَا خَٰلِدُونَ\u{a0}٣٦\u{2}\n       \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ ٱدۡخُلُواْ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ\nفِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةٞ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا\nجَمِيعٗا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ\nعَذَابٗا ضِعۡفٗا مِّنَ ٱلنَّارِۖ قَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ\u{a0}٣٨\n\u{2}          \n          \n       \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ كَذَّبُواْ\nبِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ\nٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي\nٱلۡمُجۡرِمِينَ\u{a0}٤٠\u{2}  \n         \n        \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ\nٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ\u{a0}٤٢\u{2}  \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلّٖ\nتَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا\nوَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ\nوَنُودُوٓاْ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ\u{a0}٤٣\n\u{2}     \n         \n           \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقّٗا\nفَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن\nلَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ\u{a0}٤٤\u{2}           \n           \n   \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا\nعِوَجٗا وَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ\u{a0}٤٥\u{2}     \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ\nرِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ\nلَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ\u{a0}٤٦\u{2}   \n  \u{3}       \n   \u{a0}\u{1}\u{2}6\u{2}7\u{2}۞ وَإِذَا صُرِفَتۡ أَبۡصَٰرُهُمۡ تِلۡقَآءَ\nأَصۡحَٰبِ ٱلنَّارِ قَالُواْ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ\u{a0}٤٧\u{2}   \n        \u{a0}\u{1}\u{2}7\u{2}\u{2}وَنَادَىٰٓ أَصۡحَٰبُ\nٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ\nوَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ\u{a0}٤٨\u{2} \n        \n  \u{a0}\u{1}\u{2}9\u{2}10\u{2}أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ\nٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُواْ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَلَآ أَنتُمۡ تَحۡزَنُونَ\u{a0}٤٩\n\u{2}    \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا\nمِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى\nٱلۡكَٰفِرِينَ\u{a0}٥٠\u{2}       \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَهۡوٗا وَلَعِبٗا\nوَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُواْ\nلِقَآءَ يَوۡمِهِمۡ هَٰذَا وَمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ\u{a0}٥١\n\u{2}    \n      \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبٖ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ هُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ\nيُؤۡمِنُونَ\u{a0}٥٢\u{2}        \n\u{a0}\u{1}\u{2}\u{2}5\u{2}هَلۡ يَنظُرُونَ إِلَّا تَأۡوِيلَهُۥۚ يَوۡمَ يَأۡتِي تَأۡوِيلُهُۥ يَقُولُ\nٱلَّذِينَ نَسُوهُ مِن قَبۡلُ قَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا\nمِن شُفَعَآءَ فَيَشۡفَعُواْ لَنَآ أَوۡ نُرَدُّ فَنَعۡمَلَ غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ\nقَدۡ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ\u{a0}٥٣\n\u{2}       \n          \n          \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ\nأَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثٗا\nوَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ أَلَا لَهُ ٱلۡخَلۡقُ\nوَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ\u{a0}٥٤\u{2}        \n         \n       \n    \u{a0}\u{1}\u{2}9\u{2}\u{2}ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا\nوَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ\u{a0}٥٥\u{2}  \n    \u{a0}\u{1}\u{2}10\u{2}\u{2}وَلَا تُفۡسِدُواْ فِي\nٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا وَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ\nٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ\u{a0}٥٦\u{2}  \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي يُرۡسِلُ\nٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۖ حَتَّىٰٓ إِذَآ أَقَلَّتۡ سَحَابٗا\nثِقَالٗا سُقۡنَٰهُ لِبَلَدٖ مَّيِّتٖ فَأَنزَلۡنَا بِهِ ٱلۡمَآءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ\nٱلثَّمَرَٰتِۚ كَذَٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ\u{a0}٥٧\n\u{2}  \n        \n          \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ\nيَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ\u{a0}٦١\n\u{2}\n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ\nرَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡ وَلِتَتَّقُواْ وَلَعَلَّكُمۡ تُرۡحَمُونَ\u{a0}٦٣\u{2}      \n     \u{a0}\u{1}\u{2}9\u{2}\u{2}فَكَذَّبُوهُ\nفَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ\nبِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ\u{a0}٦٤\u{2}\n       \n    \u{a0}\u{1}\u{2}\u{2}12\u{2}۞ وَإِلَىٰ عَادٍ أَخَاهُمۡ\nهُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ\u{a0}٦٥\n\u{2}  \n           \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي\nسَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ\u{a0}٦٦\u{2}        \n    \u{a0}\u{1}'
    '\u{2}14\u{2}\u{2}قَالَ يَٰقَوۡمِ\nلَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ\u{a0}٦٧\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَوَعَجِبۡتُمۡ\nأَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ\nوَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ\nفِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ\u{a0}٦٩\n\u{2}\n        \n        \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ\nيَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ\u{a0}٧٠\n\u{2}       \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ\nمَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن\nرَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ\nفِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ\u{a0}٧٣\n\u{2}       \n        \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ\nفِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ\nٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ\nمُفۡسِدِينَ\u{a0}٧٤\u{2}       \n      \n        \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ\nأَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ\nٱلۡمُرۡسَلِينَ\u{a0}٧٧\u{2}   \n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ\nإِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ\u{a0}٨٣\u{2} \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَمۡطَرۡنَا عَلَيۡهِم\nمَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ\u{a0}٨٤\n\u{2} \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ\nمَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن\nرَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ\nٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ\nإِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ\u{a0}٨٥\n\u{2}       \n        \n     \n      \n      \u{a0}\n\u{1}\u{2}10\u{2}\u{2}وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ\nعَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ\nوَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ\nكَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ\u{a0}٨٦\u{2}     \n       \n     \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِن كَانَ طَآئِفَةٞ\nمِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ\nفَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ\u{a0}٨٧\n\u{2}  \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ\nوَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ\nكُنَّا كَٰرِهِينَ\u{a0}٨٨\u{2}       \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم\nبَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ\nٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ\nبَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ\u{a0}٨٩\u{2}        \n             \n           \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلۡمَلَأُ\nٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ\u{a0}٩٠\n\u{2} \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ\u{a0}٩١\n\u{2}     \u{a0}\n\u{1}\u{2}9\u{2}\u{2}ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا\nكَانُواْ هُمُ ٱلۡخَٰسِرِينَ\u{a0}٩٢\u{2}         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ\nأَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ\nعَلَىٰ قَوۡمٖ كَٰفِرِينَ\u{a0}٩٣\u{2}    \n      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّبِيٍّ إِلَّآ\nأَخَذۡنَآ أَهۡلَهَا بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَضَّرَّعُونَ\u{a0}٩٤\u{2}      \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ\nبَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَواْ وَّقَالُواْ قَدۡ مَسَّ\nءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذۡنَٰهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ\u{a0}٩٥\n\u{2}\n        \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا بَيَٰتٗا\nوَهُمۡ نَآئِمُونَ\u{a0}٩٧\u{2}      \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا\nضُحٗى وَهُمۡ يَلۡعَبُونَ\u{a0}٩٨\u{2}     \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَفَأَمِنُواْ مَكۡرَ ٱللَّهِۚ فَلَا يَأۡمَنُ\nمَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ\u{a0}٩٩\u{2}    \n    \u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَهۡدِ لِلَّذِينَ\nيَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَآ أَن لَّوۡ نَشَآءُ أَصَبۡنَٰهُم\nبِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَعُونَ\u{a0}١٠٠\n\u{2}  \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}تِلۡكَ ٱلۡقُرَىٰ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآئِهَاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُهُم\nبِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ مِن قَبۡلُۚ\nكَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلۡكَٰفِرِينَ\u{a0}١٠١\u{2}        \n       \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم\nبِبَيِّنَةٖ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِيَ بَنِيٓ إِسۡرَٰٓءِيلَ\u{a0}١٠٥\u{2}          \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}14\u{2}۞ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِيَ تَلۡقَفُ مَا\nيَأۡفِكُونَ\u{a0}١١٧\u{2}         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ\nفِرۡعَوۡنُ ءَامَنتُم بِهِۦ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّ هَٰذَا لَمَكۡرٞ مَّكَرۡتُمُوهُ\nفِي ٱلۡمَدِينَةِ لِتُخۡرِجُواْ مِنۡهَآ أَهۡلَهَاۖ فَسَوۡفَ تَعۡلَمُونَ\u{a0}١٢٣\u{2}\n          \n      \u{a0}\u{1}\u{2}3\u{2}4\u{2}لَأُقَطِّعَنَّ\nأَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ ثُمَّ لَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ\u{a0}١٢٤\n\u{2}\n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}6\u{2}وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا\nبِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ\u{a0}١٢٦\n\u{2}     \n         \u{a0}\n\u{1}'
    '\u{2}\u{2}\u{2}وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُۥ لِيُفۡسِدُواْ\nفِي ٱلۡأَرۡضِ وَيَذَرَكَ وَءَالِهَتَكَۚ قَالَ سَنُقَتِّلُ أَبۡنَآءَهُمۡ وَنَسۡتَحۡيِۦ\nنِسَآءَهُمۡ وَإِنَّا فَوۡقَهُمۡ قَٰهِرُونَ\u{a0}١٢٧\u{2}        \n       \n   \u{a0}\u{1}\u{2}9\u{2}\u{2}قَالَ مُوسَىٰ لِقَوۡمِهِ\nٱسۡتَعِينُواْ بِٱللَّهِ وَٱصۡبِرُوٓاْۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ يُورِثُهَا مَن\nيَشَآءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ\u{a0}١٢٨\u{2}  \n       \n    \u{a0}\u{1}\u{2}11\u{2}\u{2}قَالُوٓاْ أُوذِينَا\nمِن قَبۡلِ أَن تَأۡتِيَنَا وَمِنۢ بَعۡدِ مَا جِئۡتَنَاۚ قَالَ عَسَىٰ رَبُّكُمۡ\nأَن يُهۡلِكَ عَدُوَّكُمۡ وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ\nفَيَنظُرَ كَيۡفَ تَعۡمَلُونَ\u{a0}١٢٩\u{2} \n          \n     \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ\nيَطَّيَّرُواْ بِمُوسَىٰ وَمَن مَّعَهُۥٓۗ أَلَآ إِنَّمَا طَٰٓئِرُهُمۡ عِندَ ٱللَّهِ وَلَٰكِنَّ\nأَكۡثَرَهُمۡ لَا يَعۡلَمُونَ\u{a0}١٣١\u{2}        \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالُواْ مَهۡمَا تَأۡتِنَا بِهِۦ مِنۡ ءَايَةٖ\nلِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ\u{a0}١٣٢\u{2}     \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَرۡسَلۡنَا عَلَيۡهِمُ\nٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٖ مُّفَصَّلَٰتٖ\nفَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ\u{a0}١٣٣\u{2} \n      \n   \u{a0}\u{1}\u{2}6\u{2}\u{2}وَلَمَّا وَقَعَ عَلَيۡهِمُ\nٱلرِّجۡزُ قَالُواْ يَٰمُوسَى ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَۖ لَئِن\nكَشَفۡتَ عَنَّا ٱلرِّجۡزَ لَنُؤۡمِنَنَّ لَكَ وَلَنُرۡسِلَنَّ مَعَكَ بَنِيٓ\nإِسۡرَٰٓءِيلَ\u{a0}١٣٤\u{2}  \n         \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلرِّجۡزَ إِلَىٰٓ أَجَلٍ\nهُم بَٰلِغُوهُ إِذَا هُمۡ يَنكُثُونَ\u{a0}١٣٥\u{2}     \n    \u{a0}\u{1}\u{2}\u{2}11\u{2}فَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ\nفِي ٱلۡيَمِّ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ\u{a0}١٣٦\n\u{2}  \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ\nٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ\nٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ بِمَا صَبَرُواْۖ وَدَمَّرۡنَا مَا كَانَ\nيَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُواْ يَعۡرِشُونَ\u{a0}١٣٧\n\u{2}     \n       \n        \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتَوۡاْ عَلَىٰ قَوۡمٖ يَعۡكُفُونَ عَلَىٰٓ\nأَصۡنَامٖ لَّهُمۡۚ قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ\nقَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ\u{a0}١٣٨\u{2}        \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٞ مَّا هُمۡ فِيهِ وَبَٰطِلٞ\nمَّا كَانُواْ يَعۡمَلُونَ\u{a0}١٣٩\u{2}      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ أَغَيۡرَ ٱللَّهِ أَبۡغِيكُمۡ إِلَٰهٗا\nوَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَٰلَمِينَ\u{a0}١٤٠\u{2}    \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ أَنجَيۡنَٰكُم\nمِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُقَتِّلُونَ\nأَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن\nرَّبِّكُمۡ عَظِيمٞ\u{a0}١٤١\u{2} \n      \n      \n \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَوَٰعَدۡنَا مُوسَىٰ ثَلَٰثِينَ لَيۡلَةٗ\nوَأَتۡمَمۡنَٰهَا بِعَشۡرٖ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرۡبَعِينَ لَيۡلَةٗۚ وَقَالَ\nمُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخۡلُفۡنِي فِي قَوۡمِي وَأَصۡلِحۡ وَلَا تَتَّبِعۡ\nسَبِيلَ ٱلۡمُفۡسِدِينَ\u{a0}١٤٢\u{2}   \n       \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ\nرَبُّهُۥ قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ قَالَ لَن تَرَىٰنِي وَلَٰكِنِ ٱنظُرۡ\nإِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ\nرَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكّٗا وَخَرَّ مُوسَىٰ صَعِقٗاۚ فَلَمَّآ أَفَاقَ\nقَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ\u{a0}١٤٣\n\u{2}    \n          \n        \n        \n      \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ\nفِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ\nبِهَا وَإِن يَرَوۡاْ سَبِيلَ ٱلرُّشۡدِ لَا يَتَّخِذُوهُ سَبِيلٗا وَإِن يَرَوۡاْ\nسَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ ذَٰلِكَ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا\nوَكَانُواْ عَنۡهَا غَٰفِلِينَ\u{a0}١٤٦\u{2}    \n         \n         \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآءِ\nٱلۡأٓخِرَةِ حَبِطَتۡ أَعۡمَٰلُهُمۡۚ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ\nيَعۡمَلُونَ\u{a0}١٤٧\u{2}   \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَٱتَّخَذَ قَوۡمُ مُوسَىٰ مِنۢ بَعۡدِهِۦ مِنۡ حُلِيِّهِمۡ\nعِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٌۚ أَلَمۡ يَرَوۡاْ أَنَّهُۥ لَا يُكَلِّمُهُمۡ وَلَا يَهۡدِيهِمۡ\nسَبِيلًاۘ ٱتَّخَذُوهُ وَكَانُواْ ظَٰلِمِينَ\u{a0}١٤٨\u{2}      \n          \n   \u{a0}\u{1}\u{2}13\u{2}\u{2}وَلَمَّا سُقِطَ\nفِيٓ أَيۡدِيهِمۡ وَرَأَوۡاْ أَنَّهُمۡ قَدۡ ضَلُّواْ قَالُواْ لَئِن لَّمۡ يَرۡحَمۡنَا\nرَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ\u{a0}١٤٩\n\u{2} \n         \n     \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ رَبِّ ٱغۡفِرۡ لِي وَلِأَخِي وَأَدۡخِلۡنَا فِي\nرَحۡمَتِكَۖ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ\u{a0}١٥١\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ٱتَّخَذُواْ\nٱلۡعِجۡلَ سَيَنَالُهُمۡ غَضَبٞ مِّن رَّبِّهِمۡ وَذِلَّةٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ\nوَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ\u{a0}١٥٢\u{2}  \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ ثُمَّ\nتَابُواْ مِنۢ بَعۡدِهَا وَءَامَنُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ\u{a0}١٥٣\n\u{2}   \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِي\nنُسۡخَتِهَا هُدٗى وَرَحۡمَةٞ لِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَبُونَ\u{a0}١٥٤\u{2}       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱخۡتَارَ\nمُوسَىٰ قَوۡمَهُۥ سَبۡعِينَ رَجُلٗا لِّمِيقَٰتِنَاۖ فَلَمَّآ أَخَذَتۡهُمُ ٱلرَّجۡفَةُ\nقَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَهُم مِّن قَبۡلُ وَإِيَّٰيَۖ أَتُهۡلِكُنَا بِمَا فَعَلَ\nٱلسُّفَهَآءُ مِنَّآۖ إِنۡ هِيَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهۡدِي\nمَن تَشَآءُۖ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ\u{a0}١٥٥\n\u{2}\n       \n          \n          \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ إِنَّا\nهُدۡنَآ إِلَيۡكَۚ قَالَ عَذَابِيٓ أُصِيبُ بِهِۦ مَنۡ أَشَآءُۖ وَرَحۡمَتِي\nوَسِعَتۡ كُلَّ شَيۡءٖۚ فَسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ\nٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ\u{a0}١٥٦\u{2}        \n        \n      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَتَّبِعُونَ\nٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ\nفِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ يَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَيَنۡهَىٰهُمۡ\nعَنِ ٱلۡمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيۡهِمُ\nٱلۡخَبَٰٓئِثَ وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ\nعَلَيۡهِمۡۚ فَٱلَّذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُواْ\nٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ\u{a0}١٥٧\u{2} \n      \n     \n      \n      \n      \n      \u{a0}\u{1}\u{2}10\u{2}\u{2}قُلۡ\nيَٰٓأَيُّهَا ٱلنَّاسُ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡ جَمِيعًا ٱلَّذِي\nلَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ\nفَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِيِّ ٱلۡأُمِّيِّ ٱلَّذِي يُؤۡمِنُ بِٱللَّهِ\nوَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَدُونَ\u{a0}١٥٨\n\u{2}\n       \n         \n       \n   \u{a0}\n\u{1}\u{2}15\u{2}\u{2}وَمِن قَوۡمِ مُوسَىٰٓ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ\u{a0}١٥٩\n\u{2}       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَطَّعۡنَٰهُمُ ٱثۡنَتَيۡ عَشۡرَةَ أَسۡبَاطًا أُمَمٗاۚ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ\nإِذِ ٱسۡتَسۡقَىٰهُ قَوۡمُهُۥٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ\nفَٱنۢبَجَسَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ\nمَّشۡرَبَهُمۡۚ وَظَلَّلۡنَا عَلَيۡهِمُ ٱلۡغَمَٰمَ وَأَنزَلۡنَا عَلَيۡهِمُ ٱلۡمَنَّ\nوَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا\nظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ\u{a0}١٦٠\u{2}       \n      \n        \n      \n      \n    \u{a0}\u{1}\u{2}6\u{2}\u{2}وَإِذۡ\nقِيلَ لَهُمُ ٱسۡكُنُواْ هَٰذِهِ ٱلۡقَرۡيَةَ وَكُلُواْ مِنۡهَا حَيۡثُ\nشِئۡتُمۡ وَقُولُواْ حِطَّةٞ وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا نَّغۡفِرۡ\nلَكُمۡ خَطِيٓـَٰٔتِكُمۡۚ سَنَزِيدُ ٱلۡمُحۡسِنِينَ\u{a0}١٦١\n\u{2}\n       \n      \n   \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ\nفَأَرۡسَلۡنَا عَلَيۡهِمۡ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ\nيَظۡلِمُونَ\u{a0}١٦٢\u{2}        \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ\nحَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ\nحِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ\nلَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ\u{a0}١٦٣\n\u{2}    \n       \n      \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}8\u{2}وَإِذۡ تَأَذَّنَ رَبُّكَ لَيَبۡعَثَنَّ عَلَيۡهِمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَن\nيَسُومُهُمۡ سُوٓءَ ٱلۡعَذَابِۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ\nلَغَفُورٞ رَّحِيمٞ\u{a0}١٦٧\u{2}        \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَطَّعۡنَٰهُمۡ فِي ٱلۡأَرۡضِ أُمَمٗاۖ مِّنۡهُمُ\nٱلصَّٰلِحُونَ وَمِنۡهُمۡ دُونَ ذَٰلِكَۖ وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ\nوَٱلسَّيِّـَٔاتِ لَعَلَّهُمۡ يَرۡجِعُونَ\u{a0}١٦٨\u{2}    \n     \n  \u{a0}\u{1}\u{2}\u{2}\u{2}فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٞ\nوَرِثُواْ ٱلۡكِتَٰبَ يَأۡخُذُونَ عَرَضَ هَٰذَا ٱلۡأَدۡنَىٰ وَيَقُولُونَ سَيُغۡفَرُ لَنَا\nوَإِن يَأۡتِهِمۡ عَرَضٞ مِّثۡلُهُۥ يَأۡخُذُوهُۚ أَلَمۡ يُؤۡخَذۡ عَلَيۡهِم مِّيثَٰقُ ٱلۡكِتَٰبِ\nأَن لَّا يَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُواْ مَا فِيهِۗ وَٱلدَّارُ ٱلۡأٓخِرَةُ\nخَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ\u{a0}١٦٩\u{2}   \n        \n         \n           \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةٞ وَظَنُّوٓاْ أَنَّهُۥ وَاقِعُۢ بِهِمۡ\nخُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ\u{a0}١٧١\n\u{2}         \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَوۡ تَقُولُوٓاْ إِنَّمَآ أَشۡرَكَ\nءَابَآؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّيَّةٗ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ\nٱلۡمُبۡطِلُونَ\u{a0}١٧٣\u{2}   \n         \n\u{a0}\u{1}\u{2}\u{2}7\u{2}وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلَعَلَّهُمۡ يَرۡجِعُونَ\u{a0}١٧٤\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا\nفَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ\u{a0}١٧٥\u{2}       \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِيرٗا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ لَهُمۡ قُلُوبٞ\nلَّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُنٞ لَّا يُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانٞ لَّا يَسۡمَعُونَ\nبِهَآۚ أُوْلَٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ أُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ\u{a0}١٧٩\n\u{2}        \n           \n        \u{a0}\n\u{1}\u{2}4\u{2}\u{2}وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ\nأَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ\u{a0}١٨٠\u{2}        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِمَّنۡ خَلَقۡنَآ أُمَّةٞ\nيَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ\u{a0}١٨١\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا\nسَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ\u{a0}١٨٢\u{2}  \n    \u{a0}\u{1}\u{2}\u{2}8\u{2}وَأُمۡلِي لَهُمۡۚ إِنَّ\nكَيۡدِي مَتِينٌ\u{a0}١٨٣\u{2}  \n \u{a0}\u{1}\u{2}8\u{2}9\u{2}أَوَلَمۡ يَتَفَكَّرُواْۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍۚ إِنۡ\nهُوَ إِلَّا نَذِيرٞ مُّبِينٌ\u{a0}١٨٤\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَنظُرُواْ فِي مَلَكُوتِ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضِ وَمَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ وَأَنۡ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقۡتَرَبَ\nأَجَلُهُمۡۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ\u{a0}١٨٥\u{2}    \n           \n    \u{a0}\u{1}\u{2}\u{2}\u{2}مَن يُضۡلِلِ ٱللَّهُ فَلَا\nهَادِيَ لَهُۥۚ وَيَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ\u{a0}١٨٦\u{2}   \n     \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ\nأَيَّانَ مُرۡسَىٰهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ رَبِّيۖ لَا يُجَلِّيهَا لِوَقۡتِهَآ إِلَّا هُوَۚ ثَقُلَتۡ\nفِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا تَأۡتِيكُمۡ إِلَّا بَغۡتَةٗۗ يَسۡـَٔلُونَكَ كَأَنَّكَ حَفِيٌّ\nعَنۡهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ\u{a0}١٨٧\n\u{2}  \n            \n         \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ وَلَوۡ كُنتُ\nأَعۡلَمُ ٱلۡغَيۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَيۡرِ وَمَا مَسَّنِيَ ٱلسُّوٓءُۚ إِنۡ\nأَنَا۠ إِلَّا نَذِيرٞ وَبَشِيرٞ لِّقَوۡمٖ يُؤۡمِنُونَ\u{a0}١٨٨\u{2}            \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}۞ هُوَ ٱلَّذِي خَلَقَكُم\nمِّن نَّفۡسٖ وَٰحِدَةٖ وَجَعَلَ مِنۡهَا زَوۡجَهَا لِيَسۡكُنَ إِلَيۡهَاۖ فَلَمَّا\nتَغَشَّىٰهَا حَمَلَتۡ حَمۡلًا خَفِيفٗا فَمَرَّتۡ بِهِۦۖ فَلَمَّآ أَثۡقَلَت دَّعَوَا\nٱللَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَٰلِحٗا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ\u{a0}١٨٩\n\u{2}  \n        \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ\nعِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡيَسۡتَجِيبُواْ لَكُمۡ إِن\nكُنتُمۡ صَٰدِقِينَ\u{a0}١٩٤\u{2}     \n     \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَهُمۡ أَرۡجُلٞ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٖ\nيَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٞ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٞ\nيَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ\u{a0}١٩٥\n\u{2}      \n         \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَطِيعُونَ نَصۡرَكُمۡ وَلَآ\nأَنفُسَهُمۡ يَنصُرُونَ\u{a0}١٩٧\u{2}       \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ\nبِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ\u{a0}١٩٩\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِمَّا يَنزَغَنَّكَ مِنَ\nٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ\u{a0}٢٠٠\u{2}  \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يُجَٰدِلُونَكَ فِي ٱلۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى\nٱلۡمَوۡتِ وَهُمۡ يَنظُرُونَ\u{a0}٦\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا\nلَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ\nوَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ\u{a0}٧\n\u{2}     \n       \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ\nعَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ\nٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ\u{a0}١١\n\u{2}     \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ\nسَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ\nٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ\u{a0}١٢\u{2}         \n       \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ\nوَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ\nفِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ\u{a0}١٩\u{2}    \n          \n       \u{a0}\u{1}\u{2}6\u{2}\u{2}يَٰٓأَيُّهَا\nٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡاْ عَنۡهُ وَأَنتُمۡ\nتَسۡمَعُونَ\u{a0}٢٠\u{2}\n        \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ\nٱلَّذِينَ لَا يَعۡقِلُونَ\u{a0}٢٢\u{2}      \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ\nٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ\nلَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ\u{a0}٢٩\u{2}    \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ\nكَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ\nٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ\u{a0}٣٠\u{2}   \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا\nقَالُواْ قَدۡ سَمِعۡنَا لَوۡ نَشَآءُ لَقُلۡنَا مِثۡلَ هَٰذَآ إِنۡ هَٰذَآ إِلَّآ\nأَسَٰطِيرُ ٱلۡأَوَّلِينَ\u{a0}٣١\u{2}   \n          \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ\nوَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ\u{a0}٣٣\n\u{2}   \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{2}\u{2}\u{2}۞ وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ\nوَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ إِن\nكُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا يَوۡمَ ٱلۡفُرۡقَانِ\nيَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ\u{a0}٤١\u{2}        \n      \n        \n       \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ\nوَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ\u{a0}٤٦\u{2}       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَكُونُواْ كَٱلَّذِينَ\nخَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ\nعَن سَبِيلِ ٱللَّهِۚ وَٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطٞ\u{a0}٤٧\u{2}  \n      \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ زَيَّنَ لَهُمُ\nٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡيَوۡمَ مِنَ\nٱلنَّاسِ وَإِنِّي جَارٞ لَّكُمۡۖ فَلَمَّا تَرَآءَتِ ٱلۡفِئَتَانِ نَكَصَ\nعَلَىٰ عَقِبَيۡهِ وَقَالَ إِنِّي بَرِيٓءٞ مِّنكُمۡ إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ\nإِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ\u{a0}٤٨\u{2}  \n       \n       \n          \n     \u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ يَقُولُ\nٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمۡۗ\nوَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ\u{a0}٤٩\n\u{2} \n       \n       \u{a0}\n\u{1}\u{2}11\u{2}\u{2}وَلَوۡ تَرَىٰٓ إِذۡ يَتَوَفَّى ٱلَّذِينَ كَفَرُواْ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ\nوُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ\u{a0}٥٠\u{2}       \n    \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ\nمَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ\u{a0}٥٣\u{2}           \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ عَٰهَدتَّ مِنۡهُمۡ ثُمَّ يَنقُضُونَ عَهۡدَهُمۡ فِي كُلِّ مَرَّةٖ\nوَهُمۡ لَا يَتَّقُونَ\u{a0}٥٦\u{2}        \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِمَّا تَخَافَنَّ مِن\nقَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ\u{a0}٥٨\n\u{2}  \n          \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَإِن جَنَحُواْ\nلِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\u{a0}٦١\n\u{2} \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ\nمَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ\nٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ إِنَّهُۥ عَزِيزٌ حَكِيمٞ\u{a0}٦٣\u{2}    \n        \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلۡـَٰٔنَ خَفَّفَ\nٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِيكُمۡ ضَعۡفٗاۚ فَإِن يَكُن مِّنكُم مِّاْئَةٞ\nصَابِرَةٞ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُمۡ أَلۡفٞ يَغۡلِبُوٓاْ أَلۡفَيۡنِ\nبِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ\u{a0}٦٦\u{2} \n         \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}مَا كَانَ لِنَبِيٍّ أَن يَكُونَ\nلَهُۥٓ أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِي ٱلۡأَرۡضِۚ تُرِيدُونَ عَرَضَ ٱلدُّنۡيَا\nوَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ\u{a0}٦٧\u{2}    \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}لَّوۡلَا كِتَٰبٞ مِّنَ\nٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمٞ\u{a0}٦٨\u{2}  \n      \u{a0}\u{1}\u{2}\u{2}\u{2}فَكُلُواْ مِمَّا\nغَنِمۡتُمۡ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ\u{a0}٦٩\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَإِن يُرِيدُواْ خِيَانَتَكَ فَقَدۡ خَانُواْ\nٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ\u{a0}٧١\u{2}    \n       \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ\nوَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ هُمُ\nٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ\u{a0}٧٤\u{2}  \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَامَنُواْ مِنۢ\nبَعۡدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمۡ فَأُوْلَٰٓئِكَ مِنكُمۡۚ وَأُوْلُواْ ٱلۡأَرۡحَامِ\nبَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمُۢ\u{a0}٧٥\n\u{2}  \n       \n          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ثُمَّ لَمۡ يَنقُصُوكُمۡ\nشَيۡـٔٗا وَلَمۡ يُظَٰهِرُواْ عَلَيۡكُمۡ أَحَدٗا فَأَتِمُّوٓاْ إِلَيۡهِمۡ عَهۡدَهُمۡ إِلَىٰ\nمُدَّتِهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ\u{a0}٤\u{2}       \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ\nفَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ\nوَٱقۡعُدُواْ لَهُمۡ كُلَّ مَرۡصَدٖۚ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ\nوَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ\u{a0}٥\n\u{2}   \n     \n       \n       \u{a0}\n\u{1}\u{2}14\u{2}\u{2}وَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ\nكَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ\u{a0}٦\n\u{2}       \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}كَيۡفَ يَكُونُ لِلۡمُشۡرِكِينَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ\nرَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا\nٱسۡتَقَٰمُواْ لَكُمۡ فَٱسۡتَقِيمُواْ لَهُمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ\u{a0}٧\n\u{2}      \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}كَيۡفَ وَإِن يَظۡهَرُواْ عَلَيۡكُمۡ لَا يَرۡقُبُواْ فِيكُمۡ إِلّٗا\nوَلَا ذِمَّةٗۚ يُرۡضُونَكُم بِأَفۡوَٰهِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ\nفَٰسِقُونَ\u{a0}٨\u{2}       \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا فَصَدُّواْ\nعَن سَبِيلِهِۦٓۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ\u{a0}٩\u{2}     \n      \u{a0}\u{1}\u{2}\u{2}\u{2}لَا يَرۡقُبُونَ\nفِي مُؤۡمِنٍ إِلّٗا وَلَا ذِمَّةٗۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُعۡتَدُونَ\u{a0}١٠\n\u{2} \n       \u{a0}\n\u{1}\u{2}9\u{2}\u{2}فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ\nفِي ٱلدِّينِۗ وَنُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ\u{a0}١١\u{2}      \n     \u{a0}\u{1}\u{2}\u{2}12\u{2}وَإِن نَّكَثُوٓاْ\nأَيۡمَٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُواْ فِي دِينِكُمۡ فَقَٰتِلُوٓاْ\nأَئِمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَآ أَيۡمَٰنَ لَهُمۡ لَعَلَّهُمۡ يَنتَهُونَ\u{a0}١٢\n\u{2} \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَلَا تُقَٰتِلُونَ قَوۡمٗا نَّكَثُوٓاْ أَيۡمَٰنَهُمۡ وَهَمُّواْ\nبِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ\nأَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِينَ\u{a0}١٣\n\u{2}     \n     \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَيُذۡهِبۡ\nغَيۡظَ قُلُوبِهِمۡۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ\u{a0}١٥\n\u{2}\n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُواْ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ\nمِنكُمۡ وَلَمۡ يَتَّخِذُواْ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِينَ\nوَلِيجَةٗۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}١٦\u{2}        \n         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}مَا كَانَ لِلۡمُشۡرِكِينَ\nأَن يَعۡمُرُواْ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلۡكُفۡرِۚ\nأُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ وَفِي ٱلنَّارِ هُمۡ خَٰلِدُونَ\u{a0}١٧\n\u{2}  \n       \n      \u{a0}\n\u{1}\u{2}9\u{2}\u{2}إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ\nوَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ\nأُوْلَٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ\u{a0}١٨\u{2}        \n        \n    \u{a0}\u{1}\u{2}\u{2}14\u{2}۞ أَجَعَلۡتُمۡ سِقَايَةَ\nٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ\nوَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ\nٱلظَّٰلِمِينَ\u{a0}١٩\u{2} \n        \n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ\nبِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ\u{a0}٢٠\n\u{2}      \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ إِن\nكَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ\nوَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ\nتَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ\nفِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي\nٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ\u{a0}٢٤\u{2} \n     \n     \n      \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ\nكَثِيرَةٖ وَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ\nتُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ\nبِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ\u{a0}٢٥\u{2}    \n      \n     \n    \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ\nعَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَنزَلَ جُنُودٗا لَّمۡ تَرَوۡهَا\nوَعَذَّبَ ٱلَّذِينَ كَفَرُواْۚ وَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ\u{a0}٢٦\n\u{2}   \n       \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ غَفُورٞ\nرَّحِيمٞ\u{a0}٢٧\u{2}          \n\u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ\nنَجَسٞ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ\nوَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن\nشَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٞ\u{a0}٢٨\u{2}    \n       \n        \n    \u{a0}\u{1}\u{2}\u{2}8\u{2}قَٰتِلُواْ ٱلَّذِينَ\nلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ\nٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ\nٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدٖ وَهُمۡ صَٰغِرُونَ\u{a0}٢٩\n\u{2} \n         \n        \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى\nٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ ذَٰلِكَ قَوۡلُهُم بِأَفۡوَٰهِهِمۡۖ\nيُضَٰهِـُٔونَ قَوۡلَ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُۚ قَٰتَلَهُمُ\nٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ\u{a0}٣٠\u{2}      \n     \n      \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}يُرِيدُونَ أَن يُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَيَأۡبَى ٱللَّهُ إِلَّآ\nأَن يُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ\u{a0}٣٢\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِيٓ\nأَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ\nكُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ\u{a0}٣٣\u{2} \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ\nأَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ\nوَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا\nفِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ\u{a0}٣٤\u{2} \n      \n      \n     \n     \u{a0}\u{1}\u{2}\u{2}\u{2}يَوۡمَ يُحۡمَىٰ\nعَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ\nوَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ\nتَكۡنِزُونَ\u{a0}٣٥\u{2} \n       \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ\nشَهۡرٗا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ\nمِنۡهَآ أَرۡبَعَةٌ حُرُمٞۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُۚ فَلَا تَظۡلِمُواْ فِيهِنَّ\nأَنفُسَكُمۡۚ وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ كَمَا\nيُقَٰتِلُونَكُمۡ كَآفَّةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ\u{a0}٣٦\n\u{2}      \n       \n        \n    \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُواْ\nيُحِلُّونَهُۥ عَامٗا وَيُحَرِّمُونَهُۥ عَامٗا لِّيُوَاطِـُٔواْ عِدَّةَ مَا حَرَّمَ ٱللَّهُ\nفَيُحِلُّواْ مَا حَرَّمَ ٱللَّهُۚ زُيِّنَ لَهُمۡ سُوٓءُ أَعۡمَٰلِهِمۡۗ وَٱللَّهُ\nلَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ\u{a0}٣٧\u{2}        \n        \n        \n   \u{a0}\u{1}\u{2}4\u{2}7\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ\nإِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ\nفَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ\u{a0}٣٨\n\u{2} \n          \n      \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا\nغَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ\nقَدِيرٌ\u{a0}٣٩\u{2}      \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ\nٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ\nيَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ\nٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا\nوَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ\nوَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ\u{a0}٤٠\n\u{2}      \n        \n       \n      \n    \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}5\u{2}لَوۡ كَانَ عَرَضٗا قَرِيبٗا وَسَفَرٗا قَاصِدٗا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتۡ\nعَلَيۡهِمُ ٱلشُّقَّةُۚ وَسَيَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا\nمَعَكُمۡ يُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ يَعۡلَمُ إِنَّهُمۡ لَكَٰذِبُونَ\u{a0}٤٢\n\u{2}        \n      \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ\nصَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ\u{a0}٤٣\u{2}         \n  \u{a0}\u{1}\u{2}7\u{2}\u{2}لَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ\nيُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ\nوَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ\u{a0}٤٤\u{2}  \n      \n   \u{a0}\u{1}\u{2}9\u{2}\u{2}إِنَّمَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ\nلَا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ\nفِي رَيۡبِهِمۡ يَتَرَدَّدُونَ\u{a0}٤٥\u{2}  \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَلَوۡ أَرَادُواْ ٱلۡخُرُوجَ\nلَأَعَدُّواْ لَهُۥ عُدَّةٗ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ\nوَقِيلَ ٱقۡعُدُواْ مَعَ ٱلۡقَٰعِدِينَ\u{a0}٤٦\u{2}  \n       \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}لَقَدِ ٱبۡتَغَوُاْ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ حَتَّىٰ\nجَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ\u{a0}٤٨\n\u{2}        \n      \u{a0}\n\u{1}\u{2}3\u{2}\u{2}وَمِنۡهُم مَّن يَقُولُ ٱئۡذَن لِّي وَلَا تَفۡتِنِّيٓۚ أَلَا فِي ٱلۡفِتۡنَةِ\nسَقَطُواْۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ\u{a0}٤٩\n\u{2}         \n    \u{a0}\n\u{1}\u{2}5\u{2}7\u{2}إِن تُصِبۡكَ حَسَنَةٞ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ\nمُصِيبَةٞ يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ وَيَتَوَلَّواْ\nوَّهُمۡ فَرِحُونَ\u{a0}٥٠\u{2}     \n       \n \u{a0}\u{1}\u{2}7\u{2}\u{2}قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ\nٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\u{a0}٥١\n\u{2}     \n       \u{a0}\n\u{1}\u{2}9\u{2}\u{2}قُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ وَنَحۡنُ\nنَتَرَبَّصُ بِكُمۡ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٖ مِّنۡ عِندِهِۦٓ\nأَوۡ بِأَيۡدِينَاۖ فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ\u{a0}٥٢\u{2}       \n       \n     \u{a0}\u{1}\u{2}\u{2}13\u{2}قُلۡ\nأَنفِقُواْ طَوۡعًا أَوۡ كَرۡهٗا لَّن يُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ\nقَوۡمٗا فَٰسِقِينَ\u{a0}٥٣\u{2}\n        \n \u{a0}\u{1}\u{2}13\u{2}\u{2}وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَٰتُهُمۡ\nإِلَّآ أَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأۡتُونَ ٱلصَّلَوٰةَ\nإِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ\u{a0}٥٤\n\u{2}     \n       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَوۡ يَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَٰرَٰتٍ\nأَوۡ مُدَّخَلٗا لَّوَلَّوۡاْ إِلَيۡهِ وَهُمۡ يَجۡمَحُونَ\u{a0}٥٧\u{2}    \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنۡهُم مَّن يَلۡمِزُكَ\nفِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا\nهُمۡ يَسۡخَطُونَ\u{a0}٥٨\u{2}  \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡ أَنَّهُمۡ رَضُواْ مَآ ءَاتَىٰهُمُ ٱللَّهُ\nوَرَسُولُهُۥ وَقَالُواْ حَسۡبُنَا ٱللَّهُ سَيُؤۡتِينَا ٱللَّهُ مِن فَضۡلِهِۦ\nوَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ\u{a0}٥٩\u{2}     \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ إِنَّمَا ٱلصَّدَقَٰتُ\nلِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ\nوَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ\nفَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ\u{a0}٦٠\u{2} \n     \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنۡهُمُ\nٱلَّذِينَ يُؤۡذُونَ ٱلنَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٞۚ قُلۡ أُذُنُ خَيۡرٖ\nلَّكُمۡ يُؤۡمِنُ بِٱللَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ وَرَحۡمَةٞ لِّلَّذِينَ\nءَامَنُواْ مِنكُمۡۚ وَٱلَّذِينَ يُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِيمٞ\u{a0}٦١\n\u{2}\n        \n      \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَلَمۡ يَعۡلَمُوٓاْ أَنَّهُۥ\nمَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدٗا فِيهَاۚ\nذَٰلِكَ ٱلۡخِزۡيُ ٱلۡعَظِيمُ\u{a0}٦٣\u{2}  \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}يَحۡذَرُ ٱلۡمُنَٰفِقُونَ\nأَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ\nإِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ\u{a0}٦٤\u{2} \n         \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَعَدَ ٱللَّهُ\nٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ\nفِيهَاۚ هِيَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ\u{a0}٦٨\n\u{2} \n     \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}كَٱلَّذِينَ مِن قَبۡلِكُمۡ كَانُوٓاْ أَشَدَّ مِنكُمۡ قُوَّةٗ وَأَكۡثَرَ\nأَمۡوَٰلٗا وَأَوۡلَٰدٗا فَٱسۡتَمۡتَعُواْ بِخَلَٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ\nكَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ وَخُضۡتُمۡ\nكَٱلَّذِي خَاضُوٓاْۚ أُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا\nوَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ\u{a0}٦٩\u{2}       \n     \n      \n      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ يَأۡتِهِمۡ\nنَبَأُ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَقَوۡمِ\nإِبۡرَٰهِيمَ وَأَصۡحَٰبِ مَدۡيَنَ وَٱلۡمُؤۡتَفِكَٰتِۚ أَتَتۡهُمۡ\nرُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن\nكَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ\u{a0}٧٠\u{2} \n        \n    \n      \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَحۡلِفُونَ بِٱللَّهِ\nمَا قَالُواْ وَلَقَدۡ قَالُواْ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُواْ بَعۡدَ إِسۡلَٰمِهِمۡ\nوَهَمُّواْ بِمَا لَمۡ يَنَالُواْۚ وَمَا نَقَمُوٓاْ إِلَّآ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ\nمِن فَضۡلِهِۦۚ فَإِن يَتُوبُواْ يَكُ خَيۡرٗا لَّهُمۡۖ وَإِن يَتَوَلَّوۡاْ يُعَذِّبۡهُمُ\nٱللَّهُ عَذَابًا أَلِيمٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَمَا لَهُمۡ فِي ٱلۡأَرۡضِ\nمِن وَلِيّٖ وَلَا نَصِيرٖ\u{a0}٧٤\u{2} \n        \n          \n         \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَمِنۡهُم مَّنۡ عَٰهَدَ ٱللَّهَ لَئِنۡ\nءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ\u{a0}٧٥\n\u{2}    \n      \u{a0}\n\u{1}\u{2}\u{2}9\u{2}فَلَمَّآ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ\u{a0}٧٦\n\u{2}        \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ\nٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ\u{a0}٧٧\u{2}        \n     \u{a0}\u{1}\u{2}11\u{2}\u{2}أَلَمۡ يَعۡلَمُوٓاْ\nأَنَّ ٱللَّهَ يَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّٰمُ\nٱلۡغُيُوبِ\u{a0}٧٨\u{2} \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ\nٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا\nجُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ\u{a0}٧٩\n\u{2}   \n      \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}فَرِحَ ٱلۡمُخَلَّفُونَ\nبِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ\nوَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَقَالُواْ لَا تَنفِرُواْ فِي ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ\nأَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ\u{a0}٨١\u{2} \n       \n           \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَلۡيَضۡحَكُواْ قَلِيلٗا وَلۡيَبۡكُواْ كَثِيرٗا\nجَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ\u{a0}٨٢\u{2}   \n   \u{a0}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّٰتٖ تَجۡرِي\nمِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}٨٩\u{2}    \n       \u{a0}\u{1}\u{2}5\u{2}7\u{2}وَجَآءَ\nٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِيُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِينَ كَذَبُواْ\nٱللَّهَ وَرَسُولَهُۥۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٞ\u{a0}٩٠\n\u{2}\n       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّمَا ٱلسَّبِيلُ عَلَى\nٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِيَآءُۚ رَضُواْ بِأَن يَكُونُواْ\nمَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَمُونَ\u{a0}٩٣\n\u{2}  \n      \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَعۡتَذِرُونَ إِلَيۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡۚ قُل لَّا تَعۡتَذِرُواْ لَن\nنُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَيَرَى\nٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ\nوَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\u{a0}٩٤\u{2}        \n       \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}سَيَحۡلِفُونَ\nبِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَيۡهِمۡ لِتُعۡرِضُواْ عَنۡهُمۡۖ فَأَعۡرِضُواْ\nعَنۡهُمۡۖ إِنَّهُمۡ رِجۡسٞۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَآءَۢ بِمَا كَانُواْ\nيَكۡسِبُونَ\u{a0}٩٥\u{2}\n       \n       \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ\nحُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ\u{a0}٩٧\u{2}      \n        \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنَ\nٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَۚ\nعَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ\u{a0}٩٨\u{2}\n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنَ\nٱلۡأَعۡرَابِ مَن يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَتَّخِذُ\nمَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِۚ أَلَآ إِنَّهَا قُرۡبَةٞ\nلَّهُمۡۚ سَيُدۡخِلُهُمُ ٱللَّهُ فِي رَحۡمَتِهِۦٓۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ\u{a0}٩٩\n\u{2}\n      \n         \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَمۡ يَعۡلَمُوٓاْ\nأَنَّ ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ\nٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ\u{a0}١٠٤\u{2} \n         \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ\nٱللَّهِ إِمَّا يُعَذِّبُهُمۡ وَإِمَّا يَتُوبُ عَلَيۡهِمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ\u{a0}١٠٦\n\u{2}  \n        \u{a0}\n\u{1}\u{2}\u{2}3\u{2}وَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ\nٱلۡمُؤۡمِنِينَ وَإِرۡصَادٗا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ\nوَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ\u{a0}١٠٧\n\u{2}      \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ\nيَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ\nوَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ\u{a0}١٠٨\u{2}         \n         \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم\nبِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ\nوَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ\nوَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ\nبِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}١١١\n\u{2}      \n       \n      \n      \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن\nيَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ\nمَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ\u{a0}١١٣\u{2}     \n       \n     \u{a0}\u{1}\u{2}\u{2}8\u{2}وَمَا كَانَ\nٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةٖ وَعَدَهَآ إِيَّاهُ\nفَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوّٞ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٞ\u{a0}١١٤\n\u{2} \n       \n           \u{a0}\n\u{1}\u{2}\u{2}10\u{2}وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ\nيُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ\u{a0}١١٥\u{2}        \n        \u{a0}\u{1}\u{2}10\u{2}\u{2}إِنَّ ٱللَّهَ\nلَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۚ وَمَا لَكُم مِّن\nدُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ\u{a0}١١٦\u{2} \n        \n     \u{a0}\u{1}\u{2}12\u{2}\u{2}لَّقَد تَّابَ ٱللَّهُ عَلَى\nٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي\nسَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ\nمِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ\u{a0}١١٧\n\u{2}   \n     \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم\nمِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ\nعَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٞ وَلَا نَصَبٞ\nوَلَا مَخۡمَصَةٞ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئٗا يَغِيظُ\nٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوّٖ نَّيۡلًا إِلَّا كُتِبَ لَهُم\nبِهِۦ عَمَلٞ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ\u{a0}١٢٠\n\u{2}     \n         \n        \n        \n        \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ\nفَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ\nوَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ\u{a0}١٢٢\n\u{2}    \n         \n      \u{a0}\n\u{1}\u{2}\u{2}2\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ\nوَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ\u{a0}١٢٣\n\u{2}       \n       \u{a0}\n\u{1}\u{2}\u{2}4\u{2}وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ\nإِيمَٰنٗاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنٗا وَهُمۡ يَسۡتَبۡشِرُونَ\u{a0}١٢٤\n\u{2}         \n       \u{a0}\n\u{1}\u{2}5\u{2}6\u{2}وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا\nإِلَىٰ رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ\u{a0}١٢٥\u{2}      \n    \u{a0}\u{1}\u{2}6\u{2}8\u{1}\u{2}8\u{2}10\u{2}وَإِذَا مَآ أُنزِلَتۡ\nسُورَةٞ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَىٰكُم مِّنۡ أَحَدٖ\nثُمَّ ٱنصَرَفُواْۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ\u{a0}١٢٧\n\u{2}  \n        \n        \u{a0}\n\u{1}\u{2}11\u{2}13\u{2}لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ\nعَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ\nرَءُوفٞ رَّحِيمٞ\u{a0}١٢٨\u{2}     \n     \n \u{a0}\u{1}\u{2}13\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}5\u{2}أَكَانَ لِلنَّاسِ عَجَبًا\nأَنۡ أَوۡحَيۡنَآ إِلَىٰ رَجُلٖ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓاْ\nأَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَٰفِرُونَ إِنَّ هَٰذَا\nلَسَٰحِرٞ مُّبِينٌ\u{a0}٢\u{2}  \n          \n         \n \u{a0}\u{1}\u{2}5\u{2}\u{2}إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ\nفِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِيعٍ\nإِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا\nتَذَكَّرُونَ\u{a0}٣\u{2}      \n           \n        \n\u{a0}\u{1}\u{2}8\u{2}\u{2}إِلَيۡهِ مَرۡجِعُكُمۡ جَمِيعٗاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ\nيَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ\nبِٱلۡقِسۡطِۚ وَٱلَّذِينَ كَفَرُواْ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ\nأَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ\u{a0}٤\u{2}      \n        \n       \n   \u{a0}\u{1}\u{2}11\u{2}\u{2}هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ\nضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ\nوَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ\nلِقَوۡمٖ يَعۡلَمُونَ\u{a0}٥\u{2}   \n       \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ\nٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ\u{a0}٦\n\u{2}      \n      \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ءَامَنُواْ\nوَعَمِلُواْ ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن\nتَحۡتِهِمُ ٱلۡأَنۡهَٰرُ فِي جَنَّٰتِ ٱلنَّعِيمِ\u{a0}٩\u{2}  \n      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ\nٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ\nرَبِّ ٱلۡعَٰلَمِينَ\u{a0}١٠\u{2}  \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ\nٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ\nلَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ\u{a0}١١\u{2}    \n      \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا مَسَّ\nٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا فَلَمَّا كَشَفۡنَا\nعَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرّٖ مَّسَّهُۥۚ كَذَٰلِكَ زُيِّنَ\nلِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ\u{a0}١٢\u{2} \n         \n          \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ\nلِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ لِيٓ\nأَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ إِنِّيٓ\nأَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ\u{a0}١٥\u{2}        \n          \n           \n      \u{a0}\u{1}\u{2}\u{2}\u{2}قُل لَّوۡ شَآءَ\nٱللَّهُ مَا تَلَوۡتُهُۥ عَلَيۡكُمۡ وَلَآ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ\nفِيكُمۡ عُمُرٗا مِّن قَبۡلِهِۦٓۚ أَفَلَا تَعۡقِلُونَ\u{a0}١٦\u{2}  \n        \n     \u{a0}\u{1}'
    '\u{2}6\u{2}\u{2}فَمَنۡ أَظۡلَمُ\nمِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ\nلَا يُفۡلِحُ ٱلۡمُجۡرِمُونَ\u{a0}١٧\u{2} \n        \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ\nٱلنَّاسُ إِلَّآ أُمَّةٗ وَٰحِدَةٗ فَٱخۡتَلَفُواْۚ وَلَوۡلَا كَلِمَةٞ\nسَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِفُونَ\u{a0}١٩\n\u{2} \n      \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرٞ فِيٓ\nءَايَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ\u{a0}٢١\n\u{2}           \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ\nوَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ\nوَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ\nٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ\nٱلشَّٰكِرِينَ\u{a0}٢٢\u{2}          \n        \n         \n         \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ\nنَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ\nزُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ\nأَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ\nبِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ\u{a0}٢٤\u{2}         \n         \n      \n         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱللَّهُ\nيَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ\u{a0}٢٥\n\u{2}\n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ\nوَلَا ذِلَّةٌۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ\u{a0}٢٦\u{2}       \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ\nكَسَبُواْ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةٞۖ مَّا لَهُم مِّنَ\nٱللَّهِ مِنۡ عَاصِمٖۖ كَأَنَّمَآ أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَعٗا مِّنَ ٱلَّيۡلِ مُظۡلِمًاۚ\nأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ\u{a0}٢٧\u{2}\n         \n         \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ مَن يَرۡزُقُكُم\nمِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ\nٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ\nفَسَيَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ\u{a0}٣١\u{2}  \n        \n         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ\nفَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ\u{a0}٣٢\u{2}   \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ إِنَّ ٱللَّهَ\nعَلِيمُۢ بِمَا يَفۡعَلُونَ\u{a0}٣٦\u{2}             \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ هَٰذَا ٱلۡقُرۡءَانُ أَن يُفۡتَرَىٰ مِن دُونِ\nٱللَّهِ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ ٱلۡكِتَٰبِ لَا رَيۡبَ\nفِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ\u{a0}٣٧\u{2}       \n         \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ\nٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ\u{a0}٣٩\n\u{2}          \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمۡ عَمَلُكُمۡۖ\nأَنتُم بَرِيٓـُٔونَ مِمَّآ أَعۡمَلُ وَأَنَا۠ بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ\u{a0}٤١\u{2}      \n       \u{a0}\u{1}\u{1}\u{2}\u{2}2\u{2}وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ\nلَا يُبۡصِرُونَ\u{a0}٤٣\u{2}        \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ\nٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ\u{a0}٤٤\u{2}      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا\nسَاعَةٗ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِ\nوَمَا كَانُواْ مُهۡتَدِينَ\u{a0}٤٥\u{2}     \n          \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَيَسۡتَنۢبِـُٔونَكَ\nأَحَقٌّ هُوَۖ قُلۡ إِي وَرَبِّيٓ إِنَّهُۥ لَحَقّٞۖ وَمَآ أَنتُم بِمُعۡجِزِينَ\u{a0}٥٣\n\u{2}\n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقٖ\nفَجَعَلۡتُم مِّنۡهُ حَرَامٗا وَحَلَٰلٗا قُلۡ ءَآللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ\nتَفۡتَرُونَ\u{a0}٥٩\u{2}       \n          \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَهُمُ ٱلۡبُشۡرَىٰ\nفِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ\nذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}٦٤\u{2} \n        \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَآ إِنَّ لِلَّهِ\nمَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِۗ وَمَا يَتَّبِعُ ٱلَّذِينَ\nيَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَۚ إِن يَتَّبِعُونَ إِلَّا\nٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ\u{a0}٦٦\u{2}  \n        \n       \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ\nسُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ\nإِنۡ عِندَكُم مِّن سُلۡطَٰنِۭ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا\nلَا تَعۡلَمُونَ\u{a0}٦٨\u{2}   \n         \n        \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ يَٰقَوۡمِ إِن كَانَ كَبُرَ عَلَيۡكُم\nمَّقَامِي وَتَذۡكِيرِي بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوٓاْ\nأَمۡرَكُمۡ وَشُرَكَآءَكُمۡ ثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةٗ ثُمَّ ٱقۡضُوٓاْ\nإِلَيَّ وَلَا تُنظِرُونِ\u{a0}٧١\u{2}           \n       \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ\nأَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ\u{a0}٧٢\n\u{2}      \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ\nفِرۡعَوۡنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ\u{a0}٧٥\n\u{2}      \n      \u{a0}\n\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ مُوسَىٰ يَٰقَوۡمِ إِن كُنتُمۡ\nءَامَنتُم بِٱللَّهِ فَعَلَيۡهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسۡلِمِينَ\u{a0}٨٤\u{2}    \n      \u{a0}\u{1}\u{2}8\u{2}\u{2}فَقَالُواْ عَلَى ٱللَّهِ\nتَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ\u{a0}٨٥\u{2}  \n      \u{a0}\u{1}\u{2}9\u{2}\u{2}وَنَجِّنَا\nبِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ\u{a0}٨٦\u{2}\n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ\nأَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُوتٗا وَٱجۡعَلُواْ بُيُوتَكُمۡ قِبۡلَةٗ\nوَأَقِيمُواْ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ\u{a0}٨٧\u{2}   \n       \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ\nفَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ\nٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ\nوَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ\u{a0}٩٠\u{2}   \n       \n           \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ مُبَوَّأَ صِدۡقٖ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ\nفَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ\nفِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ\u{a0}٩٣\u{2}        \n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ\nفَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَآءَكَ\nٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ\u{a0}٩٤\u{2}      \n       \n      \u{a0}\u{1}\u{2}12\u{2}\u{2}وَلَا تَكُونَنَّ\nمِنَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَٰسِرِينَ\u{a0}٩٥\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ\nءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ\nإِلَىٰ حِينٖ\u{a0}٩٨\u{2}         \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ\nجَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ\u{a0}٩٩\u{2}       \n      \u{a0}\u{1}\u{2}4\u{2}\u{2}وَمَا\nكَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَجۡعَلُ ٱلرِّجۡسَ\nعَلَى ٱلَّذِينَ لَا يَعۡقِلُونَ\u{a0}١٠٠\u{2}\n        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ\nمَا لَا يَنفَعُكَ وَلَا يَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذٗا مِّنَ ٱلظَّٰلِمِينَ\u{a0}١٠٦\n\u{2}    \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن\nيُرِدۡكَ بِخَيۡرٖ فَلَا رَآدَّ لِفَضۡلِهِۦۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ\nوَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ\u{a0}١٠٧\u{2}         \n          \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ\nٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن\nضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنَا۠ عَلَيۡكُم بِوَكِيلٖ\u{a0}١٠٨\u{2}    \n        \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱتَّبِعۡ\nمَا يُوحَىٰٓ إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ\u{a0}١٠٩\n\u{2}\n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا\nوَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ\u{a0}٦\u{2}          \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي خَلَقَ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ وَكَانَ عَرۡشُهُۥ\nعَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ وَلَئِن قُلۡتَ\nإِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ\nإِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ\u{a0}٧\u{2}  \n      \n       \n       \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ لَهُم مَّغۡفِرَةٞ\nوَأَجۡرٞ كَبِيرٞ\u{a0}١١\u{2}       \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ\nإِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ\u{a0}١٤\u{2}          \n    \u{a0}\u{1}\u{2}\u{2}5\u{2}مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ\nٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ\u{a0}١٥\n\u{2}   \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ\nمَا صَنَعُواْ فِيهَا وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ\u{a0}١٦\u{2}        \n      \u{a0}\u{1}\u{2}7\u{2}\u{2}أَفَمَن كَانَ\nعَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدٞ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَٰبُ\nمُوسَىٰٓ إِمَامٗا وَرَحۡمَةًۚ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ وَمَن يَكۡفُرۡ بِهِۦ\nمِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِي مِرۡيَةٖ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ\nمِن رَّبِّكَ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ\u{a0}١٧\u{2} \n         \n        \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَنۡ\nأَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُوْلَٰٓئِكَ يُعۡرَضُونَ\nعَلَىٰ رَبِّهِمۡ وَيَقُولُ ٱلۡأَشۡهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُواْ عَلَىٰ\nرَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ\u{a0}١٨\u{2}\n       \n       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَصُدُّونَ\nعَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ\u{a0}١٩\n\u{2} \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ لَمۡ يَكُونُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن\nدُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَۘ يُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُواْ يَسۡتَطِيعُونَ\nٱلسَّمۡعَ وَمَا كَانُواْ يُبۡصِرُونَ\u{a0}٢٠\u{2}         \n         \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ مَثَلُ ٱلۡفَرِيقَيۡنِ كَٱلۡأَعۡمَىٰ\nوَٱلۡأَصَمِّ وَٱلۡبَصِيرِ وَٱلسَّمِيعِۚ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ\u{a0}٢٤\n\u{2}  \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا\nمِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ\nٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ\u{a0}٢٧\n\u{2}         \n        \n         \u{a0}\n\u{1}'
    '\u{2}\u{2}\u{2}قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ\nمِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ\u{a0}٢٨\n\u{2}          \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ\nأَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ\nقَوۡمٗا تَجۡهَلُونَ\u{a0}٢٩\u{2}          \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ\nأَفَلَا تَذَكَّرُونَ\u{a0}٣٠\u{2}      \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ\nأَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكٞ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ\nأَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ إِذٗا\nلَّمِنَ ٱلظَّٰلِمِينَ\u{a0}٣١\u{2}      \n         \n           \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ\nجِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ\u{a0}٣٢\u{2}    \n       \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ\nإِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ\u{a0}٣٣\u{2}\n        \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا يَنفَعُكُمۡ\nنُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ\nهُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ\u{a0}٣٤\u{2} \n           \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ\nمِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ\u{a0}٣٨\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَقَالَ ٱرۡكَبُواْ\nفِيهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ\u{a0}٤١\u{2} \n        \u{a0}\u{1}\u{2}7\u{2}\u{2}وَهِيَ\nتَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ\nفِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ\u{a0}٤٢\n\u{2}\n        \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ\nٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ\nمِنَ ٱلۡمُغۡرَقِينَ\u{a0}٤٣\u{2}         \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقِيلَ يَٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ\nأَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ\nبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ\u{a0}٤٤\u{2}    \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ\nٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ\u{a0}٤٥\n\u{2}     \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}تِلۡكَ\nمِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ\nمِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ\u{a0}٤٩\u{2}\n          \n      \u{a0}\u{1}\u{2}8\u{2}\u{2}وَإِلَىٰ عَادٍ\nأَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ\nغَيۡرُهُۥٓۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ\u{a0}٥٠\u{2} \n         \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا\nمِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ\u{a0}٥٦\n\u{2}      \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ\nرَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ\u{a0}٥٧\n\u{2}        \n           \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ\nمِّنَّا وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظٖ\u{a0}٥٨\u{2}        \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَأُتۡبِعُواْ\nفِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ عَادٗا كَفَرُواْ رَبَّهُمۡۗ أَلَا\nبُعۡدٗا لِّعَادٖ قَوۡمِ هُودٖ\u{a0}٦٠\u{2}\n           \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ\nيَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ\nوَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ\u{a0}٦١\n\u{2}    \n           \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن\nنَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ\u{a0}٦٢\n\u{2}         \n          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا جَآءَ\nأَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا\nوَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ\u{a0}٦٦\u{2} \n       \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَخَذَ\nٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ\u{a0}٦٧\n\u{2}\n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا\nلِّثَمُودَ\u{a0}٦٨\u{2}          \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا\nرَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ\nقَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ\u{a0}٧٠\u{2}\n        \n       \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ\nشُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ\nوَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ\nوَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ\u{a0}٨٤\u{2}  \n         \n      \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَٰقَوۡمِ\nأَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ\nٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ\u{a0}٨٥\n\u{2}\n     \n      \u{a0}\n\u{1}\u{2}9\u{2}\u{2}بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم\nبِحَفِيظٖ\u{a0}٨٦\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن\nنَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ\nإِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ\u{a0}٨٧\u{2}    \n          \n   \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن\nكُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ\nأُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ\nمَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ\u{a0}٨٨\n\u{2}   \n           \n        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ\nٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ\nمُحِيطٞ\u{a0}٩٢\u{2}     \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ\nسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ\nكَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ\u{a0}٩٣\u{2}     \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَمَّا جَآءَ\nأَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ\nٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ\u{a0}٩٤\n\u{2} \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ\u{a0}٩٥\u{2}         \u{a0}\u{1}\u{2}13\u{2}\u{2}وَلَقَدۡ\nأَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ\u{a0}٩٦\u{2}\n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّمَنۡ خَافَ عَذَابَ ٱلۡأٓخِرَةِۚ\nذَٰلِكَ يَوۡمٞ مَّجۡمُوعٞ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوۡمٞ مَّشۡهُودٞ\u{a0}١٠٣\u{2}       \n       \u{a0}\u{1}\u{2}9\u{2}\u{2}وَمَا\nنُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٖ مَّعۡدُودٖ\u{a0}١٠٤\u{2}\n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}خَٰلِدِينَ فِيهَا مَا دَامَتِ\nٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالٞ لِّمَا يُرِيدُ\u{a0}١٠٧\n\u{2}   \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَأَمَّا ٱلَّذِينَ سُعِدُواْ فَفِي ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ\nٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۖ عَطَآءً غَيۡرَ مَجۡذُوذٖ\u{a0}١٠٨\n\u{2}        \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}10\u{2}وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ\nٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ لِلذَّٰكِرِينَ\u{a0}١١٤\n\u{2}     \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ\u{a0}١١٥\u{2}      \u{a0}\u{1}\u{2}11\u{2}\u{2}فَلَوۡلَا\nكَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةٖ يَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ\nفِي ٱلۡأَرۡضِ إِلَّا قَلِيلٗا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِينَ\nظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ\u{a0}١١٦\u{2}\n         \n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ\nرَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ\u{a0}١١٧\n\u{2} \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا\nلَّعَلَّكُمۡ تَعۡقِلُونَ\u{a0}٢\u{2}   \n \u{a0}\u{1}\u{2}\u{2}\u{2}نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ\nبِمَآ أَوۡحَيۡنَآ إِلَيۡكَ هَٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ\nلَمِنَ ٱلۡغَٰفِلِينَ\u{a0}٣\u{2}    \n        \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَكَذَٰلِكَ يَجۡتَبِيكَ\nرَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ\nوَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ\nإِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ\u{a0}٦\u{2} \n       \n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ\nءَايَٰتٞ لِّلسَّآئِلِينَ\u{a0}٧\u{2}    \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ\nأَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ\u{a0}٨\u{2}     \n        \u{a0}\u{1}\u{2}7\u{2}\u{2}ٱقۡتُلُواْ\nيُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ\nبَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ\u{a0}٩\u{2}\n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ قَآئِلٞ مِّنۡهُمۡ لَا تَقۡتُلُواْ يُوسُفَ\nوَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ ٱلسَّيَّارَةِ إِن كُنتُمۡ\nفَٰعِلِينَ\u{a0}١٠\u{2}     \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ يَٰٓأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ\nلَنَٰصِحُونَ\u{a0}١١\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَرۡسِلۡهُ مَعَنَا غَدٗا يَرۡتَعۡ وَيَلۡعَبۡ وَإِنَّا لَهُۥ\nلَحَٰفِظُونَ\u{a0}١٢\u{2}      \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَجَآءَتۡ سَيَّارَةٞ فَأَرۡسَلُواْ\nوَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمٞۚ وَأَسَرُّوهُ بِضَٰعَةٗۚ\nوَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ\u{a0}١٩\u{2}  \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَمَّا بَلَغَ\nأَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ\u{a0}٢٢\n\u{2} \n      \u{a0}\n\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا\nعَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ\u{a0}٣٠\n\u{2}       \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ\nكُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ\nوَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ\nكَرِيمٞ\u{a0}٣١\u{2}        \n         \n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن\nنَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا\nمِّنَ ٱلصَّٰغِرِينَ\u{a0}٣٢\u{2}       \n        \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ\nإِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ\nرَأۡسِي خُبۡزٗا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ\nٱلۡمُحۡسِنِينَ\u{a0}٣٦\u{2}     \n         \n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ لِلَّذِي\nظَنَّ أَنَّهُۥ نَاجٖ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ\nٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ\u{a0}٤٢\n\u{2} \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ\nسَبۡعٌ عِجَافٞ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖۖ\nيَٰٓأَيُّهَا ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ\u{a0}٤٣\n\u{2}       \n      \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي\nبِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ\nٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ\u{a0}٥٠\u{2}  \n          \n       \u{a0}\u{1}\u{2}11\u{2}\u{2}قَالَ\nمَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ لِلَّهِ\nمَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ\nٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ\u{a0}٥١\u{2}\n         \n         \n       \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ\nرَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ\u{a0}٥٣\u{2}         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ\nلِنَفۡسِيۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٞ\u{a0}٥٤\u{2}    \n        \u{a0}\u{1}\u{2}3\u{2}\u{2}قَالَ\nٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ\u{a0}٥٥\u{2}\n      \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَجَآءَ إِخۡوَةُ\nيُوسُفَ فَدَخَلُواْ عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ\u{a0}٥٨\u{2} \n      \u{a0}\u{1}\u{2}8\u{2}\u{2}وَلَمَّا\nجَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخٖ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا تَرَوۡنَ\nأَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ\u{a0}٥٩\u{2}\n         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِن لَّمۡ تَأۡتُونِي بِهِۦ فَلَا\nكَيۡلَ لَكُمۡ عِندِي وَلَا تَقۡرَبُونِ\u{a0}٦٠\u{2}    \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}7\u{2}قَالَ لَنۡ\nأُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ\nأَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ\u{a0}٦٦\n\u{2} \n         \n           \u{a0}\n\u{1}\u{2}\u{2}10\u{2}وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ\nمُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا\nلِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ\u{a0}٦٧\u{2}         \n          \n     \u{a0}\u{1}\u{2}10\u{2}13\u{2}وَلَمَّا\nدَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم\nمِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ\nلَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ\u{a0}٦٨\n\u{2}\n        \n          \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَخَاهُۖ قَالَ\nإِنِّيٓ أَنَا۠ أَخُوكَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَعۡمَلُونَ\u{a0}٦٩\n\u{2}       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ\nأَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ\u{a0}٧٠\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ وَأَقۡبَلُواْ\nعَلَيۡهِم مَّاذَا تَفۡقِدُونَ\u{a0}٧١\u{2} \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ قَالُوٓاْ إِن يَسۡرِقۡ\nفَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ\nوَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرّٞ مَّكَانٗاۖ وَٱللَّهُ أَعۡلَمُ بِمَا\nتَصِفُونَ\u{a0}٧٧\u{2}  \n         \n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{2}\u{2}2\u{2}يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ\nمِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ\u{a0}٨٧\n\u{2}       \n           \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ\nوَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ\nإِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ\u{a0}٨٨\u{2}        \n       \n   \u{a0}\u{1}\u{2}5\u{2}6\u{2}قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم\nبِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ\u{a0}٨٩\u{2}    \n    \u{a0}\u{1}\u{2}6\u{2}\u{2}قَالُوٓاْ أَءِنَّكَ\nلَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ\nعَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ\nٱلۡمُحۡسِنِينَ\u{a0}٩٠\u{2} \n         \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا\nوَإِن كُنَّا لَخَٰطِـِٔينَ\u{a0}٩١\u{2}     \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ\nٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ\u{a0}٩٢\n\u{2}   \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ بَصِيرٗا\nوَأۡتُونِي بِأَهۡلِكُمۡ أَجۡمَعِينَ\u{a0}٩٣\u{2}        \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ رَبِّ\nقَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي\nمُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ\u{a0}١٠١\u{2}\n        \n       \n  \u{a0}\u{1}\u{2}\u{2}14\u{2}ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ\nنُوحِيهِ إِلَيۡكَۖ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ أَجۡمَعُوٓاْ أَمۡرَهُمۡ وَهُمۡ يَمۡكُرُونَ\u{a0}١٠٢\n\u{2}   \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفَأَمِنُوٓاْ أَن تَأۡتِيَهُمۡ غَٰشِيَةٞ مِّنۡ عَذَابِ ٱللَّهِ\nأَوۡ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ\u{a0}١٠٧\u{2}      \n      \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ هَٰذِهِۦ\nسَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ وَسُبۡحَٰنَ\nٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ\u{a0}١٠٨\u{2} \n         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ\nإِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ فِي\nٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ\nوَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ\u{a0}١٠٩\u{2}   \n         \n       \n      \u{a0}\u{1}\u{2}10\u{2}12\u{2}حَتَّىٰٓ\nإِذَا ٱسۡتَيۡـَٔسَ ٱلرُّسُلُ وَظَنُّوٓاْ أَنَّهُمۡ قَدۡ كُذِبُواْ جَآءَهُمۡ\nنَصۡرُنَا فَنُجِّيَ مَن نَّشَآءُۖ وَلَا يُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ\u{a0}١١٠\n\u{2}\n       \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةٞ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ\nحَدِيثٗا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ\nوَتَفۡصِيلَ كُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ\u{a0}١١١\n\u{2}        \n      \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ ٱلَّذِي رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ\nعَمَدٖ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ\nيَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ يُدَبِّرُ ٱلۡأَمۡرَ يُفَصِّلُ ٱلۡأٓيَٰتِ لَعَلَّكُم بِلِقَآءِ\nرَبِّكُمۡ تُوقِنُونَ\u{a0}٢\u{2}    \n         \n        \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَفِي ٱلۡأَرۡضِ\nقِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ\nوَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ\nفِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ\u{a0}٤\n\u{2} \n       \n        \n       \u{a0}\n\u{1}\u{2}13\u{2}\u{2}۞ وَإِن تَعۡجَبۡ فَعَجَبٞ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِي خَلۡقٖ\nجَدِيدٍۗ أُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ وَأُوْلَٰٓئِكَ ٱلۡأَغۡلَٰلُ\nفِيٓ أَعۡنَاقِهِمۡۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ\u{a0}٥\n\u{2}         \n      \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}4\u{2}وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ\nأُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦٓۗ إِنَّمَآ أَنتَ مُنذِرٞۖ وَلِكُلِّ قَوۡمٍ هَادٍ\u{a0}٧\n\u{2}   \n          \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}سَوَآءٞ مِّنكُم مَّنۡ أَسَرَّ\nٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّيۡلِ وَسَارِبُۢ\nبِٱلنَّهَارِ\u{a0}١٠\u{2}   \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ\nمِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ\nوَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن\nوَالٍ\u{a0}١١\u{2}       \n            \n            \n\u{a0}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا\nوَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ\u{a0}١٢\u{2}     \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦٓ أَوۡلِيَآءَ لَا يَمۡلِكُونَ لِأَنفُسِهِمۡ\nنَفۡعٗا وَلَا ضَرّٗاۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ أَمۡ هَلۡ تَسۡتَوِي\nٱلظُّلُمَٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُواْ لِلَّهِ شُرَكَآءَ خَلَقُواْ كَخَلۡقِهِۦ فَتَشَٰبَهَ ٱلۡخَلۡقُ\nعَلَيۡهِمۡۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖ وَهُوَ ٱلۡوَٰحِدُ ٱلۡقَهَّٰرُ\u{a0}١٦\u{2}   \n          \n          \n         \n        \u{a0}\u{1}\u{2}\u{2}12\u{2}أَنزَلَ مِنَ\nٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدٗا رَّابِيٗاۖ\nوَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعٖ زَبَدٞ مِّثۡلُهُۥۚ كَذَٰلِكَ\nيَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءٗۖ وَأَمَّا مَا\nيَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ\u{a0}١٧\n\u{2} \n        \n           \n         \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}لِلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِينَ لَمۡ يَسۡتَجِيبُواْ لَهُۥ\nلَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦٓۚ\nأُوْلَٰٓئِكَ لَهُمۡ سُوٓءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ\u{a0}١٨\n\u{2}       \n          \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ\nأُوْلُواْ ٱلۡأَلۡبَٰبِ\u{a0}١٩\u{2}            \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ\nأَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِ أُوْلَٰٓئِكَ لَهُمُ ٱللَّعۡنَةُ\nوَلَهُمۡ سُوٓءُ ٱلدَّارِ\u{a0}٢٥\u{2}        \n          \n  \u{a0}\u{1}\u{2}\u{2}12\u{2}ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ\nبِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعٞ\u{a0}٢٦\u{2}      \n        \u{a0}\u{1}\u{2}12\u{2}\u{2}وَيَقُولُ\nٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ يُضِلُّ\nمَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَنۡ أَنَابَ\u{a0}٢٧\u{2}\n           \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ\nقُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ\u{a0}٢٨\n\u{2}  \n       \u{a0}\n\u{1}\u{2}\u{2}2\u{2}ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ\nمَـَٔابٖ\u{a0}٢٩\u{2}      \n\u{a0}\u{1}\u{2}\u{2}\u{2}كَذَٰلِكَ أَرۡسَلۡنَٰكَ فِيٓ أُمَّةٖ قَدۡ خَلَتۡ مِن قَبۡلِهَآ أُمَمٞ\nلِّتَتۡلُوَاْ عَلَيۡهِمُ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَهُمۡ يَكۡفُرُونَ بِٱلرَّحۡمَٰنِۚ\nقُلۡ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ\u{a0}٣٠\n\u{2}        \n       \n          \u{a0}\n\u{1}\u{2}5\u{2}\u{2}وَلَوۡ أَنَّ قُرۡءَانٗا سُيِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ\nبِهِ ٱلۡمَوۡتَىٰۗ بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِيعًاۗ أَفَلَمۡ يَاْيۡـَٔسِ ٱلَّذِينَ ءَامَنُوٓاْ\nأَن لَّوۡ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعٗاۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ\nتُصِيبُهُم بِمَا صَنَعُواْ قَارِعَةٌ أَوۡ تَحُلُّ قَرِيبٗا مِّن دَارِهِمۡ حَتَّىٰ يَأۡتِيَ\nوَعۡدُ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ\u{a0}٣١\u{2}           \n         \n          \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ\nمِّن قَبۡلِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ\nعِقَابِ\u{a0}٣٢\u{2}  \n        \n\u{a0}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}۞ مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nأُكُلُهَا دَآئِمٞ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِينَ ٱتَّقَواْۚ وَّعُقۡبَى\nٱلۡكَٰفِرِينَ ٱلنَّارُ\u{a0}٣٥\u{2}        \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَفۡرَحُونَ\nبِمَآ أُنزِلَ إِلَيۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن يُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَآ أُمِرۡتُ\nأَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ إِلَيۡهِ أَدۡعُواْ وَإِلَيۡهِ مَـَٔابِ\u{a0}٣٦\n\u{2}   \n          \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ\u{a0}٣٩\n\u{2}       \u{a0}\n\u{1}\u{2}11\u{2}\u{2}وَإِن مَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيۡكَ\nٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ\u{a0}٤٠\u{2}         \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَسۡتَ مُرۡسَلٗاۚ قُلۡ كَفَىٰ بِٱللَّهِ\nشَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَٰبِ\u{a0}٤٣\n\u{2}       \n      \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَسۡتَحِبُّونَ\nٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ\nوَيَبۡغُونَهَا عِوَجًاۚ أُوْلَٰٓئِكَ فِي ضَلَٰلِۭ بَعِيدٖ\u{a0}٣\u{2} \n       \n     \u{a0}\u{1}\u{2}\u{2}12\u{2}وَمَآ أَرۡسَلۡنَا\nمِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ\nمَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٤\n\u{2} \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ تَأَذَّنَ\nرَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ\nعَذَابِي لَشَدِيدٞ\u{a0}٧\u{2} \n      \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ\nجَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ\u{a0}٨\u{2}       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ\nمِن قَبۡلِكُمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ\nبَعۡدِهِمۡ لَا يَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ\nفَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ وَقَالُوٓاْ إِنَّا كَفَرۡنَا بِمَآ أُرۡسِلۡتُم\nبِهِۦ وَإِنَّا لَفِي شَكّٖ مِّمَّا تَدۡعُونَنَآ إِلَيۡهِ مُرِيبٖ\u{a0}٩\u{2}   \n       \n       \n        \n       \u{a0}\u{1}\u{2}11\u{2}\u{2}۞ قَالَتۡ\nرُسُلُهُمۡ أَفِي ٱللَّهِ شَكّٞ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَدۡعُوكُمۡ\nلِيَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرَكُمۡ إِلَىٰٓ أَجَلٖ\nمُّسَمّٗىۚ قَالُوٓاْ إِنۡ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا تُرِيدُونَ أَن تَصُدُّونَا\nعَمَّا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتُونَا بِسُلۡطَٰنٖ مُّبِينٖ\u{a0}١٠\n\u{2}\n       \n      \n         \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ\nوَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ\u{a0}١٢\n\u{2}        \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِينَ كَفَرُواْ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ\nأَرۡضِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۖ فَأَوۡحَىٰٓ إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ\nٱلظَّٰلِمِينَ\u{a0}١٣\u{2}     \n        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ\nوَيَأۡتِيهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانٖ وَمَا هُوَ بِمَيِّتٖۖ وَمِن\nوَرَآئِهِۦ عَذَابٌ غَلِيظٞ\u{a0}١٧\u{2}   \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}مَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ\nأَعۡمَٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ لَّا يَقۡدِرُونَ\nمِمَّا كَسَبُواْ عَلَىٰ شَيۡءٖۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ\u{a0}١٨\n\u{2}   \n         \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}11\u{2}وَقَالَ ٱلشَّيۡطَٰنُ\nلَمَّا قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ\nفَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ\nفَٱسۡتَجَبۡتُمۡ لِيۖ فَلَا تَلُومُونِي وَلُومُوٓاْ أَنفُسَكُمۖ مَّآ أَنَا۠\nبِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ إِنِّي كَفَرۡتُ بِمَآ\nأَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ\u{a0}٢٢\n\u{2} \n        \n         \n       \n      \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}3\u{2}وَمَثَلُ كَلِمَةٍ خَبِيثَةٖ\nكَشَجَرَةٍ خَبِيثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارٖ\u{a0}٢٦\n\u{2}  \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ\nٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَۚ وَيَفۡعَلُ\nٱللَّهُ مَا يَشَآءُ\u{a0}٢٧\u{2}       \n      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا\nوَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ\u{a0}٢٨\u{2}       \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ ٱلَّذِي خَلَقَ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ\nبِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِيَ\nفِي ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَٰرَ\u{a0}٣٢\u{2}  \n      \n        \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ\nقَالَ إِبۡرَٰهِيمُ رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا وَٱجۡنُبۡنِي وَبَنِيَّ\nأَن نَّعۡبُدَ ٱلۡأَصۡنَامَ\u{a0}٣٥\u{2}\n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِيرٗا مِّنَ ٱلنَّاسِۖ\nفَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ وَمَنۡ عَصَانِي فَإِنَّكَ غَفُورٞ رَّحِيمٞ\u{a0}٣٦\n\u{2}     \n        \u{a0}\n\u{1}\u{2}6\u{2}\u{2}رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ\nٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ\nتَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ\u{a0}٣٧\n\u{2}          \n       \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}رَبَّنَآ إِنَّكَ تَعۡلَمُ مَا نُخۡفِي وَمَا نُعۡلِنُۗ وَمَا يَخۡفَىٰ عَلَى ٱللَّهِ مِن شَيۡءٖ\nفِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ\u{a0}٣٨\u{2}            \n    \u{a0}\u{1}\u{2}\u{2}11\u{2}ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي وَهَبَ لِي\nعَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ\u{a0}٣٩\n\u{2}    \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ\nدُعَآءِ\u{a0}٤٠\u{2}       \n\u{a0}\u{1}\u{2}\u{2}\u{2}رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ\nٱلۡحِسَابُ\u{a0}٤١\u{2}      \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}مُهۡطِعِينَ مُقۡنِعِي رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ\nهَوَآءٞ\u{a0}٤٣\u{2}       \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَأَنذِرِ ٱلنَّاسَ يَوۡمَ يَأۡتِيهِمُ ٱلۡعَذَابُ فَيَقُولُ ٱلَّذِينَ\nظَلَمُواْ رَبَّنَآ أَخِّرۡنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖ نُّجِبۡ دَعۡوَتَكَ وَنَتَّبِعِ\nٱلرُّسُلَۗ أَوَلَمۡ تَكُونُوٓاْ أَقۡسَمۡتُم مِّن قَبۡلُ مَا لَكُم\nمِّن زَوَالٖ\u{a0}٤٤\u{2}      \n        \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَسَكَنتُمۡ فِي مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓاْ\nأَنفُسَهُمۡ وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا\nلَكُمُ ٱلۡأَمۡثَالَ\u{a0}٤٥\u{2}    \n      \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَدۡ مَكَرُواْ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ\nمَكۡرُهُمۡ وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ\u{a0}٤٦\n\u{2}    \n      \u{a0}\n\u{1}\u{2}9\u{2}\u{2}فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ إِنَّ ٱللَّهَ عَزِيزٞ\nذُو ٱنتِقَامٖ\u{a0}٤٧\u{2}        \n \u{a0}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}هَٰذَا بَلَٰغٞ لِّلنَّاسِ وَلِيُنذَرُواْ\nبِهِۦ وَلِيَعۡلَمُوٓاْ أَنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَلِيَذَّكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ\u{a0}٥٢\n\u{2}   \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَّوۡ مَا تَأۡتِينَا بِٱلۡمَلَٰٓئِكَةِ إِن كُنتَ\nمِنَ ٱلصَّٰدِقِينَ\u{a0}٧\u{2}     \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا يَأۡتِيهِم مِّن\nرَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\u{a0}١١\u{2}  \n    \u{a0}\u{1}\u{2}\u{2}\u{2}كَذَٰلِكَ نَسۡلُكُهُۥ فِي\nقُلُوبِ ٱلۡمُجۡرِمِينَ\u{a0}١٢\u{2}  \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَجَعَلۡنَا لَكُمۡ فِيهَا\nمَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ\u{a0}٢٠\u{2}  \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا\nخَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ\u{a0}٢١\u{2}    \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَرۡسَلۡنَا ٱلرِّيَٰحَ\nلَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ\nبِخَٰزِنِينَ\u{a0}٢٢\u{2} \n        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ\nمِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ\u{a0}٢٦\u{2}  \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ\nٱلسَّمُومِ\u{a0}٢٧\u{2}     \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن\nصَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ\u{a0}٢٨\u{2}       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن\nرُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ\u{a0}٢٩\u{2}    \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ لَمۡ أَكُن\nلِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ\u{a0}٣٣\u{2}  \n       \u{a0}\u{1}\u{2}2\u{2}\u{2}قَالَ\nفَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ\u{a0}٣٤\u{2}\n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ\u{a0}٤٩\u{2}     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ\u{a0}٦٨\u{2}     \u{a0}\u{1}\u{2}14\u{2}\u{2}وَٱتَّقُواْ\nٱللَّهَ وَلَا تُخۡزُونِ\u{a0}٦٩\u{2}\n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ\nٱلۡعَظِيمَ\u{a0}٨٧\u{2}     \n\u{a0}\u{1}\u{2}\u{2}\u{2}لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ\nوَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ\u{a0}٨٨\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَقُلۡ إِنِّيٓ\nأَنَا ٱلنَّذِيرُ ٱلۡمُبِينُ\u{a0}٨٩\u{2} \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ\nأَنۡ أَنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ\u{a0}٢\u{2}         \n       \u{a0}\u{1}\u{2}\u{2}\u{2}خَلَقَ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَٰلَىٰ عَمَّا يُشۡرِكُونَ\u{a0}٣\u{2} \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗۖ لَّكُم مِّنۡهُ\nشَرَابٞ وَمِنۡهُ شَجَرٞ فِيهِ تُسِيمُونَ\u{a0}١٠\u{2}       \n    \u{a0}\u{1}\u{1}\u{2}\u{2}10\u{2}وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ\nمُسَخَّرَٰتُۢ بِأَمۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ\u{a0}١٢\n\u{2}      \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَا ذَرَأَ لَكُمۡ فِي ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَٰنُهُۥٓۚ إِنَّ\nفِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَذَّكَّرُونَ\u{a0}١٣\u{2}       \n    \u{a0}\u{1}\u{2}12\u{2}\u{2}وَهُوَ ٱلَّذِي\nسَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُواْ\nمِنۡهُ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ\nوَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}١٤\n\u{2} \n      \n      \n    \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}أَمۡوَٰتٌ غَيۡرُ\nأَحۡيَآءٖۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ\u{a0}٢١\u{2} \n    \u{a0}\u{1}\u{2}\u{2}8\u{2}إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۚ\nفَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ قُلُوبُهُم مُّنكِرَةٞ وَهُم مُّسۡتَكۡبِرُونَ\u{a0}٢٢\n\u{2}  \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ\nلَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ\u{a0}٢٣\u{2}         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمۡ\nقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ\u{a0}٢٤\u{2}     \n  \u{a0}\u{1}\u{2}\u{2}\u{2}لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ\nيَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ أَلَا\nسَآءَ مَا يَزِرُونَ\u{a0}٢٥\u{2}  \n        \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَقِيلَ\nلِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرٗاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي\nهَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ\u{a0}٣٠\n\u{2}\n         \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ لَهُمۡ فِيهَا\nمَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ\u{a0}٣١\u{2}        \n     \u{a0}\u{1}\u{2}10\u{2}\u{2}ٱلَّذِينَ تَتَوَفَّىٰهُمُ\nٱلۡمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيۡكُمُ ٱدۡخُلُواْ ٱلۡجَنَّةَ بِمَا\nكُنتُمۡ تَعۡمَلُونَ\u{a0}٣٢\u{2} \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ\nأَوۡ يَأۡتِيَ أَمۡرُ رَبِّكَۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ\nٱللَّهُ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ\u{a0}٣٣\u{2}     \n          \n    \u{a0}\u{1}\u{2}14\u{2}\u{2}فَأَصَابَهُمۡ\nسَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\u{a0}٣٤\n\u{2}\n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لِيُبَيِّنَ لَهُمُ ٱلَّذِي يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ\nكَانُواْ كَٰذِبِينَ\u{a0}٣٩\u{2}        \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ\nٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ فَإِيَّٰيَ فَٱرۡهَبُونِ\u{a0}٥١\u{2}    \n      \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ\nإِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِيقٞ مِّنكُم بِرَبِّهِمۡ يُشۡرِكُونَ\u{a0}٥٤\n\u{2}\n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن\nيُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ\nسَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ\u{a0}٦١\u{2}          \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ\nوَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ\nلَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ\u{a0}٦٢\u{2}   \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن\nقَبۡلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ\nعَذَابٌ أَلِيمٞ\u{a0}٦٣\u{2}     \n        \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ\nلَأٓيَةٗ لِّقَوۡمٖ يَسۡمَعُونَ\u{a0}٦٥\u{2}            \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا\nفِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّٰرِبِينَ\u{a0}٦٦\n\u{2}      \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ كُلِي\nمِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا\nشَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ\nيَتَفَكَّرُونَ\u{a0}٦٩\u{2} \n         \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ\nٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمٖ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمٞ قَدِيرٞ\u{a0}٧٠\u{2}        \n          \u{a0}\u{1}\u{2}10\u{2}\u{2}وَٱللَّهُ\nفَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ بِرَآدِّي\nرِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ\nٱللَّهِ يَجۡحَدُونَ\u{a0}٧١\u{2}\n         \n        \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا\nمَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا\nفَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ\nبَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ\u{a0}٧٥\u{2}   \n         \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلَيۡنِ\nأَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَهُوَ كَلٌّ عَلَىٰ\nمَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن\nيَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ\u{a0}٧٦\u{2}   \n        \n         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَلِلَّهِ غَيۡبُ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ\nأَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٧٧\u{2} \n       \n        \u{a0}\u{1}\u{2}11\u{2}13\u{2}وَٱللَّهُ\nأَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـٔٗا وَجَعَلَ\nلَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}٧٨\n\u{2}\n       \n     \u{a0}\n\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلٗا وَجَعَلَ لَكُم\nمِّنَ ٱلۡجِبَالِ أَكۡنَٰنٗا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ\nٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ\nعَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ\u{a0}٨١\u{2}       \n      \n      \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ\nقَالُواْ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ\nفَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ\u{a0}٨٦\u{2}    \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَلۡقَوۡاْ\nإِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ\u{a0}٨٧\n\u{2}\n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابٗا فَوۡقَ\nٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ\u{a0}٨٨\u{2}        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ نَبۡعَثُ فِي كُلِّ\nأُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ\nهَٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ وَهُدٗى\nوَرَحۡمَةٗ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ\u{a0}٨٩\u{2}   \n        \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ\nوَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ\nوَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ\u{a0}٩٠\n\u{2}   \n      \n    \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ\nغَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثٗا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا\nبَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ\nٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ\u{a0}٩٢\n\u{2}   \n       \n         \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا\nوَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ\nعَظِيمٞ\u{a0}٩٤\u{2}        \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ إِنَّمَا عِندَ ٱللَّهِ\nهُوَ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\u{a0}٩٥\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}مَا عِندَكُمۡ يَنفَدُ\nوَمَا عِندَ ٱللَّهِ بَاقٖۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ\nمَا كَانُواْ يَعۡمَلُونَ\u{a0}٩٦\u{2}  \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ\nأَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ\nأَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ\u{a0}٩٧\u{2}    \n       \n    \u{a0}\u{1}\u{2}8\u{2}\u{2}فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ\nفَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ\u{a0}٩٨\u{2}  \n    \u{a0}\u{1}\u{2}9\u{2}10\u{2}إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ\nعَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ\u{a0}٩٩\u{2}   \n     \u{a0}\u{1}\u{2}10\u{2}11\u{2}إِنَّمَا\nسُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ\u{a0}١٠٠\n\u{2}\n       \u{a0}\n\u{1}\u{2}\u{2}13\u{2}وَإِذَا بَدَّلۡنَآ ءَايَةٗ مَّكَانَ ءَايَةٖ وَٱللَّهُ أَعۡلَمُ\nبِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ\u{a0}١٠١\n\u{2}      \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِيُثَبِّتَ\nٱلَّذِينَ ءَامَنُواْ وَهُدٗى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ\u{a0}١٠٢\n\u{2}       \n    \u{a0}\n\u{1}\u{2}\u{2}3\u{2}وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٞۗ لِّسَانُ\nٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيّٞ وَهَٰذَا لِسَانٌ عَرَبِيّٞ\nمُّبِينٌ\u{a0}١٠٣\u{2}       \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ\nٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِيمٌ\u{a0}١٠٤\u{2}       \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ\nوَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا\nفَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ\u{a0}١٠٦\n\u{2}        \n       \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ\nوَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ\u{a0}١٠٧\u{2}      \n     \u{a0}\u{1}\u{2}10\u{2}\u{2}أُوْلَٰٓئِكَ\nٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ\nوَأُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ\u{a0}١٠٨\u{2}\n      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}لَا جَرَمَ أَنَّهُمۡ فِي\nٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ\u{a0}١٠٩\u{2}   \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ يَوۡمَ تَأۡتِي كُلُّ نَفۡسٖ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ\nنَفۡسٖ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ\u{a0}١١١\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَضَرَبَ ٱللَّهُ مَثَلٗا\nقَرۡيَةٗ كَانَتۡ ءَامِنَةٗ مُّطۡمَئِنَّةٗ يَأۡتِيهَا رِزۡقُهَا رَغَدٗا\nمِّن كُلِّ مَكَانٖ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ\nٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ\u{a0}١١٢\u{2}  \n      \n        \n    \u{a0}\u{1}\u{2}\u{2}7\u{2}وَلَقَدۡ\nجَآءَهُمۡ رَسُولٞ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ\nظَٰلِمُونَ\u{a0}١١٣\u{2}\n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗا\nوَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ\u{a0}١١٤\n\u{2}     \n      \u{a0}\n\u{1}\u{2}9\u{2}\u{2}إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ\nأُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ\nٱللَّهَ غَفُورٞ رَّحِيمٞ\u{a0}١١٥\u{2}       \n          \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ\nٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ\nإِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ\u{a0}١١٦\u{2}    \n        \n       \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ\nبَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ\u{a0}١١٩\n\u{2}         \n        \u{a0}\n\u{1}\u{2}3\u{2}\u{2}إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ\u{a0}١٢٠\n\u{2}          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ\nٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا\nكَانُواْ فِيهِ يَخۡتَلِفُونَ\u{a0}١٢٤\u{2}    \n        \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ\nلَهُوَ خَيۡرٞ لِّلصَّٰبِرِينَ\u{a0}١٢٦\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ\nوَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ\u{a0}١٢٧\n\u{2}    \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ\nإِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ\nهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ\u{a0}١\u{2}       \n         \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا\nعَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ\nوَكَانَ وَعۡدٗا مَّفۡعُولٗا\u{a0}٥\u{2}    \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ\nوَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا\u{a0}٦\n\u{2}    \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ\nوَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ\nكَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا\u{a0}٧\n\u{2}        \n     \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}وَكُلَّ\nإِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا\nيَلۡقَىٰهُ مَنشُورًا\u{a0}١٣\u{2}\n         \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَكَمۡ أَهۡلَكۡنَا مِنَ\nٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا\u{a0}١٧\n\u{2}  \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}كُلّٗا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنۡ عَطَآءِ\nرَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا\u{a0}٢٠\u{2}     \n     \u{a0}\u{1}\u{2}\u{2}6\u{2}ٱنظُرۡ كَيۡفَ فَضَّلۡنَا\nبَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتٖ وَأَكۡبَرُ تَفۡضِيلٗا\u{a0}٢١\n\u{2}  \n       \u{a0}\n\u{1}\u{2}\u{2}7\u{2}لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا\u{a0}٢٢\n\u{2}        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا\nيَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ\nأُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا\u{a0}٢٣\u{2}        \n        \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱخۡفِضۡ\nلَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي\nصَغِيرٗا\u{a0}٢٤\u{2}\n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن\nقُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي\nٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا\u{a0}٣٣\u{2}        \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ\nإِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا\u{a0}٣٦\n\u{2}      \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا\u{a0}٥٠\u{2}    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ\nوَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا\u{a0}٥٢\u{2}   \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ\nأَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ\nعَدُوّٗا مُّبِينٗا\u{a0}٥٣\u{2}    \n        \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَرَبُّكَ أَعۡلَمُ\nبِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ\nوَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا\u{a0}٥٥\u{2} \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا\nيَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا\u{a0}٥٦\u{2}      \n     \u{a0}\u{1}\u{2}\u{2}13\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ\nيَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ\nرَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورٗا\u{a0}٥٧\n\u{2} \n       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا\nجَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ\nفِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا\u{a0}٦٠\n\u{2}       \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ\nفِي ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمٗا\u{a0}٦٦\n\u{2}    \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ\nإِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا\u{a0}٦٧\u{2}           \n     \u{a0}\u{1}\u{2}\u{2}\u{2}أَفَأَمِنتُمۡ أَن يَخۡسِفَ\nبِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ\nوَكِيلًا\u{a0}٦٨\u{2}  \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ\nعَلَيۡكُمۡ قَاصِفٗا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُواْ\nلَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعٗا\u{a0}٦٩\u{2}       \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ وَحَمَلۡنَٰهُمۡ\nفِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَىٰ\nكَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا\u{a0}٧٠\u{2}    \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ\nبِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ يَقۡرَءُونَ\nكِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا\u{a0}٧١\u{2}   \n      \n   \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}وَمَن كَانَ فِي هَٰذِهِۦٓ\nأَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا\u{a0}٧٢\u{2}   \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِن كَادُواْ\nلَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ\nوَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا\u{a0}٧٣\u{2} \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ\nتَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا\u{a0}٧٤\u{2}    \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}سُنَّةَ مَن قَدۡ\nأَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا\u{a0}٧٧\u{2}  \n       \u{a0}\u{1}\u{2}\u{2}\u{2}أَقِمِ\nٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ\nقُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا\u{a0}٧٨\u{2}\n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ\nنَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا\u{a0}٧٩\u{2}   \n       \u{a0}\u{1}\u{2}6\u{2}\u{2}وَقُل رَّبِّ\nأَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن\nلَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا\u{a0}٨٠\u{2} \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ\nإِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا\u{a0}٨١\u{2}    \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ\nوَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا\u{a0}٨٢\u{2}     \n      \u{a0}\u{1}\u{2}10\u{2}11\u{2}وَإِذَآ\nأَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسٗا\u{a0}٨٣\n\u{2}\n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُلۡ كُلّٞ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ\nسَبِيلٗا\u{a0}٨٤\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي\nوَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا\u{a0}٨٥\u{2}       \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُل\nلَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ\nلَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا\u{a0}٨٨\u{2}\n         \n       \u{a0}\u{1}\u{2}3\u{2}\u{2}وَلَقَدۡ\nصَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ\nإِلَّا كُفُورٗا\u{a0}٨٩\u{2}\n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ\nٱلۡأَرۡضِ يَنۢبُوعًا\u{a0}٩٠\u{2}       \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَوۡ تَكُونَ لَكَ جَنَّةٞ مِّن نَّخِيلٖ وَعِنَبٖ\nفَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا\u{a0}٩١\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}8\u{2}أَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا\nزَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ قَبِيلًا\u{a0}٩٢\n\u{2}   \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَوۡ يَكُونَ لَكَ بَيۡتٞ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ وَلَن نُّؤۡمِنَ\nلِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّي هَلۡ\nكُنتُ إِلَّا بَشَرٗا رَّسُولٗا\u{a0}٩٣\u{2}           \n         \n   \u{a0}\u{1}\u{2}\u{2}12\u{2}وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ\nٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرٗا رَّسُولٗا\u{a0}٩٤\u{2}      \n       \u{a0}\u{1}\u{2}12\u{2}\u{2}قُل لَّوۡ كَانَ\nفِي ٱلۡأَرۡضِ مَلَٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم\nمِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا\u{a0}٩٥\u{2}  \n      \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ\nٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ\nوَجَعَلَ لَهُمۡ أَجَلٗا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورٗا\u{a0}٩٩\n\u{2}   \n        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ\nيَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا\u{a0}٢\u{2}        \n     \u{a0}\u{1}\u{2}14\u{2}\u{2}مَّٰكِثِينَ\nفِيهِ أَبَدٗا\u{a0}٣\u{2}\n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ\nوَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا\u{a0}١٠\u{2}          \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ فِي\nٱلۡكَهۡفِ سِنِينَ عَدَدٗا\u{a0}١١\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ بَعَثۡنَٰهُمۡ لِنَعۡلَمَ أَيُّ ٱلۡحِزۡبَيۡنِ\nأَحۡصَىٰ لِمَا لَبِثُوٓاْ أَمَدٗا\u{a0}١٢\u{2}    \n   \u{a0}\u{1}\u{2}\u{2}\u{2}نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَهُم بِٱلۡحَقِّۚ\nإِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى\u{a0}١٣\u{2}    \n     \u{a0}\u{1}\u{2}11\u{2}\u{2}وَرَبَطۡنَا\nعَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُواْ فَقَالُواْ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nلَن نَّدۡعُوَاْ مِن دُونِهِۦٓ إِلَٰهٗاۖ لَّقَدۡ قُلۡنَآ إِذٗا شَطَطًا\u{a0}١٤\u{2}\n        \n        \u{a0}\u{1}\u{2}13\u{2}\u{2}هَٰٓؤُلَآءِ\nقَوۡمُنَا ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ لَّوۡلَا يَأۡتُونَ عَلَيۡهِم\nبِسُلۡطَٰنِۭ بَيِّنٖۖ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا\u{a0}١٥\n\u{2}\n       \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ\nٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةٖ\nمِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن\nيُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِيّٗا مُّرۡشِدٗا\u{a0}١٧\u{2}       \n        \n          \n     \u{a0}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}سَيَقُولُونَ ثَلَٰثَةٞ\nرَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةٞ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا\nبِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةٞ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ أَعۡلَمُ\nبِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلٞۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءٗ ظَٰهِرٗا\nوَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا\u{a0}٢٢\u{2} \n      \n       \n          \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ\nيُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ\nٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ\nأَمۡرُهُۥ فُرُطٗا\u{a0}٢٨\u{2}       \n        \n          \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَٱضۡرِبۡ\nلَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا\nبِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا\u{a0}٣٢\u{2}\n        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي\nلَأَجِدَنَّ خَيۡرٗا مِّنۡهَا مُنقَلَبٗا\u{a0}٣٦\u{2}       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ\nأَكَفَرۡتَ بِٱلَّذِي خَلَقَكَ مِن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ سَوَّىٰكَ رَجُلٗا\u{a0}٣٧\n\u{2}    \n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡلَآ إِذۡ\nدَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠\nأَقَلَّ مِنكَ مَالٗا وَوَلَدٗا\u{a0}٣٩\u{2} \n            \n   \u{a0}\u{1}\u{2}\u{2}9\u{2}فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرٗا مِّن\nجَنَّتِكَ وَيُرۡسِلَ عَلَيۡهَا حُسۡبَانٗا مِّنَ ٱلسَّمَآءِ فَتُصۡبِحَ صَعِيدٗا\nزَلَقًا\u{a0}٤٠\u{2}     \n       \n\u{a0}\u{1}\u{2}9\u{2}\u{2}أَوۡ يُصۡبِحَ مَآؤُهَا غَوۡرٗا فَلَن تَسۡتَطِيعَ لَهُۥ طَلَبٗا\u{a0}٤١\n\u{2}       \u{a0}\n\u{1}\u{2}10\u{2}\u{2}وَأُحِيطَ بِثَمَرِهِۦ فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ\nعَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدٗا\u{a0}٤٢\u{2}          \n       \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ مَّآ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّينَ عَضُدٗا\u{a0}٥١\n\u{2}   \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ\nإِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ\nلِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوٗا\u{a0}٥٦\u{2}  \n      \n       \u{a0}\u{1}\u{2}6\u{2}9\u{2}وَمَنۡ\nأَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ\nإِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۖ\nوَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا أَبَدٗا\u{a0}٥٧\u{2}\n          \n         \n       \u{a0}\u{1}\u{2}9\u{2}11\u{2}وَرَبُّكَ\nٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ يُؤَاخِذُهُم بِمَا كَسَبُواْ لَعَجَّلَ لَهُمُ\nٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدٞ لَّن يَجِدُواْ مِن دُونِهِۦ مَوۡئِلٗا\u{a0}٥٨\n\u{2}\n        \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَتِلۡكَ ٱلۡقُرَىٰٓ أَهۡلَكۡنَٰهُمۡ لَمَّا ظَلَمُواْ وَجَعَلۡنَا لِمَهۡلِكِهِم\nمَّوۡعِدٗا\u{a0}٥٩\u{2}      \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا بَلَغَا\nمَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبٗا\u{a0}٦١\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَوَجَدَا عَبۡدٗا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةٗ مِّنۡ\nعِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمٗا\u{a0}٦٥\u{2}      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ\nعَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا\u{a0}٦٦\u{2}    \n     \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ إِنَّكَ لَن تَسۡتَطِيعَ\nمَعِيَ صَبۡرٗا\u{a0}٦٧\u{2}   \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ\nفَإِنِ ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرٗا\u{a0}٧٠\n\u{2}\n          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا\u{a0}٧٥\u{2}        \u{a0}\u{1}\u{2}\u{2}2\u{2}قَالَ إِن\nسَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا\u{a0}٧٦\n\u{2} \n          \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَمَّا\nٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا\nوَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا\u{a0}٧٩\u{2}\n        \n      \u{a0}\u{1}\u{2}\u{2}9\u{2}وَأَمَّا ٱلۡغُلَٰمُ\nفَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا\u{a0}٨٠\n\u{2} \n       \u{a0}\n\u{1}'
    '\u{2}\u{2}10\u{2}فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرٗا مِّنۡهُ زَكَوٰةٗ وَأَقۡرَبَ رُحۡمٗا\u{a0}٨١\n\u{2}        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ\nتَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ\nأَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ\nعَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا\u{a0}٨٢\u{2}       \n         \n       \n        \u{a0}\u{1}\u{2}14\u{2}\u{2}وَيَسۡـَٔلُونَكَ\nعَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا\u{a0}٨٣\n\u{2}\n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}1\u{2}فَأَتۡبَعَ سَبَبًا\u{a0}٨٥\n\u{2} \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}حَتَّىٰٓ\nإِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمٖ لَّمۡ نَجۡعَل لَّهُم مِّن\nدُونِهَا سِتۡرٗا\u{a0}٩٠\u{2}\n           \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ أَتۡبَعَ\nسَبَبًا\u{a0}٩٢\u{2} \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ\nمُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ\nسَدّٗا\u{a0}٩٤\u{2}     \n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ\nوَبَيۡنَهُمۡ رَدۡمًا\u{a0}٩٥\u{2}         \n \u{a0}\u{1}\u{2}\u{2}14\u{2}ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ\nقَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا\u{a0}٩٦\n\u{2}       \n          \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذٖ يَمُوجُ فِي بَعۡضٖۖ وَنُفِخَ فِي ٱلصُّورِ\nفَجَمَعۡنَٰهُمۡ جَمۡعٗا\u{a0}٩٩\u{2}        \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا\u{a0}١٠٠\n\u{2}    \u{a0}\n\u{1}\u{2}4\u{2}5\u{2}ٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ\nسَمۡعًا\u{a0}١٠١\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ\nأَوۡلِيَآءَۚ إِنَّآ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلٗا\u{a0}١٠٢\u{2}       \n     \u{a0}\u{1}\u{2}\u{2}7\u{2}قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ\nأَعۡمَٰلًا\u{a0}١٠٣\u{2}   \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ\nيُحۡسِنُونَ صُنۡعًا\u{a0}١٠٤\u{2}        \n \u{a0}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ\nفَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا\u{a0}١٠٥\u{2}     \n       \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ جَزَآؤُهُمۡ\nجَهَنَّمُ بِمَا كَفَرُواْ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَرُسُلِي هُزُوًا\u{a0}١٠٦\u{2} \n      \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ءَامَنُواْ\nوَعَمِلُواْ ٱلصَّٰلِحَٰتِ كَانَتۡ لَهُمۡ جَنَّٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا\u{a0}١٠٧\u{2}  \n      \u{a0}\u{1}\u{2}\u{2}\u{2}خَٰلِدِينَ\nفِيهَا لَا يَبۡغُونَ عَنۡهَا حِوَلٗا\u{a0}١٠٨\u{2}\n    \u{a0}\u{1}\u{2}\u{2}\u{2}قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادٗا لِّكَلِمَٰتِ رَبِّي\nلَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّي وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدٗا\u{a0}١٠٩\u{2}      \n          \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ\nإِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَمَن كَانَ يَرۡجُواْ\nلِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا\u{a0}١١٠\n\u{2}\n            \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ\u{a0}٢\n\u{2}    \u{a0}\n\u{1}\u{2}4\u{2}\u{2}إِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا\u{a0}٣\u{2}    \u{a0}\u{1}\u{2}\u{2}6\u{2}قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ\nمِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ\nشَقِيّٗا\u{a0}٤\u{2}    \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ\nٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا\u{a0}٥\u{2}     \n      \u{a0}\u{1}\u{2}\u{2}\u{2}يَرِثُنِي وَيَرِثُ\nمِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا\u{a0}٦\u{2} \n     \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰزَكَرِيَّآ\nإِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا\u{a0}٧\n\u{2}\n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي\nعَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا\u{a0}٨\u{2}       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ كَذَٰلِكَ\nقَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٞ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ\nشَيۡـٔٗا\u{a0}٩\u{2} \n          \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَخَرَجَ عَلَىٰ قَوۡمِهِۦ\nمِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا\u{a0}١١\n\u{2}  \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ فَحَمَلَتۡهُ فَٱنتَبَذَتۡ\nبِهِۦ مَكَانٗا قَصِيّٗا\u{a0}٢٢\u{2} \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ\nإِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا\u{a0}٢٦\n\u{2}         \n       \u{a0}\n\u{1}\u{2}3\u{2}4\u{2}فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا\nفَرِيّٗا\u{a0}٢٧\u{2}        \n\u{a0}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}1\u{2}وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةٖ وَهُمۡ لَا يُؤۡمِنُونَ\u{a0}٣٩\n\u{2}           \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَعُونَ\u{a0}٤٠\u{2}       \u{a0}\u{1}\u{2}2\u{2}\u{2}وَٱذۡكُرۡ\nفِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا\u{a0}٤١\u{2}\n      \u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَ لِأَبِيهِ يَٰٓأَبَتِ\nلِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـٔٗا\u{a0}٤٢\u{2}   \n          \u{a0}\u{1}\u{2}4\u{2}\u{2}يَٰٓأَبَتِ\nإِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطٗا\nسَوِيّٗا\u{a0}٤٣\u{2}\n          \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ\nأَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيّٗا\u{a0}٤٨\u{2}        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ\nمِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلّٗا جَعَلۡنَا نَبِيّٗا\u{a0}٤٩\n\u{2}   \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَوَهَبۡنَا لَهُۥ مِن\nرَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا\u{a0}٥٣\u{2}  \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ\nإِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيّٗا\u{a0}٥٦\u{2}   \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ\nأَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحٖ\nوَمِن ذُرِّيَّةِ إِبۡرَٰهِيمَ وَإِسۡرَٰٓءِيلَ وَمِمَّنۡ هَدَيۡنَا وَٱجۡتَبَيۡنَآۚ إِذَا تُتۡلَىٰ عَلَيۡهِمۡ\nءَايَٰتُ ٱلرَّحۡمَٰنِ خَرُّواْۤ سُجَّدٗاۤ وَبُكِيّٗا۩\u{a0}٥٨\u{2} \n           \n         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ فَخَلَفَ مِنۢ بَعۡدِهِمۡ\nخَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا\u{a0}٥٩\n\u{2}  \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا سَلَٰمٗاۖ\nوَلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَةٗ وَعَشِيّٗا\u{a0}٦٢\u{2}     \n    \u{a0}\u{1}\u{2}\u{2}\u{2}تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِي نُورِثُ مِنۡ\nعِبَادِنَا مَن كَانَ تَقِيّٗا\u{a0}٦٣\u{2}    \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ مَا بَيۡنَ\nأَيۡدِينَا وَمَا خَلۡفَنَا وَمَا بَيۡنَ ذَٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِيّٗا\u{a0}٦٤\n\u{2}       \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ\nلِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرٞ مَّقَامٗا وَأَحۡسَنُ نَدِيّٗا\u{a0}٧٣\u{2}       \n       \u{a0}\u{1}\u{2}10\u{2}\u{2}وَكَمۡ\nأَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثٗا وَرِءۡيٗا\u{a0}٧٤\u{2}\n       \u{a0}\u{1}\u{2}11\u{2}\u{2}قُلۡ مَن\nكَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ\nإِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرّٞ مَّكَانٗا\nوَأَضۡعَفُ جُندٗا\u{a0}٧٥\u{2} \n           \n        \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ\u{a0}١١\n\u{2}   \u{a0}\n\u{1}\u{2}15\u{2}\u{2}إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى\u{a0}١٢\n\u{2}        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ تَمۡشِيٓ أُخۡتُكَ\nفَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ\nعَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّٰكَ فُتُونٗاۚ\nفَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ\u{a0}٤٠\n\u{2}  \n          \n         \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا\nفِي ذِكۡرِي\u{a0}٤٢\u{2}     \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا\nلَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ\u{a0}٤٤\u{2}   \n   \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ\nأَوۡ أَن يَطۡغَىٰ\u{a0}٤٥\u{2}      \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى\u{a0}٥٢\n\u{2}          \u{a0}\n\u{1}'
    '\u{2}2\u{2}\u{2}ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ\nمِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ\u{a0}٥٣\u{2}         \n        \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ مِنۡهَا\nخَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ\u{a0}٥٥\u{2}\n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم\nمِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ\u{a0}٦٣\u{2}      \n     \u{a0}\u{1}\u{2}14\u{2}\u{2}فَأَجۡمِعُواْ\nكَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ\u{a0}٦٤\n\u{2}\n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}2\u{2}قَالَ\nبَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ\u{a0}٦٦\n\u{2}\n          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَآ أَعۡجَلَكَ عَن\nقَوۡمِكَ يَٰمُوسَىٰ\u{a0}٨٣\u{2}  \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ\nيَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ\nٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم\nمَّوۡعِدِي\u{a0}٨٦\u{2}      \n       \n         \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا\nيَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا\u{a0}٨٩\u{2}      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ\nيَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ\nأَمۡرِي\u{a0}٩٠\u{2}     \n        \n\u{a0}\u{1}\u{2}\u{2}5\u{2}قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ\u{a0}٩١\n\u{2}        \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ\u{a0}٩٢\u{2}      \u{a0}\u{1}\u{2}6\u{2}\u{2}أَلَّا تَتَّبِعَنِۖ\nأَفَعَصَيۡتَ أَمۡرِي\u{a0}٩٣\u{2} \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ\nإِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَٰٓءِيلَ وَلَمۡ تَرۡقُبۡ\nقَوۡلِي\u{a0}٩٤\u{2}      \n         \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ بَصُرۡتُ\nبِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ\nفَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي\u{a0}٩٦\u{2} \n        \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَوۡمَئِذٖ يَتَّبِعُونَ ٱلدَّاعِيَ\nلَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسٗا\u{a0}١٠٨\n\u{2}  \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ\nحَمَلَ ظُلۡمٗا\u{a0}١١١\u{2}      \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا\nيَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا\u{a0}١١٢\u{2}      \n   \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا\nوَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا\u{a0}١١٣\n\u{2}   \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَنۡ أَعۡرَضَ عَن\nذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ\nأَعۡمَىٰ\u{a0}١٢٤\u{2}  \n       \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ\u{a0}١٢٦\u{2}       \u{a0}\u{1}\u{2}1\u{2}\u{2}وَكَذَٰلِكَ\nنَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ\nوَأَبۡقَىٰٓ\u{a0}١٢٧\u{2}\n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ\nفِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ\u{a0}١٢٨\u{2}        \n       \u{a0}\u{1}\u{2}4\u{2}\u{2}وَلَوۡلَا كَلِمَةٞ\nسَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى\u{a0}١٢٩\u{2} \n      \u{a0}\u{1}\u{2}5\u{2}7\u{2}فَٱصۡبِرۡ عَلَىٰ\nمَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ\nوَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ\u{a0}١٣٠\u{2} \n         \n       \u{a0}\u{1}\u{2}7\u{2}\u{2}وَلَا\nتَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nلِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ\u{a0}١٣١\u{2}\n          \n     \u{a0}\u{1}\u{2}\u{2}10\u{2}وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ\nوَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ\u{a0}١٣٢\n\u{2}  \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي\nٱلصُّحُفِ ٱلۡأُولَىٰ\u{a0}١٣٣\u{2}          \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ\nلَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن\nقَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ\u{a0}١٣٤\u{2}     \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَاهِيَةٗ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ\nهَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ\nتُبۡصِرُونَ\u{a0}٣\u{2}     \n       \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ\nٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرٞ فَلۡيَأۡتِنَا بِـَٔايَةٖ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ\u{a0}٥\n\u{2}    \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوٗا\nلَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ\u{a0}١٧\u{2}    \n     \u{a0}\u{1}\u{2}\u{2}\u{2}بَلۡ نَقۡذِفُ بِٱلۡحَقِّ\nعَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ\u{a0}١٨\n\u{2}  \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَمِ\nٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ\nوَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ\u{a0}٢٤\n\u{2}\n          \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ\nجَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ\u{a0}٢٩\u{2}        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا\nأَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ\nهُمۡ كَٰفِرُونَ\u{a0}٣٦\u{2}       \n      \n \u{a0}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدِ ٱسۡتُهۡزِئَ\nبِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ\nيَسۡتَهۡزِءُونَ\u{a0}٤١\u{2} \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ\nٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ\u{a0}٤٢\u{2}     \n      \u{a0}\u{1}\u{2}11\u{2}\u{2}أَمۡ\nلَهُمۡ ءَالِهَةٞ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ\nأَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ\u{a0}٤٣\u{2}\n       \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ\nٱلسَّاعَةِ مُشۡفِقُونَ\u{a0}٤٩\u{2}     \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا\nبِهِۦ عَٰلِمِينَ\u{a0}٥١\u{2}      \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ\u{a0}٥٣\n\u{2}    \u{a0}\n\u{1}\u{2}12\u{2}\u{2}قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ\u{a0}٥٤\u{2}       \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُوٓاْ\nأَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ\u{a0}٥٥\u{2}\n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُواْ فَأۡتُواْ بِهِۦ\nعَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ\u{a0}٦١\u{2}  \n    \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُوٓاْ ءَأَنتَ فَعَلۡتَ\nهَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ\u{a0}٦٢\u{2}  \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ نُكِسُواْ عَلَىٰ\nرُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ\u{a0}٦٥\u{2}  \n     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا\nتَعۡقِلُونَ\u{a0}٦٧\u{2}       \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ\nنَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ\u{a0}٧٨\n\u{2}      \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلٗا\nدُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ\u{a0}٨٢\u{2}      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَأَيُّوبَ إِذۡ\nنَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ\u{a0}٨٣\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{2}\u{2}\u{2}إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ\nٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ\u{a0}٩٨\u{2}    \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}5\u{2}يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا\nبَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ\u{a0}١٠٤\n\u{2}      \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ\nيَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ\u{a0}١٠٥\u{2}        \n  \u{a0}\u{1}\u{2}7\u{2}\u{2}إِنَّ فِي هَٰذَا لَبَلَٰغٗا\nلِّقَوۡمٍ عَٰبِدِينَ\u{a0}١٠٦\u{2}   \n \u{a0}\u{1}\u{2}\u{2}8\u{2}وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ\u{a0}١٠٧\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ\nفَهَلۡ أَنتُم مُّسۡلِمُونَ\u{a0}١٠٨\u{2}       \n  \u{a0}\u{1}\u{2}10\u{2}11\u{2}فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ\nعَلَىٰ سَوَآءٖۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدٞ مَّا تُوعَدُونَ\u{a0}١٠٩\n\u{2}   \n        \u{a0}\n\u{1}\u{2}\u{2}12\u{2}إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ\u{a0}١١٠\n\u{2}       \u{a0}\n\u{1}\u{2}\u{2}13\u{2}وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةٞ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينٖ\u{a0}١١١\u{2}       \u{a0}\u{1}\u{2}13\u{2}14\u{2}قَٰلَ\nرَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ\u{a0}١١٢\n\u{2}\n        \u{a0}\n\u{1}\u{2}2\u{2}\u{2}۞يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ\nعَظِيمٞ\u{a0}١\u{2}       \n\u{a0}\u{1}\u{2}3\u{2}5\u{2}يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ\nأَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ\nسُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ\u{a0}٢\n\u{2}     \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ\nشَيۡطَٰنٖ مَّرِيدٖ\u{a0}٣\u{2}         \n \u{a0}\u{1}\u{2}\u{2}\u{2}كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ\nوَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ\u{a0}٤\u{2}      \n   \u{a0}\u{1}\u{2}8\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي\nرَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ\nمِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ\nوَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ\nطِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ\nوَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ\nبَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا\nٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ\u{a0}٥\n\u{2}    \n          \n         \n         \n      \n        \n        \n       \u{a0}\n\u{1}\u{2}\u{2}1\u{2}ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٦\n\u{2}            \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمِنَ ٱلنَّاسِ\nمَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ\nفِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ\nٱلۡخُسۡرَانُ ٱلۡمُبِينُ\u{a0}١١\u{2} \n           \n        \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ\nوَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ\nيَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ\u{a0}١٧\u{2}      \n      \n       \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ أَنَّ ٱللَّهَ\nيَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ\nوَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ\nوَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ\nإِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩\u{a0}١٨\u{2}   \n         \n      \n          \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ\nفِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ\nمِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ\u{a0}١٩\u{2}  \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ\nوَٱلۡجُلُودُ\u{a0}٢٠\u{2}    \n\u{a0}\u{1}\u{1}\u{2}\u{2}12\u{2}كُلَّمَآ أَرَادُوٓاْ\nأَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ\u{a0}٢٢\n\u{2} \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي\nشَيۡـٔٗا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ\nٱلسُّجُودِ\u{a0}٢٦\u{2}        \n     \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}لِّيَشۡهَدُواْ\nمَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ\nعَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ\nٱلۡبَآئِسَ ٱلۡفَقِيرَ\u{a0}٢٨\u{2}\n       \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ\nنُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ\u{a0}٢٩\u{2}   \n   \u{a0}\u{1}\u{2}12\u{2}\u{2}ذَٰلِكَۖ وَمَن\nيُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ\nلَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ\nٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ\u{a0}٣٠\n\u{2} \n        \n      \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلِكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكٗا لِّيَذۡكُرُواْ ٱسۡمَ\nٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ\nفَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ\u{a0}٣٤\u{2}     \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ\nقُلُوبُهُمۡ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا\nرَزَقۡنَٰهُمۡ يُنفِقُونَ\u{a0}٣٥\u{2}    \n       \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ ٱللَّهَ\nيُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٖ كَفُورٍ\u{a0}٣٨\n\u{2} \n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن\nيَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ\nصَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ\nكَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ\nعَزِيزٌ\u{a0}٤٠\u{2}       \n         \n       \n       \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}9\u{2}وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطٖ\u{a0}٤٣\n\u{2}   \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ\nأَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ\u{a0}٤٤\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَكَأَيِّن مِّن قَرۡيَةٍ\nأَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةٞ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا\nوَبِئۡرٖ مُّعَطَّلَةٖ وَقَصۡرٖ مَّشِيدٍ\u{a0}٤٥\u{2}  \n      \n   \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ\nفَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا\nلَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ\u{a0}٤٦\n\u{2}   \n         \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَكَأَيِّن مِّن\nقَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ\u{a0}٤٨\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}6\u{2}وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ\u{a0}٥١\n\u{2}       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ\nأَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ\nثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ\u{a0}٥٢\u{2}          \n        \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}3\u{2}وَٱلَّذِينَ كَفَرُواْ\nوَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ\u{a0}٥٧\n\u{2} \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ\nلَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ\nٱلرَّٰزِقِينَ\u{a0}٥٨\u{2}        \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}لَيُدۡخِلَنَّهُم مُّدۡخَلٗا يَرۡضَوۡنَهُۥۚ وَإِنَّ\nٱللَّهَ لَعَلِيمٌ حَلِيمٞ\u{a0}٥٩\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ\nمَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ\nلَعَفُوٌّ غَفُورٞ\u{a0}٦٠\u{2}   \n         \n \u{a0}\u{1}\u{2}\u{2}10\u{2}ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي\nٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ\u{a0}٦١\n\u{2}     \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن\nدُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ\u{a0}٦٢\n\u{2}        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ\nبِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ\nٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ\u{a0}٦٥\u{2}            \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِيٓ أَحۡيَاكُمۡ\nثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ\u{a0}٦٦\n\u{2}  \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ\nفِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ\u{a0}٧٠\u{2}          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَعۡبُدُونَ مِن دُونِ\nٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمٞۗ وَمَا لِلظَّٰلِمِينَ\nمِن نَّصِيرٖ\u{a0}٧١\u{2}  \n            \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ تَعۡرِفُ فِي\nوُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ\nبِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن\nذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ\u{a0}٧٢\n\u{2}      \n     \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ\nتَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ\nوَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ\nٱلطَّالِبُ وَٱلۡمَطۡلُوبُ\u{a0}٧٣\u{2}       \n         \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ\nٱللَّهَ لَقَوِيٌّ عَزِيزٌ\u{a0}٧٤\u{2}     \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}14\u{2}وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ\nعَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ\nٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ\nوَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ\nوَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ\u{a0}٧٨\n\u{2}        \n         \n        \n       \n       \u{a0}\n\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}2\u{1}\u{2}3\u{2}3\u{1}\u{2}3\u{2}4\u{1}\u{2}4\u{2}4\u{1}\u{2}4\u{2}5\u{2}إِلَّا عَلَىٰٓ\nأَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ\u{a0}٦\n\u{2} \n       \u{a0}\n\u{1}\u{2}\u{2}6\u{2}فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ\u{a0}٧\u{2}      \u{a0}\u{1}\u{2}6\u{2}7\u{2}وَٱلَّذِينَ هُمۡ\nلِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ\u{a0}٨\u{2} \n  \u{a0}\u{1}\u{2}7\u{2}\u{2}وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ\nيُحَافِظُونَ\u{a0}٩\u{2}   \n\u{a0}\u{1}\u{2}\u{2}8\u{2}أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ\u{a0}١٠\u{2}  \u{a0}\u{1}\u{2}8\u{2}\u{2}ٱلَّذِينَ يَرِثُونَ\nٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ\u{a0}١١\u{2} \n   \u{a0}\u{1}\u{2}9\u{2}\u{2}وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن\nسُلَٰلَةٖ مِّن طِينٖ\u{a0}١٢\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}10\u{2}ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ\u{a0}١٣\u{2}     \u{a0}\u{1}\u{2}10\u{2}\u{2}ثُمَّ\nخَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا\nٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا\nءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ\u{a0}١٤\u{2}\n      \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ\nلَمَيِّتُونَ\u{a0}١٥\u{2}   \n\u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ\u{a0}١٦\u{2}    \u{a0}\u{1}\u{2}14\u{2}\u{2}وَلَقَدۡ\nخَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ\u{a0}١٧\n\u{2}\n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ\nبِهِۦ لَقَٰدِرُونَ\u{a0}١٨\u{2}          \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ\nلَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ\u{a0}١٩\u{2}      \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَشَجَرَةٗ تَخۡرُجُ مِن\nطُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ\u{a0}٢٠\u{2}  \n     \u{a0}\u{1}\u{2}4\u{2}\u{2}وَإِنَّ لَكُمۡ فِي\nٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ\nوَمِنۡهَا تَأۡكُلُونَ\u{a0}٢١\u{2}  \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ\u{a0}٢٢\u{2}   \u{a0}\u{1}\u{2}6\u{2}\u{2}وَلَقَدۡ\nأَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ\nغَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ\u{a0}٢٣\u{2}\n           \n  \u{a0}\u{1}\u{2}\u{2}10\u{2}فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ\nإِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ\nمَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ\u{a0}٢٤\u{2}       \n          \n      \u{a0}\u{1}\u{2}10\u{2}\u{2}إِنۡ هُوَ إِلَّا\nرَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ\u{a0}٢٥\u{2}  \n      \u{a0}\u{1}\u{2}11\u{2}\u{2}قَالَ رَبِّ ٱنصُرۡنِي\nبِمَا كَذَّبُونِ\u{a0}٢٦\u{2}  \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا\nوَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن\nكُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ\nمِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ\u{a0}٢٧\n\u{2}     \n        \n        \n       \u{a0}\n\u{1}'
    '\u{2}\u{2}\u{2}فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا\nمِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ\u{a0}٢٨\u{2}           \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ\nٱلۡمُنزِلِينَ\u{a0}٢٩\u{2}      \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ\nٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nمَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا\nتَشۡرَبُونَ\u{a0}٣٣\u{2}   \n        \n          \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ\u{a0}٣٦\u{2}   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِنۡ هُوَ إِلَّا رَجُلٌ\nٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ\u{a0}٣٨\u{2}   \n       \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ\nكُلَّ مَا جَآءَ أُمَّةٗ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضٗا وَجَعَلۡنَٰهُمۡ\nأَحَادِيثَۚ فَبُعۡدٗا لِّقَوۡمٖ لَّا يُؤۡمِنُونَ\u{a0}٤٤\u{2}   \n         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ\nهَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ\u{a0}٤٥\u{2}   \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَيَحۡسَبُونَ أَنَّمَا\nنُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ\u{a0}٥٥\u{2} \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةٖ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلٞ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا\nعَٰمِلُونَ\u{a0}٦٣\u{2}            \n\u{a0}\u{1}\u{2}\u{2}5\u{2}حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ\u{a0}٦٤\n\u{2}       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قَدۡ كَانَتۡ ءَايَٰتِي\nتُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ\u{a0}٦٦\u{2}  \n     \u{a0}\u{1}\u{2}7\u{2}\u{2}مُسۡتَكۡبِرِينَ\nبِهِۦ سَٰمِرٗا تَهۡجُرُونَ\u{a0}٦٧\u{2}\n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ\nءَابَآءَهُمُ ٱلۡأَوَّلِينَ\u{a0}٦٨\u{2}       \n \u{a0}\u{1}\u{2}\u{2}9\u{2}أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ\u{a0}٦٩\n\u{2}      \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ\nكَٰرِهُونَ\u{a0}٧٠\u{2}        \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ\nوَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن\nذِكۡرِهِم مُّعۡرِضُونَ\u{a0}٧١\u{2}     \n       \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ\nيَعۡمَهُونَ\u{a0}٧٥\u{2}         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ\nإِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ\u{a0}٨٣\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن\nكُنتُمۡ تَعۡلَمُونَ\u{a0}٨٤\u{2}     \n \u{a0}\u{1}\u{2}\u{2}11\u{2}سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ\u{a0}٨٥\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}12\u{2}قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ\u{a0}٨٦\n\u{2}       \u{a0}\n\u{1}\u{1}'
    '\u{2}\u{2}\u{2}قُلۡ مَنۢ بِيَدِهِۦ\nمَلَكُوتُ كُلِّ شَيۡءٖ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن\nكُنتُمۡ تَعۡلَمُونَ\u{a0}٨٨\u{2}  \n        \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ\nوَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا\nبَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ\u{a0}٩١\u{2}    \n           \n      \u{a0}\u{1}\u{2}3\u{2}\u{2}عَٰلِمِ\nٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ\u{a0}٩٢\u{2}\n    \u{a0}\u{1}\u{1}\u{2}\u{2}6\u{2}رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ\nٱلظَّٰلِمِينَ\u{a0}٩٤\u{2}    \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ\u{a0}٩٥\n\u{2}      \u{a0}\n\u{1}\u{2}7\u{2}\u{2}ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ\u{a0}٩٦\n\u{2}        \u{a0}\n\u{1}\u{2}8\u{2}\u{2}وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ\u{a0}٩٧\u{2}      \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَعُوذُ بِكَ\nرَبِّ أَن يَحۡضُرُونِ\u{a0}٩٨\u{2} \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كـَلَّآۚ إِنَّهَا كَلِمَةٌ\nهُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ\u{a0}١٠٠\u{2}       \n       \u{a0}\u{1}\u{2}11\u{2}\u{2}فَإِذَا نُفِخَ\nفِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ\u{a0}١٠١\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ\u{a0}١٠٥\u{2}       \u{a0}\u{1}\u{2}1\u{2}\u{2}قَالُواْ\nرَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ\u{a0}١٠٦\u{2}\n      \u{a0}\u{1}\u{2}2\u{2}\u{2}رَبَّنَآ\nأَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ\u{a0}١٠٧\u{2}\n     \u{a0}\u{1}\u{2}3\u{2}\u{2}قَالَ ٱخۡسَـُٔواْ فِيهَا\nوَلَا تُكَلِّمُونِ\u{a0}١٠٨\u{2}  \n \u{a0}\u{1}\u{2}\u{2}5\u{2}إِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ\nءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ\u{a0}١٠٩\u{2}      \n      \u{a0}\u{1}\u{2}5\u{2}6\u{2}فَٱتَّخَذۡتُمُوهُمۡ\nسِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ\u{a0}١١٠\n\u{2}\n      \u{a0}\n\u{1}\u{2}\u{2}7\u{2}إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ\u{a0}١١١\u{2}       \u{a0}\u{1}\u{2}7\u{2}8\u{2}قَٰلَ\nكَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ\u{a0}١١٢\u{2}\n     \u{a0}\u{1}\u{2}8\u{2}\u{2}قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ\nيَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ\u{a0}١١٣\u{2}    \n  \u{a0}\u{1}\u{2}9\u{2}\u{2}قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗاۖ لَّوۡ أَنَّكُمۡ\nكُنتُمۡ تَعۡلَمُونَ\u{a0}١١٤\u{2}      \n \u{a0}\u{1}\u{2}10\u{2}\u{2}أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ\nإِلَيۡنَا لَا تُرۡجَعُونَ\u{a0}١١٥\u{2}    \n  \u{a0}\u{1}\u{2}11\u{2}\u{2}فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا\nهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ\u{a0}١١٦\u{2}      \n   \u{a0}\u{1}\u{2}12\u{2}\u{2}وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا\nءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ\nٱلۡكَٰفِرُونَ\u{a0}١١٧\u{2}    \n           \n\u{a0}\u{1}\u{2}14\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}3\u{2}5\u{2}ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم\nبِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ\nعَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ\u{a0}٢\u{2}         \n           \n   \u{a0}\u{1}\u{2}5\u{2}\u{2}ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ\nمُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى\nٱلۡمُؤۡمِنِينَ\u{a0}٣\u{2}     \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ\nفَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَٰٓئِكَ هُمُ\nٱلۡفَٰسِقُونَ\u{a0}٤\u{2}       \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ\nرَّحِيمٞ\u{a0}٥\u{2}         \n\u{a0}\u{1}\u{2}\u{2}11\u{2}وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ\nفَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ\u{a0}٦\n\u{2}        \n       \u{a0}\n\u{1}\u{2}\u{2}12\u{2}وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ\u{a0}٧\u{2}        \u{a0}\u{1}\u{2}12\u{2}13\u{2}وَيَدۡرَؤُاْ\nعَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ\u{a0}٨\n\u{2}\n         \u{a0}\n\u{1}\u{2}\u{2}14\u{2}وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ\u{a0}٩\n\u{2}        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ\nخَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ\nكِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ\u{a0}١١\u{2}           \n          \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}10\u{2}وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ\nقُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ\u{a0}١٦\n\u{2}  \n          \u{a0}\n\u{1}\u{2}\u{2}11\u{2}يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤۡمِنِينَ\u{a0}١٧\n\u{2}        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ\nيُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ\nفِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ\u{a0}١٩\u{2} \n         \n       \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ\nخُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ\nٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي\nمَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ\u{a0}٢١\u{2}        \n       \n           \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ\nوَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي\nسَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ\nوَٱللَّهُ غَفُورٞ رَّحِيمٌ\u{a0}٢٢\u{2}    \n       \n         \n  \u{a0}\u{1}\u{2}\u{2}8\u{2}إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ\nٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ\u{a0}٢٣\n\u{2}    \n       \u{a0}\n\u{1}\u{2}\u{2}9\u{2}يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ\u{a0}٢٤\n\u{2}        \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَوۡمَئِذٖ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ\nٱلۡمُبِينُ\u{a0}٢٥\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ\nوَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَٰٓئِكَ مُبَرَّءُونَ\nمِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ\u{a0}٢٦\u{2}   \n     \n     \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ\nوَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ\u{a0}٢٧\n\u{2} \n       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدٗا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن\nقِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ\nعَلِيمٞ\u{a0}٢٨\u{2}          \n         \n\u{a0}\u{1}\u{2}\u{2}4\u{2}لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا غَيۡرَ مَسۡكُونَةٖ\nفِيهَا مَتَٰعٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ\u{a0}٢٩\n\u{2}       \n        \u{a0}\n\u{1}'
    '\u{2}\u{2}\u{2}قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ\nذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ\u{a0}٣٠\u{2}      \n       \u{a0}\u{1}\u{2}6\u{2}\u{2}وَقُل لِّلۡمُؤۡمِنَٰتِ\nيَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ\nزِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ\nوَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ\nءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ\nأَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ\nأَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ\nٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ\nوَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ\nإِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ\u{a0}٣١\n\u{2} \n      \n        \n       \n      \n         \n         \n        \n        \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ\nوَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ\nعَلِمۡتُمۡ فِيهِمۡ خَيۡرٗاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا\nتُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ\nٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورٞ رَّحِيمٞ\u{a0}٣٣\n\u{2}         \n       \n         \n         \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ\nٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ\nلَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ\nنُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ\nلِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ\u{a0}٣٥\u{2}  \n        \n        \n          \n          \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ\nٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ\u{a0}٣٧\n\u{2}           \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ يَرۡزُقُ\nمَن يَشَآءُ بِغَيۡرِ حِسَابٖ\u{a0}٣٨\u{2}         \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَوۡ كَظُلُمَٰتٖ فِي بَحۡرٖ لُّجِّيّٖ يَغۡشَىٰهُ مَوۡجٞ مِّن فَوۡقِهِۦ مَوۡجٞ مِّن\nفَوۡقِهِۦ سَحَابٞۚ ظُلُمَٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَآ أَخۡرَجَ يَدَهُۥ لَمۡ\nيَكَدۡ يَرَىٰهَاۗ وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورٗا فَمَا لَهُۥ مِن نُّورٍ\u{a0}٤٠\u{2}          \n         \n           \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ أَنَّ\nٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَٰٓفَّٰتٖۖ كُلّٞ قَدۡ\nعَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ\u{a0}٤١\u{2}  \n          \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفِي قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوٓاْ أَمۡ يَخَافُونَ\nأَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ\u{a0}٥٠\n\u{2}      \n        \u{a0}\n\u{1}\u{2}11\u{2}\u{2}إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِينَ إِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ\nأَن يَقُولُواْ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ\u{a0}٥١\u{2}          \n      \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل\nلَّا تُقۡسِمُواْۖ طَاعَةٞ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}٥٣\n\u{2}       \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ\nٱلصَّٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ\nٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ\nوَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ يَعۡبُدُونَنِي لَا يُشۡرِكُونَ بِي\nشَيۡـٔٗاۚ وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ\u{a0}٥٥\n\u{2}     \n     \n        \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nلِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ\nثَلَٰثَ مَرَّٰتٖۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ\nوَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَآءِۚ ثَلَٰثُ عَوۡرَٰتٖ لَّكُمۡۚ لَيۡسَ عَلَيۡكُمۡ\nوَلَا عَلَيۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّٰفُونَ عَلَيۡكُم بَعۡضُكُمۡ عَلَىٰ\nبَعۡضٖۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ\u{a0}٥٨\n\u{2}  \n        \n          \n        \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا بَلَغَ ٱلۡأَطۡفَٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡيَسۡتَـٔۡذِنُواْ كَمَا ٱسۡتَـٔۡذَنَ\nٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦۗ وَٱللَّهُ\nعَلِيمٌ حَكِيمٞ\u{a0}٥٩\u{2}       \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِي لَا يَرۡجُونَ\nنِكَاحٗا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ ثِيَابَهُنَّ\nغَيۡرَ مُتَبَرِّجَٰتِۭ بِزِينَةٖۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرٞ لَّهُنَّۗ وَٱللَّهُ\nسَمِيعٌ عَلِيمٞ\u{a0}٦٠\u{2}     \n      \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ\nحَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞ وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ\nمِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ\nأَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ\nأَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ\nأَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ\nأَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ\nجَمِيعًا أَوۡ أَشۡتَاتٗاۚ فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ\nتَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ كَذَٰلِكَ\nيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ\u{a0}٦١\n\u{2}      \n         \n       \n       \n      \n      \n      \n        \n      \n     \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ\nبَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلَّذِينَ\nيَتَسَلَّلُونَ مِنكُمۡ لِوَاذٗاۚ فَلۡيَحۡذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنۡ أَمۡرِهِۦٓ\nأَن تُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَلِيمٌ\u{a0}٦٣\u{2}   \n       \n       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَآ إِنَّ لِلَّهِ\nمَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قَدۡ يَعۡلَمُ مَآ أَنتُمۡ عَلَيۡهِ وَيَوۡمَ\nيُرۡجَعُونَ إِلَيۡهِ فَيُنَبِّئُهُم بِمَا عَمِلُواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ\u{a0}٦٤\n\u{2}  \n         \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ\nيَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا\u{a0}٢\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}4\u{2}وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ إِفۡكٌ\nٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَيۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَآءُو ظُلۡمٗا وَزُورٗا\u{a0}٤\n\u{2}      \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ\nفِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا\u{a0}٦\u{2}    \n      \u{a0}\u{1}\u{2}7\u{2}\u{2}وَقَالُواْ\nمَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ\nلَوۡلَآ أُنزِلَ إِلَيۡهِ مَلَكٞ فَيَكُونَ مَعَهُۥ نَذِيرًا\u{a0}٧\u{2}\n       \n      \u{a0}\u{1}\u{2}9\u{2}\u{2}أَوۡ يُلۡقَىٰٓ\nإِلَيۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةٞ يَأۡكُلُ مِنۡهَاۚ وَقَالَ\nٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا\u{a0}٨\u{2} \n        \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِيدٖ سَمِعُواْ لَهَا تَغَيُّظٗا وَزَفِيرٗا\u{a0}١٢\u{2}        \u{a0}\u{1}\u{2}1\u{2}\u{2}وَإِذَآ\nأُلۡقُواْ مِنۡهَا مَكَانٗا ضَيِّقٗا مُّقَرَّنِينَ دَعَوۡاْ هُنَالِكَ ثُبُورٗا\u{a0}١٣\n\u{2}\n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}لَّا تَدۡعُواْ ٱلۡيَوۡمَ ثُبُورٗا وَٰحِدٗا وَٱدۡعُواْ ثُبُورٗا كَثِيرٗا\u{a0}١٤\u{2}       \u{a0}\u{1}\u{2}3\u{2}\u{2}قُلۡ\nأَذَٰلِكَ خَيۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ\nلَهُمۡ جَزَآءٗ وَمَصِيرٗا\u{a0}١٥\u{2}\n        \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُواْ سُبۡحَٰنَكَ مَا كَانَ\nيَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ\nوَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا\u{a0}١٨\u{2}   \n         \n      \u{a0}\u{1}\u{2}10\u{2}\u{2}فَقَدۡ\nكَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِيعُونَ صَرۡفٗا وَلَا\nنَصۡرٗاۚ وَمَن يَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابٗا كَبِيرٗا\u{a0}١٩\n\u{2}\n      \n      \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا لَوۡلَآ أُنزِلَ عَلَيۡنَا ٱلۡمَلَٰٓئِكَةُ\nأَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُواْ فِيٓ أَنفُسِهِمۡ وَعَتَوۡ عُتُوّٗا كَبِيرٗا\u{a0}٢١\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{2}\u{2}\u{2}يَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ أَتَّخِذۡ\nفُلَانًا خَلِيلٗا\u{a0}٢٨\u{2}   \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلرَّسُولُ\nيَٰرَبِّ إِنَّ قَوۡمِي ٱتَّخَذُواْ هَٰذَا ٱلۡقُرۡءَانَ مَهۡجُورٗا\u{a0}٣٠\u{2} \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَٰٓئِكَ شَرّٞ\nمَّكَانٗا وَأَضَلُّ سَبِيلٗا\u{a0}٣٤\u{2}       \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَقُلۡنَا ٱذۡهَبَآ إِلَى\nٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا فَدَمَّرۡنَٰهُمۡ تَدۡمِيرٗا\u{a0}٣٦\u{2}  \n     \u{a0}\u{1}\u{2}5\u{2}\u{2}وَقَوۡمَ\nنُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ\nءَايَةٗۖ وَأَعۡتَدۡنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمٗا\u{a0}٣٧\u{2}\n      \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَكُلّٗا ضَرَبۡنَا\nلَهُ ٱلۡأَمۡثَٰلَۖ وَكُلّٗا تَبَّرۡنَا تَتۡبِيرٗا\u{a0}٣٩\u{2} \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ\nٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ بَلۡ\nكَانُواْ لَا يَرۡجُونَ نُشُورٗا\u{a0}٤٠\u{2}   \n       \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ\nٱلظِّلَّ وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنٗا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلٗا\u{a0}٤٥\n\u{2}     \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي جَعَلَ\nلَكُمُ ٱلَّيۡلَ لِبَاسٗا وَٱلنَّوۡمَ سُبَاتٗا وَجَعَلَ ٱلنَّهَارَ نُشُورٗا\u{a0}٤٧\n\u{2}  \n       \u{a0}\n\u{1}\u{2}6\u{2}\u{2}وَهُوَ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا\nمِنَ ٱلسَّمَآءِ مَآءٗ طَهُورٗا\u{a0}٤٨\u{2}        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَا تُطِعِ ٱلۡكَٰفِرِينَ\nوَجَٰهِدۡهُم بِهِۦ جِهَادٗا كَبِيرٗا\u{a0}٥٢\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَهُوَ ٱلَّذِي مَرَجَ\nٱلۡبَحۡرَيۡنِ هَٰذَا عَذۡبٞ فُرَاتٞ وَهَٰذَا مِلۡحٌ أُجَاجٞ وَجَعَلَ بَيۡنَهُمَا بَرۡزَخٗا\nوَحِجۡرٗا مَّحۡجُورٗا\u{a0}٥٣\u{2}  \n         \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَتَوَكَّلۡ\nعَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ\nعِبَادِهِۦ خَبِيرًا\u{a0}٥٨\u{2}\n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا\nفِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَٰنُ فَسۡـَٔلۡ بِهِۦ\nخَبِيرٗا\u{a0}٥٩\u{2}     \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ\nأَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورٗا۩\u{a0}٦٠\u{2}       \n    \u{a0}\u{1}\u{2}\u{2}8\u{2}تَبَارَكَ ٱلَّذِي جَعَلَ\nفِي ٱلسَّمَآءِ بُرُوجٗا وَجَعَلَ فِيهَا سِرَٰجٗا وَقَمَرٗا مُّنِيرٗا\u{a0}٦١\u{2}  \n       \u{a0}\u{1}\u{2}8\u{2}\u{2}وَهُوَ\nٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ\nشُكُورٗا\u{a0}٦٢\u{2}\n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ\nهَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا\u{a0}٦٣\u{2}     \n     \u{a0}\u{1}\u{2}11\u{2}\u{2}وَٱلَّذِينَ\nيَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا\u{a0}٦٤\u{2}\n   \u{a0}\u{1}\u{2}\u{2}13\u{2}وَٱلَّذِينَ يَقُولُونَ\nرَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا\u{a0}٦٥\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ إِذَآ أَنفَقُواْ\nلَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا\u{a0}٦٧\n\u{2}  \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ\nٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ\nأَثَامٗا\u{a0}٦٨\u{2}         \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ يَوۡمَ ٱلۡقِيَٰمَةِ وَيَخۡلُدۡ فِيهِۦ\nمُهَانًا\u{a0}٦٩\u{2}      \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا\nفَأُوْلَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا\nرَّحِيمٗا\u{a0}٧٠\u{2}      \n       \n\u{a0}\u{1}\u{2}6\u{2}\u{2}وَمَن تَابَ وَعَمِلَ صَٰلِحٗا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ\nمَتَابٗا\u{a0}٧١\u{2}       \n\u{a0}\u{1}\u{2}7\u{2}\u{2}وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ\nمَرُّواْ كِرَامٗا\u{a0}٧٢\u{2}      \n \u{a0}\u{1}\u{2}8\u{2}9\u{2}وَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ\nلَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا\u{a0}٧٣\u{2}    \n    \u{a0}\u{1}\u{2}9\u{2}11\u{2}وَٱلَّذِينَ يَقُولُونَ رَبَّنَا\nهَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا\nلِلۡمُتَّقِينَ إِمَامًا\u{a0}٧٤\u{2}  \n       \n \u{a0}\u{1}\u{2}11\u{2}12\u{2}أُوْلَٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا\nصَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا\u{a0}٧٥\u{2}   \n    \u{a0}\u{1}\u{2}12\u{2}13\u{2}خَٰلِدِينَ\nفِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا\u{a0}٧٦\u{2}\n   \u{a0}\u{1}\u{2}13\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}3\u{2}لَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ\nأَلَّا يَكُونُواْ مُؤۡمِنِينَ\u{a0}٣\u{2}  \n  \u{a0}\u{1}\u{2}3\u{2}4\u{1}\u{2}4\u{2}5\u{1}\u{2}5\u{2}6\u{2}فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ\nبِهِۦ يَسۡتَهۡزِءُونَ\u{a0}٦\u{2}     \n \u{a0}\u{1}\u{2}6\u{2}\u{2}أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ\nكَرِيمٍ\u{a0}٧\u{2}         \n\u{a0}\u{1}\u{2}7\u{2}7\u{1}'
    '\u{2}7\u{2}8\u{2}وَإِنَّ\nرَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ\u{a0}٩\u{2}\n   \u{a0}\u{1}\u{2}8\u{2}\u{2}وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ\nٱلظَّٰلِمِينَ\u{a0}١٠\u{2}      \n\u{a0}\u{1}\u{2}\u{2}9\u{2}قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ\u{a0}١١\u{2}   \u{a0}\u{1}\u{2}9\u{2}\u{2}قَالَ رَبِّ إِنِّيٓ أَخَافُ\nأَن يُكَذِّبُونِ\u{a0}١٢\u{2}   \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ\nإِلَىٰ هَٰرُونَ\u{a0}١٣\u{2}     \n \u{a0}\u{1}\u{2}\u{2}11\u{2}وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ\u{a0}١٤\u{2}     \u{a0}\u{1}\u{2}11\u{2}\u{2}قَالَ\nكـَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ\u{a0}١٥\u{2}\n     \u{a0}\u{1}\u{2}12\u{2}\u{2}فَأۡتِيَا فِرۡعَوۡنَ\nفَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ\u{a0}١٦\u{2} \n    \u{a0}\u{1}\u{2}\u{2}13\u{2}أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ\u{a0}١٧\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}14\u{2}قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ\u{a0}١٨\n\u{2}         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ\u{a0}٢٨\u{2}        \u{a0}\u{1}\u{2}7\u{2}\u{2}قَالَ\nلَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ\u{a0}٢٩\u{2}\n      \u{a0}\u{1}\u{2}8\u{2}\u{2}قَالَ\nأَوَلَوۡ جِئۡتُكَ بِشَيۡءٖ مُّبِينٖ\u{a0}٣٠\u{2}\n   \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ مِنَ\nٱلصَّٰدِقِينَ\u{a0}٣١\u{2}     \n\u{a0}\u{1}\u{2}\u{2}\u{2}فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ\u{a0}٣٢\u{2}     \u{a0}\u{1}\u{2}10\u{2}\u{2}وَنَزَعَ يَدَهُۥ\nفَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ\u{a0}٣٣\u{2} \n   \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ\nعَلِيمٞ\u{a0}٣٤\u{2}     \n\u{a0}\u{1}\u{2}\u{2}\u{2}يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا\nتَأۡمُرُونَ\u{a0}٣٥\u{2}      \n\u{a0}\u{1}\u{2}\u{2}13\u{2}قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ\u{a0}٣٦\n\u{2}      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم\nمُّتَّبَعُونَ\u{a0}٥٢\u{2}      \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا تَرَٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ\u{a0}٦١\u{2}       \u{a0}\u{1}\u{2}1\u{2}\u{2}قَالَ\nكـَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ\u{a0}٦٢\u{2}\n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب\nبِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ\u{a0}٦٣\n\u{2}    \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم\nمُّؤۡمِنِينَ\u{a0}٦٧\u{2}      \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ\u{a0}٦٨\u{2}    \u{a0}\u{1}'
    '\u{2}6\u{2}\u{2}وَٱتۡلُ عَلَيۡهِمۡ\nنَبَأَ إِبۡرَٰهِيمَ\u{a0}٦٩\u{2} \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ\u{a0}٧٠\u{2}     \u{a0}\u{1}\u{2}7\u{2}\u{2}قَالُواْ\nنَعۡبُدُ أَصۡنَامٗا فَنَظَلُّ لَهَا عَٰكِفِينَ\u{a0}٧١\u{2}\n    \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ\nتَدۡعُونَ\u{a0}٧٢\u{2}   \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا\nكَذَٰلِكَ يَفۡعَلُونَ\u{a0}٧٤\u{2}   \n \u{a0}\u{1}\u{2}\u{2}10\u{2}قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ\u{a0}٧٥\u{2}    \u{a0}\u{1}\u{2}10\u{2}\u{2}أَنتُمۡ\nوَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ\u{a0}٧٦\u{2}\n \u{a0}\u{1}\u{2}\u{2}11\u{2}فَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ\u{a0}٧٧\n\u{2}     \u{a0}\n\u{1}\u{1}\u{2}\u{2}12\u{2}وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ\u{a0}٧٩\n\u{2}   \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِي يُمِيتُنِي ثُمَّ\nيُحۡيِينِ\u{a0}٨١\u{2}  \n\u{a0}\u{1}\u{2}\u{2}14\u{2}وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ\u{a0}٨٢\n\u{2}       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}4\u{2}وَبُرِّزَتِ ٱلۡجَحِيمُ لِلۡغَاوِينَ\u{a0}٩١\n\u{2}  \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}مِن دُونِ ٱللَّهِ هَلۡ يَنصُرُونَكُمۡ\nأَوۡ يَنتَصِرُونَ\u{a0}٩٣\u{2}    \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَجُنُودُ إِبۡلِيسَ\nأَجۡمَعُونَ\u{a0}٩٥\u{2} \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَآ أَضَلَّنَآ\nإِلَّا ٱلۡمُجۡرِمُونَ\u{a0}٩٩\u{2} \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا صَدِيقٍ حَمِيمٖ\u{a0}١٠١\n\u{2}  \u{a0}\n\u{1}\u{2}10\u{2}\u{2}فَلَوۡ أَنَّ لَنَا كَرَّةٗ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ\u{a0}١٠٢\u{2}      \u{a0}\u{1}\u{1}\u{1}\u