    '\u{1}\u{1}\u{2}\u{2}\u{2}وَإِنَّ رَبَّكَ لَهُوَ\nٱلۡعَزِيزُ ٱلرَّحِيمُ\u{a0}١٩١\u{2}  \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}نَزَلَ بِهِ ٱلرُّوحُ\nٱلۡأَمِينُ\u{a0}١٩٣\u{2}  \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}بِلِسَانٍ عَرَبِيّٖ\nمُّبِينٖ\u{a0}١٩٥\u{2} \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَكُن لَّهُمۡ ءَايَةً أَن يَعۡلَمَهُۥ\nعُلَمَٰٓؤُاْ بَنِيٓ إِسۡرَٰٓءِيلَ\u{a0}١٩٧\u{2}     \n  \u{a0}\u{1}\u{2}\u{2}10\u{2}وَلَوۡ نَزَّلۡنَٰهُ عَلَىٰ بَعۡضِ ٱلۡأَعۡجَمِينَ\u{a0}١٩٨\n\u{2}    \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا\nلَهَا مُنذِرُونَ\u{a0}٢٠٨\u{2}    \n \u{a0}\u{1}\u{2}\u{2}2\u{2}ذِكۡرَىٰ وَمَا كُنَّا ظَٰلِمِينَ\u{a0}٢٠٩\u{2}   \u{a0}\u{1}\u{2}2\u{2}\u{2}وَمَا تَنَزَّلَتۡ بِهِ\nٱلشَّيَٰطِينُ\u{a0}٢١٠\u{2}  \n\u{a0}\u{1}\u{2}\u{2}3\u{2}وَمَا يَنۢبَغِي لَهُمۡ وَمَا يَسۡتَطِيعُونَ\u{a0}٢١١\u{2}    \u{a0}\u{1}\u{2}3\u{2}\u{2}إِنَّهُمۡ\nعَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ\u{a0}٢١٢\u{2}\n  \u{a0}\u{1}\u{2}4\u{2}\u{2}فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ\nمِنَ ٱلۡمُعَذَّبِينَ\u{a0}٢١٣\u{2}      \n \u{a0}\u{1}\u{2}5\u{2}5\u{1}\u{2}5\u{2}6\u{2}وَٱخۡفِضۡ\nجَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ\u{a0}٢١٥\u{2}\n    \u{a0}\u{1}\u{2}6\u{2}\u{2}فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي\nبَرِيٓءٞ مِّمَّا تَعۡمَلُونَ\u{a0}٢١٦\u{2}   \n  \u{a0}\u{1}\u{2}7\u{2}7\u{1}\u{2}7\u{2}\u{2}ٱلَّذِي\nيَرَىٰكَ حِينَ تَقُومُ\u{a0}٢١٨\u{2}\n  \u{a0}\u{1}\u{2}8\u{2}8\u{1}\u{2}8\u{2}\u{2}إِنَّهُۥ هُوَ ٱلسَّمِيعُ\nٱلۡعَلِيمُ\u{a0}٢٢٠\u{2}  \n\u{a0}\u{1}\u{2}9\u{2}9\u{1}\u{2}9\u{2}10\u{2}تَنَزَّلُ عَلَىٰ\nكُلِّ أَفَّاكٍ أَثِيمٖ\u{a0}٢٢٢\u{2} \n  \u{a0}\u{1}\u{2}10\u{2}10\u{1}\u{2}11\u{2}11\u{1}\u{2}11\u{2}12\u{1}\u{2}12\u{2}12\u{1}\u{2}12\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}3\u{1}\u{2}3\u{2}4\u{2}ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم\nبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ\u{a0}٣\u{2}     \n  \u{a0}\u{1}\u{2}4\u{2}5\u{2}إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ\nأَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ\u{a0}٤\u{2}      \n  \u{a0}\u{1}\u{2}5\u{2}6\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ لَهُمۡ سُوٓءُ ٱلۡعَذَابِ\nوَهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ\u{a0}٥\u{2}    \n    \u{a0}\u{1}\u{2}6\u{2}\u{2}وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن\nلَّدُنۡ حَكِيمٍ عَلِيمٍ\u{a0}٦\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}8\u{2}إِذۡ قَالَ مُوسَىٰ لِأَهۡلِهِۦٓ إِنِّيٓ ءَانَسۡتُ نَارٗا سَـَٔاتِيكُم\nمِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِيكُم بِشِهَابٖ قَبَسٖ لَّعَلَّكُمۡ تَصۡطَلُونَ\u{a0}٧\u{2}       \n       \u{a0}\u{1}\u{2}8\u{2}\u{2}فَلَمَّا\nجَآءَهَا نُودِيَ أَنۢ بُورِكَ مَن فِي ٱلنَّارِ وَمَنۡ حَوۡلَهَا وَسُبۡحَٰنَ ٱللَّهِ رَبِّ\nٱلۡعَٰلَمِينَ\u{a0}٨\u{2}\n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٩\u{2}     \u{a0}\u{1}\u{2}10\u{2}\u{2}وَأَلۡقِ عَصَاكَۚ\nفَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰ لَا تَخَفۡ\nإِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ\u{a0}١٠\u{2} \n           \n    \u{a0}\u{1}\u{2}\u{2}\u{2}إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ\nسُوٓءٖ فَإِنِّي غَفُورٞ رَّحِيمٞ\u{a0}١١\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}14\u{2}وَأَدۡخِلۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ\nمِنۡ غَيۡرِ سُوٓءٖۖ فِي تِسۡعِ ءَايَٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ\u{a0}١٢\n\u{2}     \n            \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ\nوَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ\u{a0}١٦\u{2}        \n        \u{a0}\u{1}\u{2}5\u{2}6\u{2}وَحُشِرَ\nلِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ يُوزَعُونَ\u{a0}١٧\n\u{2}\n       \u{a0}\n\u{1}\u{2}\u{2}8\u{2}حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةٞ يَٰٓأَيُّهَا ٱلنَّمۡلُ ٱدۡخُلُواْ\nمَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ لَا يَشۡعُرُونَ\u{a0}١٨\n\u{2}          \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ\nنِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا\nتَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ\u{a0}١٩\n\u{2}        \n        \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَا لِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ\nٱلۡغَآئِبِينَ\u{a0}٢٠\u{2}          \n\u{a0}\u{1}\u{1}'
    '\u{1}\u{1}\u{2}\u{2}\u{2}وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن\nدُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ\nفَهُمۡ لَا يَهۡتَدُونَ\u{a0}٢٤\u{2}    \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ\nفِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ\u{a0}٢٥\u{2}     \n       \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ قَالَ سَنَنظُرُ\nأَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ\u{a0}٢٧\u{2} \n    \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ\nٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ\u{a0}٣٠\u{2}    \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةٖ وَأُوْلُواْ بَأۡسٖ شَدِيدٖ وَٱلۡأَمۡرُ إِلَيۡكِ\nفَٱنظُرِي مَاذَا تَأۡمُرِينَ\u{a0}٣٣\u{2}        \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَنَّهُم\nبِجُنُودٖ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَآ أَذِلَّةٗ وَهُمۡ صَٰغِرُونَ\u{a0}٣٧\u{2}  \n         \u{a0}\u{1}\u{2}3\u{2}\u{2}قَالَ\nيَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا قَبۡلَ أَن يَأۡتُونِي مُسۡلِمِينَ\u{a0}٣٨\n\u{2}\n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي\nعَلَيۡهِ لَقَوِيٌّ أَمِينٞ\u{a0}٣٩\u{2}            \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ\nبِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا\nمِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ\nلِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ\u{a0}٤٠\u{2}       \n           \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ نَكِّرُواْ لَهَا عَرۡشَهَا\nنَنظُرۡ أَتَهۡتَدِيٓ أَمۡ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهۡتَدُونَ\u{a0}٤١\u{2}   \n       \u{a0}\u{1}\u{2}\u{2}11\u{2}فَلَمَّا جَآءَتۡ قِيلَ\nأَهَٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِينَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِينَ\u{a0}٤٢\n\u{2}  \n          \u{a0}\n\u{1}\u{2}\u{2}12\u{2}وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمٖ كَٰفِرِينَ\u{a0}٤٣\n\u{2}           \u{a0}\n\u{1}\u{2}\u{2}\u{2}قِيلَ لَهَا ٱدۡخُلِي ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةٗ وَكَشَفَتۡ عَن\nسَاقَيۡهَاۚ قَالَ إِنَّهُۥ صَرۡحٞ مُّمَرَّدٞ مِّن قَوَارِيرَۗ قَالَتۡ رَبِّ إِنِّي\nظَلَمۡتُ نَفۡسِي وَأَسۡلَمۡتُ مَعَ سُلَيۡمَٰنَ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ\u{a0}٤٤\n\u{2}         \n         \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحًا أَنِ ٱعۡبُدُواْ ٱللَّهَ فَإِذَا\nهُمۡ فَرِيقَانِ يَخۡتَصِمُونَ\u{a0}٤٥\u{2}         \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَكَانَ فِي ٱلۡمَدِينَةِ تِسۡعَةُ\nرَهۡطٖ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ\u{a0}٤٨\u{2}   \n     \u{a0}\u{1}\u{2}6\u{2}\u{2}قَالُواْ\nتَقَاسَمُواْ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهۡلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدۡنَا\nمَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَٰدِقُونَ\u{a0}٤٩\u{2}\n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَكَرُواْ مَكۡرٗا\nوَمَكَرۡنَا مَكۡرٗا وَهُمۡ لَا يَشۡعُرُونَ\u{a0}٥٠\u{2} \n    \u{a0}\u{1}\u{2}\u{2}10\u{2}فَٱنظُرۡ كَيۡفَ\nكَانَ عَٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَٰهُمۡ وَقَوۡمَهُمۡ أَجۡمَعِينَ\u{a0}٥١\n\u{2} \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ\nلَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ\u{a0}٥٢\u{2}       \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ\nأَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ\u{a0}٥٤\u{2}   \n   \u{a0}\u{1}\u{2}\u{2}\u{2}أَئِنَّكُمۡ لَتَأۡتُونَ\nٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ تَجۡهَلُونَ\u{a0}٥٥\n\u{2} \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ\nلُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ\u{a0}٥٦\u{2}        \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَٰمٌ\nعَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ\u{a0}٥٩\n\u{2}   \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَمَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ\nمَآءٗ فَأَنۢبَتۡنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهۡجَةٖ مَّا كَانَ لَكُمۡ\nأَن تُنۢبِتُواْ شَجَرَهَآۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ هُمۡ قَوۡمٞ يَعۡدِلُونَ\u{a0}٦٠\n\u{2}       \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارٗا وَجَعَلَ خِلَٰلَهَآ أَنۡهَٰرٗا وَجَعَلَ لَهَا\nرَوَٰسِيَ وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ\nأَكۡثَرُهُمۡ لَا يَعۡلَمُونَ\u{a0}٦١\u{2}        \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ\nوَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ\nمَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ\u{a0}٦٢\u{2}    \n     \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَمَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۗ\nأَءِلَٰهٞ مَّعَ ٱللَّهِۚ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}٦٤\n\u{2}         \n        \u{a0}\n\u{1}\u{2}3\u{2}\u{2}قُل لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ\nأَيَّانَ يُبۡعَثُونَ\u{a0}٦٥\u{2}           \n \u{a0}\u{1}\u{2}\u{2}\u{2}بَلِ ٱدَّٰرَكَ عِلۡمُهُمۡ فِي ٱلۡأٓخِرَةِۚ بَلۡ هُمۡ\nفِي شَكّٖ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ\u{a0}٦٦\u{2}      \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ\nأَءِذَا كُنَّا تُرَٰبٗا وَءَابَآؤُنَآ أَئِنَّا لَمُخۡرَجُونَ\u{a0}٦٧\u{2}  \n     \u{a0}\u{1}\u{2}\u{2}\u{2}لَقَدۡ وُعِدۡنَا\nهَٰذَا نَحۡنُ وَءَابَآؤُنَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ\u{a0}٦٨\n\u{2} \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{2}\u{2}\u{2}۞ وَإِذَا\nوَقَعَ ٱلۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَآبَّةٗ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ\nٱلنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ\u{a0}٨٢\u{2}\n         \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}حَتَّىٰٓ إِذَا جَآءُو\nقَالَ أَكَذَّبۡتُم بِـَٔايَٰتِي وَلَمۡ تُحِيطُواْ بِهَا عِلۡمًا أَمَّاذَا كُنتُمۡ تَعۡمَلُونَ\u{a0}٨٤\n\u{2}  \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَفَزِعَ\nمَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ\nدَٰخِرِينَ\u{a0}٨٧\u{2}    \n           \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِي ٱلنَّارِ هَلۡ تُجۡزَوۡنَ\nإِلَّا مَا كُنتُمۡ تَعۡمَلُونَ\u{a0}٩٠\u{2}        \n   \u{a0}\u{1}\u{2}\u{2}5\u{2}إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَٰذِهِ\nٱلۡبَلۡدَةِ ٱلَّذِي حَرَّمَهَا وَلَهُۥ كُلُّ شَيۡءٖۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ\nٱلۡمُسۡلِمِينَ\u{a0}٩١\u{2}     \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي\nلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَقُلۡ إِنَّمَآ أَنَا۠ مِنَ ٱلۡمُنذِرِينَ\u{a0}٩٢\u{2}      \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَقُلِ ٱلۡحَمۡدُ\nلِلَّهِ سَيُرِيكُمۡ ءَايَٰتِهِۦ فَتَعۡرِفُونَهَاۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ\u{a0}٩٣\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ\nأَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ\u{a0}٩\u{2}         \n       \u{a0}\u{1}\u{2}8\u{2}\u{2}وَأَصۡبَحَ\nفُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن\nرَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ\u{a0}١٠\u{2}\n         \n     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ\nعَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ\u{a0}١٢\n\u{2}       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}5\u{2}وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا\nفَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ\nفَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ\nفَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ\u{a0}١٥\n\u{2}      \n         \n         \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ\nٱلۡغَفُورُ ٱلرَّحِيمُ\u{a0}١٦\u{2}          \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}12\u{2}فَلَمَّآ أَنۡ أَرَادَ أَن يَبۡطِشَ بِٱلَّذِي هُوَ عَدُوّٞ لَّهُمَا قَالَ\nيَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقۡتُلَنِي كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِيدُ إِلَّآ\nأَن تَكُونَ جَبَّارٗا فِي ٱلۡأَرۡضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِينَ\u{a0}١٩\n\u{2}         \n          \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَجَآءَ رَجُلٞ مِّنۡ أَقۡصَا ٱلۡمَدِينَةِ يَسۡعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلۡمَلَأَ\nيَأۡتَمِرُونَ بِكَ لِيَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّي لَكَ مِنَ ٱلنَّٰصِحِينَ\u{a0}٢٠\n\u{2}         \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ\nٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ\nقَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا\nشَيۡخٞ كَبِيرٞ\u{a0}٢٣\u{2}       \n      \n         \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ\nٱلطُّورِ نَارٗاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم\nمِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةٖ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ\u{a0}٢٩\n\u{2}        \n         \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا\nجَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ\nمِنَ ٱلۡأٓمِنِينَ\u{a0}٣١\u{2}      \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}ٱسۡلُكۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ\nغَيۡرِ سُوٓءٖ وَٱضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَٰنِكَ\nبُرۡهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦٓۚ إِنَّهُمۡ كَانُواْ\nقَوۡمٗا فَٰسِقِينَ\u{a0}٣٢\u{2}      \n       \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسٗا فَأَخَافُ\nأَن يَقۡتُلُونِ\u{a0}٣٣\u{2}      \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرٞ\nمُّفۡتَرٗى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ\u{a0}٣٦\u{2}         \n      \u{a0}\u{1}\u{2}2\u{2}\u{2}وَقَالَ\nمُوسَىٰ رَبِّيٓ أَعۡلَمُ بِمَن جَآءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ\nلَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ\u{a0}٣٧\u{2}\n         \n      \u{a0}\u{1}\u{2}4\u{2}\u{2}وَقَالَ فِرۡعَوۡنُ\nيَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ\nلِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ\nإِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ\u{a0}٣٨\u{2} \n        \n         \n     \u{a0}\u{1}\u{2}7\u{2}\u{2}وَٱسۡتَكۡبَرَ\nهُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ أَنَّهُمۡ إِلَيۡنَا\nلَا يُرۡجَعُونَ\u{a0}٣٩\u{2}\n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي\nٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ\u{a0}٤٠\n\u{2}   \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ\u{a0}٥١\u{2}     \u{a0}\u{1}\u{1}\u{2}\u{2}3\u{2}وَإِذَا يُتۡلَىٰ عَلَيۡهِمۡ\nقَالُوٓاْ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِينَ\u{a0}٥٣\n\u{2}  \n           \u{a0}\n\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ\nٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ\u{a0}٥٤\u{2}       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذَا سَمِعُواْ ٱللَّغۡوَ\nأَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ عَلَيۡكُمۡ\nلَا نَبۡتَغِي ٱلۡجَٰهِلِينَ\u{a0}٥٥\u{2}  \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ\nٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ\u{a0}٥٦\u{2}     \n      \u{a0}\u{1}\u{2}8\u{2}\u{2}وَقَالُوٓاْ إِن\nنَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَلَمۡ نُمَكِّن لَّهُمۡ\nحَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا وَلَٰكِنَّ\nأَكۡثَرَهُمۡ لَا يَعۡلَمُونَ\u{a0}٥٧\u{2} \n        \n          \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَكَمۡ أَهۡلَكۡنَا مِن قَرۡيَةِۭ\nبَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ\nإِلَّا قَلِيلٗاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ\u{a0}٥٨\u{2}   \n       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ رَبُّكَ مُهۡلِكَ\nٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولٗا يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَاۚ وَمَا\nكُنَّا مُهۡلِكِي ٱلۡقُرَىٰٓ إِلَّا وَأَهۡلُهَا ظَٰلِمُونَ\u{a0}٥٩\n\u{2}   \n         \n     \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ\nكُنتُمۡ تَزۡعُمُونَ\u{a0}٦٢\u{2}     \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَٰٓؤُلَآءِ\nٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ مَا كَانُوٓاْ إِيَّانَا\nيَعۡبُدُونَ\u{a0}٦٣\u{2}      \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَقِيلَ ٱدۡعُواْ شُرَكَآءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ\nلَهُمۡ وَرَأَوُاْ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُواْ يَهۡتَدُونَ\u{a0}٦٤\u{2}     \n      \u{a0}\u{1}\u{2}8\u{2}\u{2}وَيَوۡمَ يُنَادِيهِمۡ\nفَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ\u{a0}٦٥\u{2} \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ\nيَوۡمَئِذٖ فَهُمۡ لَا يَتَسَآءَلُونَ\u{a0}٦٦\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ\nصَٰلِحٗا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ\u{a0}٦٧\u{2}    \n     \u{a0}\u{1}\u{2}11\u{2}\u{2}وَرَبُّكَ\nيَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ سُبۡحَٰنَ\nٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ\u{a0}٦٨\u{2}\n        \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ\nمَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ\u{a0}٧١\n\u{2}          \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}6\u{2}وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ\nوَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}٧٣\n\u{2}    \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ\nتَزۡعُمُونَ\u{a0}٧٤\u{2}      \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَنَزَعۡنَا مِن كُلِّ أُمَّةٖ شَهِيدٗا فَقُلۡنَا\nهَاتُواْ بُرۡهَٰنَكُمۡ فَعَلِمُوٓاْ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُواْ\nيَفۡتَرُونَ\u{a0}٧٥\u{2}     \n         \n\u{a0}\u{1}\u{2}\u{2}12\u{2}۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ\nعَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ\nأُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ\u{a0}٧٦\n\u{2}      \n        \n            \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ\nنَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ\nوَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ\u{a0}٧٧\n\u{2}       \n       \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ\nٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ\nوَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ\u{a0}٨٠\u{2}\n        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَخَسَفۡنَا\nبِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةٖ يَنصُرُونَهُۥ مِن دُونِ\nٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِينَ\u{a0}٨١\u{2}\n          \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا\nلِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ\u{a0}٨٣\n\u{2}   \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا كُنتَ\nتَرۡجُوٓاْ أَن يُلۡقَىٰٓ إِلَيۡكَ ٱلۡكِتَٰبُ إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۖ\nفَلَا تَكُونَنَّ ظَهِيرٗا لِّلۡكَٰفِرِينَ\u{a0}٨٦\u{2} \n        \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۘ لَآ إِلَٰهَ إِلَّا\nهُوَۚ كُلُّ شَيۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ\u{a0}٨٨\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا\nيُفۡتَنُونَ\u{a0}٢\u{2}        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا\nمَّعَ أَثۡقَالِهِمۡۖ وَلَيُسۡـَٔلُنَّ يَوۡمَ ٱلۡقِيَٰمَةِ عَمَّا كَانُواْ يَفۡتَرُونَ\u{a0}١٣\n\u{2}  \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}وَمَآ أَنتُم بِمُعۡجِزِينَ فِي\nٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ\nوَلَا نَصِيرٖ\u{a0}٢٢\u{2}   \n          \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ\nإِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٢٦\u{2}   \n       \u{a0}\u{1}\u{2}7\u{2}9\u{2}وَوَهَبۡنَا\nلَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ\nوَءَاتَيۡنَٰهُ أَجۡرَهُۥ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ\u{a0}٢٧\n\u{2}\n       \n        \u{a0}\n\u{1}\u{2}\u{2}11\u{2}وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ\nمَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ\u{a0}٢٨\n\u{2}      \n      \u{a0}\n\u{1}\u{2}\u{2}14\u{2}أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِيلَ وَتَأۡتُونَ\nفِي نَادِيكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ\nأَن قَالُواْ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ\u{a0}٢٩\n\u{2}     \n       \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَمَّآ\nأَن جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗاۖ\nوَقَالُواْ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ\nكَانَتۡ مِنَ ٱلۡغَٰبِرِينَ\u{a0}٣٣\u{2}\n        \n         \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗا فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ\nٱللَّهَ وَٱرۡجُواْ ٱلۡيَوۡمَ ٱلۡأٓخِرَ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ\u{a0}٣٦\n\u{2}      \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي\nدَارِهِمۡ جَٰثِمِينَ\u{a0}٣٧\u{2}    \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَعَادٗا وَثَمُودَاْ وَقَد تَّبَيَّنَ\nلَكُم مِّن مَّسَٰكِنِهِمۡۖ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ\nأَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ\u{a0}٣٨\n\u{2}   \n     \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَقَٰرُونَ وَفِرۡعَوۡنَ وَهَٰمَٰنَۖ وَلَقَدۡ جَآءَهُم مُّوسَىٰ\nبِٱلۡبَيِّنَٰتِ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ وَمَا كَانُواْ سَٰبِقِينَ\u{a0}٣٩\n\u{2}     \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا\nٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ\nإِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ\u{a0}٤٦\n\u{2}        \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ\nيُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ\nإِلَّا ٱلۡكَٰفِرُونَ\u{a0}٤٧\u{2}      \n         \n \u{a0}\u{1}\u{2}\u{2}7\u{2}وَمَا كُنتَ تَتۡلُواْ مِن قَبۡلِهِۦ مِن كِتَٰبٖ\nوَلَا تَخُطُّهُۥ بِيَمِينِكَۖ إِذٗا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ\u{a0}٤٨\u{2}      \n     \u{a0}\u{1}\u{2}7\u{2}\u{2}بَلۡ هُوَ\nءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ\nبِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ\u{a0}٤٩\u{2} \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ\nءَايَٰتٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ\nمُّبِينٌ\u{a0}٥٠\u{2}   \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ\nيُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةٗ وَذِكۡرَىٰ لِقَوۡمٖ\nيُؤۡمِنُونَ\u{a0}٥١\u{2}     \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ شَهِيدٗاۖ\nيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ ءَامَنُواْ\nبِٱلۡبَٰطِلِ وَكَفَرُواْ بِٱللَّهِ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ\u{a0}٥٢\n\u{2}     \n      \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ\nلَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ\u{a0}٦٤\u{2}         \n    \u{a0}\u{1}\u{2}\u{2}4\u{2}فَإِذَا رَكِبُواْ فِي\nٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا\nهُمۡ يُشۡرِكُونَ\u{a0}٦٥\u{2}  \n          \n \u{a0}\u{1}\u{2}\u{2}5\u{2}لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡ وَلِيَتَمَتَّعُواْۚ فَسَوۡفَ\nيَعۡلَمُونَ\u{a0}٦٦\u{2}    \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ\nٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ\u{a0}٦٧\n\u{2}      \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ\nلَمَّا جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ\u{a0}٦٨\u{2}         \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ\nجَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ\u{a0}٦٩\n\u{2}\n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ\nغَلَبِهِمۡ سَيَغۡلِبُونَ\u{a0}٣\u{2}     \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}2\u{2}يَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ\u{a0}٧\n\u{2}         \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَتَفَكَّرُواْ فِيٓ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ\nوَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ\nبِلِقَآيِٕ رَبِّهِمۡ لَكَٰفِرُونَ\u{a0}٨\u{2}        \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ\nكَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗ\nوَأَثَارُواْ ٱلۡأَرۡضَ وَعَمَرُوهَآ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَآءَتۡهُمۡ\nرُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ\nأَنفُسَهُمۡ يَظۡلِمُونَ\u{a0}٩\u{2}    \n         \n      \n       \n \u{a0}\u{1}\u{2}\u{2}10\u{2}ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔواْ ٱلسُّوٓأَىٰٓ\nأَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ وَكَانُواْ بِهَا يَسۡتَهۡزِءُونَ\u{a0}١٠\u{2}     \n      \u{a0}\u{1}\u{2}10\u{2}\u{2}ٱللَّهُ\nيَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ\u{a0}١١\u{2}\n      \u{a0}\u{1}'
    '\u{2}11\u{2}\u{2}وَيَوۡمَ تَقُومُ\nٱلسَّاعَةُ يُبۡلِسُ ٱلۡمُجۡرِمُونَ\u{a0}١٢\u{2} \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَمۡ يَكُن لَّهُم مِّن شُرَكَآئِهِمۡ\nشُفَعَٰٓؤُاْ وَكَانُواْ بِشُرَكَآئِهِمۡ كَٰفِرِينَ\u{a0}١٣\u{2}    \n   \u{a0}\u{1}\u{2}13\u{2}\u{2}وَيَوۡمَ\nتَقُومُ ٱلسَّاعَةُ يَوۡمَئِذٖ يَتَفَرَّقُونَ\u{a0}١٤\u{2}\n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَمَّا ٱلَّذِينَ ءَامَنُواْ\nوَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَهُمۡ فِي رَوۡضَةٖ يُحۡبَرُونَ\u{a0}١٥\n\u{2}  \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَأَمَّا ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآيِٕ ٱلۡأٓخِرَةِ فَأُوْلَٰٓئِكَ\nفِي ٱلۡعَذَابِ مُحۡضَرُونَ\u{a0}١٦\u{2}       \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ إِنَّ\nفِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡعَٰلِمِينَ\u{a0}٢٢\u{2}  \n     \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمِنۡ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيۡلِ\nوَٱلنَّهَارِ وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ\nلِّقَوۡمٖ يَسۡمَعُونَ\u{a0}٢٣\u{2}   \n       \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ\nثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِي ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٢٧\u{2}   \n         \n   \u{a0}\u{1}\u{2}\u{2}8\u{2}ضَرَبَ لَكُم مَّثَلٗا مِّنۡ\nأَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن شُرَكَآءَ فِي\nمَا رَزَقۡنَٰكُمۡ فَأَنتُمۡ فِيهِ سَوَآءٞ تَخَافُونَهُمۡ كَخِيفَتِكُمۡ\nأَنفُسَكُمۡۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ\u{a0}٢٨\n\u{2}   \n         \n      \n     \u{a0}\n\u{1}\u{2}\u{2}\u{2}بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓاْ أَهۡوَآءَهُم بِغَيۡرِ عِلۡمٖۖ فَمَن يَهۡدِي مَنۡ\nأَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّٰصِرِينَ\u{a0}٢٩\u{2}         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَقِمۡ وَجۡهَكَ لِلدِّينِ\nحَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ\nٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ\nلَا يَعۡلَمُونَ\u{a0}٣٠\u{2}  \n         \n      \n \u{a0}\u{1}\u{2}\u{2}\u{2}۞ مُنِيبِينَ إِلَيۡهِ وَٱتَّقُوهُ وَأَقِيمُواْ ٱلصَّلَوٰةَ\nوَلَا تَكُونُواْ مِنَ ٱلۡمُشۡرِكِينَ\u{a0}٣١\u{2}    \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَآ ءَاتَيۡتُم مِّن رِّبٗا\nلِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن زَكَوٰةٖ\nتُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ\u{a0}٣٩\u{2}   \n           \n     \u{a0}\u{1}\u{2}11\u{2}\u{2}ٱللَّهُ ٱلَّذِي\nخَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۖ هَلۡ مِن\nشُرَكَآئِكُم مَّن يَفۡعَلُ مِن ذَٰلِكُم مِّن شَيۡءٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ\nعَمَّا يُشۡرِكُونَ\u{a0}٤٠\u{2} \n        \n        \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَٱنظُرۡ إِلَىٰٓ ءَاثَٰرِ رَحۡمَتِ ٱللَّهِ كَيۡفَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ\nمَوۡتِهَآۚ إِنَّ ذَٰلِكَ لَمُحۡيِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٥٠\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ ٱللَّهُ ٱلَّذِي خَلَقَكُم\nمِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ\nقُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ\u{a0}٥٤\n\u{2}  \n           \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ سَاعَةٖۚ\nكَذَٰلِكَ كَانُواْ يُؤۡفَكُونَ\u{a0}٥٥\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ\nلَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ\nوَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ\u{a0}٥٦\u{2}    \n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَيَوۡمَئِذٖ لَّا يَنفَعُ ٱلَّذِينَ\nظَلَمُواْ مَعۡذِرَتُهُمۡ وَلَا هُمۡ يُسۡتَعۡتَبُونَ\u{a0}٥٧\u{2}   \n    \u{a0}\u{1}\u{2}11\u{2}13\u{2}وَلَقَدۡ ضَرَبۡنَا\nلِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖۚ وَلَئِن جِئۡتَهُم بِـَٔايَةٖ\nلَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ\u{a0}٥٨\u{2} \n         \n      \u{a0}\u{1}\u{2}13\u{2}\u{2}كَذَٰلِكَ\nيَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ\u{a0}٥٩\u{2}\n      \u{a0}\u{1}\u{2}14\u{2}\u{2}فَٱصۡبِرۡ إِنَّ\nوَعۡدَ ٱللَّهِ حَقّٞۖ وَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ\u{a0}٦٠\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}خَلَقَ\nٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ\nبِكُمۡ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَنۢبَتۡنَا فِيهَا\nمِن كُلِّ زَوۡجٖ كَرِيمٍ\u{a0}١٠\u{2}\n         \n           \n   \u{a0}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَن يُسۡلِمۡ\nوَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ\nوَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ\u{a0}٢٢\u{2} \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن كَفَرَ فَلَا يَحۡزُنكَ كُفۡرُهُۥٓۚ\nإِلَيۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\u{a0}٢٣\n\u{2}    \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ\nوَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِيٓ إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَأَنَّ ٱللَّهَ\nبِمَا تَعۡمَلُونَ خَبِيرٞ\u{a0}٢٩\u{2}           \n         \n  \u{a0}\u{1}\u{2}3\u{2}4\u{2}ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ\nمِن دُونِهِ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ\u{a0}٣٠\u{2}       \n       \u{a0}\u{1}\u{2}4\u{2}6\u{2}أَلَمۡ تَرَ أَنَّ\nٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ\nفِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ\u{a0}٣١\u{2}  \n         \n     \u{a0}\u{1}\u{2}6\u{2}8\u{1}\u{2}9\u{2}12\u{1}\u{2}12\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}2\u{1}\u{2}3\u{2}4\u{2}أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمٗا\nمَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَهۡتَدُونَ\u{a0}٣\u{2}         \n       \u{a0}\u{1}\u{2}4\u{2}\u{2}ٱللَّهُ\nٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ\nثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا\nتَتَذَكَّرُونَ\u{a0}٤\u{2}\n        \n            \n\u{a0}\u{1}\u{2}7\u{2}8\u{2}يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ\nإِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٖ مِّمَّا تَعُدُّونَ\u{a0}٥\u{2}       \n        \u{a0}\u{1}\u{2}8\u{2}9\u{2}ذَٰلِكَ\nعَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ\u{a0}٦\u{2}\n    \u{a0}\u{1}\u{2}9\u{2}10\u{2}ٱلَّذِيٓ أَحۡسَنَ\nكُلَّ شَيۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَٰنِ مِن طِينٖ\u{a0}٧\u{2} \n       \u{a0}\u{1}\u{2}10\u{2}\u{2}ثُمَّ جَعَلَ\nنَسۡلَهُۥ مِن سُلَٰلَةٖ مِّن مَّآءٖ مَّهِينٖ\u{a0}٨\u{2} \n     \u{a0}\u{1}\u{2}11\u{2}\u{2}ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ\nمِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا\nمَّا تَشۡكُرُونَ\u{a0}٩\u{2}   \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالُوٓاْ أَءِذَا ضَلَلۡنَا فِي ٱلۡأَرۡضِ أَءِنَّا لَفِي\nخَلۡقٖ جَدِيدِۭۚ بَلۡ هُم بِلِقَآءِ رَبِّهِمۡ كَٰفِرُونَ\u{a0}١٠\u{2}      \n      \u{a0}\u{1}\u{2}\u{2}\u{2}۞ قُلۡ يَتَوَفَّىٰكُم\nمَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ\u{a0}١١\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡ شِئۡنَا لَأٓتَيۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَٰكِنۡ حَقَّ ٱلۡقَوۡلُ\nمِنِّي لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ\u{a0}١٣\n\u{2}        \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ\nبِمَا كَانُواْ يَعۡمَلُونَ\u{a0}١٧\u{2}         \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَأَمَّا ٱلَّذِينَ فَسَقُواْ\nفَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا وَقِيلَ\nلَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ\u{a0}٢٠\n\u{2}  \n         \n       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ\nأَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ\u{a0}٢٢\u{2}      \n     \u{a0}\u{1}\u{2}3\u{2}\u{2}وَلَقَدۡ ءَاتَيۡنَا\nمُوسَى ٱلۡكِتَٰبَ فَلَا تَكُن فِي مِرۡيَةٖ مِّن لِّقَآئِهِۦۖ وَجَعَلۡنَٰهُ\nهُدٗى لِّبَنِيٓ إِسۡرَٰٓءِيلَ\u{a0}٢٣\u{2} \n        \n  \u{a0}\u{1}\u{2}5\u{2}6\u{2}وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ\nبِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ\u{a0}٢٤\u{2}   \n     \u{a0}\u{1}\u{2}6\u{2}7\u{2}إِنَّ رَبَّكَ\nهُوَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ\u{a0}٢٥\n\u{2} \n        \u{a0}\n\u{1}\u{2}\u{2}9\u{2}أَوَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ\nيَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ\u{a0}٢٦\n\u{2}        \n        \u{a0}\n\u{1}\u{2}10\u{2}11\u{2}أَوَلَمۡ يَرَوۡاْ أَنَّا نَسُوقُ ٱلۡمَآءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ\nبِهِۦ زَرۡعٗا تَأۡكُلُ مِنۡهُ أَنۡعَٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا يُبۡصِرُونَ\u{a0}٢٧\n\u{2}        \n       \u{a0}\n\u{1}\u{2}12\u{2}12\u{1}\u{2}13\u{2}13\u{2}قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ\u{a0}٢٩\n\u{2}          \u{a0}\n\u{1}\u{2}14\u{2}14\u{1}\u{2}2\u{2}3\u{1}\u{2}3\u{2}4\u{2}وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن\nرَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا\u{a0}٢\u{2}    \n      \u{a0}\u{1}\u{2}4\u{2}5\u{1}\u{2}5\u{2}8\u{2}مَّا جَعَلَ ٱللَّهُ لِرَجُلٖ مِّن قَلۡبَيۡنِ فِي\nجَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ\nوَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ\nيَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ\u{a0}٤\u{2}      \n       \n       \n    \u{a0}\u{1}\u{2}8\u{2}11\u{2}ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ\nهُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ\nفِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم\nبِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا\u{a0}٥\n\u{2} \n        \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ\nوَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِ\nمِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم\nمَّعۡرُوفٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا\u{a0}٦\n\u{2}      \n       \n       \n     \u{a0}\n\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَت طَّآئِفَةٞ\nمِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ\nمِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا\nفِرَارٗا\u{a0}١٣\u{2}  \n        \n           \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ\nأَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةٗۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ\nوَلِيّٗا وَلَا نَصِيرٗا\u{a0}١٧\u{2}       \n            \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ\nلِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا\u{a0}١٨\u{2}     \n       \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}يَحۡسَبُونَ ٱلۡأَحۡزَابَ\nلَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم بَادُونَ\nفِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم\nمَّا قَٰتَلُوٓاْ إِلَّا قَلِيلٗا\u{a0}٢٠\u{2} \n        \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ\nحَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا\u{a0}٢١\n\u{2}      \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لِّيَجۡزِيَ\nٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ\nأَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا\u{a0}٢٤\u{2}\n      \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَرَدَّ ٱللَّهُ ٱلَّذِينَ\nكَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرٗاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ\nوَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا\u{a0}٢٥\u{2}  \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ\nأَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا\u{a0}٣١\u{2}       \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَسَبِّحُوهُ بُكۡرَةٗ\nوَأَصِيلًا\u{a0}٤٢\u{2} \n\u{a0}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَٰٓئِكَتُهُۥ لِيُخۡرِجَكُم\nمِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمٗا\u{a0}٤٣\n\u{2}     \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ\nأَحۡلَلۡنَا لَكَ أَزۡوَٰجَكَ ٱلَّٰتِيٓ ءَاتَيۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ\nيَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ\nوَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِي هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةٗ\nمُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِيِّ إِنۡ أَرَادَ ٱلنَّبِيُّ أَن يَسۡتَنكِحَهَا\nخَالِصَةٗ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِينَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا\nعَلَيۡهِمۡ فِيٓ أَزۡوَٰجِهِمۡ وَمَا مَلَكَتۡ أَيۡمَٰنُهُمۡ لِكَيۡلَا\nيَكُونَ عَلَيۡكَ حَرَجٞۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا\u{a0}٥٠\n\u{2}  \n       \n        \n       \n         \n        \n      \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ تُرۡجِي مَن تَشَآءُ مِنۡهُنَّ وَتُـٔۡوِيٓ إِلَيۡكَ مَن تَشَآءُۖ وَمَنِ ٱبۡتَغَيۡتَ\nمِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَيۡكَۚ ذَٰلِكَ أَدۡنَىٰٓ أَن تَقَرَّ أَعۡيُنُهُنَّ\nوَلَا يَحۡزَنَّ وَيَرۡضَيۡنَ بِمَآ ءَاتَيۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ يَعۡلَمُ\nمَا فِي قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمٗا\u{a0}٥١\u{2}         \n         \n       \n      \u{a0}\u{1}\u{2}\u{2}6\u{2}لَّا يَحِلُّ لَكَ\nٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجٖ وَلَوۡ أَعۡجَبَكَ\nحُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ يَمِينُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ رَّقِيبٗا\u{a0}٥٢\n\u{2}  \n          \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن\nيُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ\nفَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ\nذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا\nيَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن\nوَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ\nلَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ\nمِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا\u{a0}٥٣\u{2}        \n         \n       \n       \n       \n       \n        \n        \u{a0}\u{1}\u{2}14\u{2}\u{2}إِن\nتُبۡدُواْ شَيۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا\u{a0}٥٤\n\u{2}\n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}لَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ\nإِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ\nأَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا\u{a0}٥٥\n\u{2}          \n        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ\nبِغَيۡرِ مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا\u{a0}٥٨\n\u{2}   \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ\nعَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ ذَٰلِكَ أَدۡنَىٰٓ أَن يُعۡرَفۡنَ فَلَا يُؤۡذَيۡنَۗ وَكَانَ\nٱللَّهُ غَفُورٗا رَّحِيمٗا\u{a0}٥٩\u{2}       \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ\nفِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ\nبِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا\u{a0}٦٠\u{2}    \n      \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ\nوَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۚ وَهُوَ\nٱلرَّحِيمُ ٱلۡغَفُورُ\u{a0}٢\u{2}    \n          \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ\nوَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ\nٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفٗا مِّنَ ٱلسَّمَآءِۚ إِنَّ فِي ذَٰلِكَ\nلَأٓيَةٗ لِّكُلِّ عَبۡدٖ مُّنِيبٖ\u{a0}٩\u{2}     \n        \n         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ\nيَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ\u{a0}١٠\u{2}    \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ\nإِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ\nعَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ\u{a0}٢١\u{2}     \n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِ\nٱللَّهِ لَا يَمۡلِكُونَ مِثۡقَالَ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي\nٱلۡأَرۡضِ وَمَا لَهُمۡ فِيهِمَا مِن شِرۡكٖ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِيرٖ\u{a0}٢٢\n\u{2}     \n        \n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ\nوَإِنَّآ أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِي ضَلَٰلٖ مُّبِينٖ\u{a0}٢٤\u{2}       \n        \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ\nلَا يَعۡلَمُونَ\u{a0}٣٦\u{2}          \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَآ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُم بِٱلَّتِي تُقَرِّبُكُمۡ عِندَنَا\nزُلۡفَىٰٓ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَٰٓئِكَ لَهُمۡ جَزَآءُ ٱلضِّعۡفِ\nبِمَا عَمِلُواْ وَهُمۡ فِي ٱلۡغُرُفَٰتِ ءَامِنُونَ\u{a0}٣٧\u{2}      \n         \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ يَسۡعَوۡنَ فِيٓ\nءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ\u{a0}٣٨\u{2}  \n     \u{a0}\u{1}\u{2}13\u{2}\u{2}قُلۡ\nإِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥۚ وَمَآ\nأَنفَقۡتُم مِّن شَيۡءٖ فَهُوَ يُخۡلِفُهُۥۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ\u{a0}٣٩\n\u{2}\n          \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَكَذَّبَ\nٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ\nفَكَيۡفَ كَانَ نَكِيرِ\u{a0}٤٥\u{2}\n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ قُلۡ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ أَن\nتَقُومُواْ لِلَّهِ مَثۡنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُواْۚ مَا بِصَاحِبِكُم\nمِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ لَّكُم بَيۡنَ يَدَيۡ عَذَابٖ شَدِيدٖ\u{a0}٤٦\n\u{2}    \n       \n          \u{a0}\n\u{1}\u{2}14\u{2}\u{2}قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرٖ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ\nكُلِّ شَيۡءٖ شَهِيدٞ\u{a0}٤٧\u{2}             \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{2}\u{2}\u{2}ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَٰٓئِكَةِ رُسُلًا أُوْلِيٓ\nأَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ\nشَيۡءٖ قَدِيرٞ\u{a0}١\u{2}        \n            \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ\nوَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٢\u{2}        \n         \u{a0}\u{1}\u{2}13\u{2}\u{2}يَٰٓأَيُّهَا\nٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم\nمِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ\u{a0}٣\n\u{2}\n          \n        \u{a0}\n\u{1}\u{2}\u{2}1\u{2}وَإِن يُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ\u{a0}٤\n\u{2}          \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا\nوَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ\u{a0}٥\u{2}         \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ\nفَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ\nعَلَيۡهِمۡ حَسَرَٰتٍۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَصۡنَعُونَ\u{a0}٨\u{2}      \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱللَّهُ ٱلَّذِيٓ أَرۡسَلَ\nٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَسُقۡنَٰهُ إِلَىٰ بَلَدٖ مَّيِّتٖ فَأَحۡيَيۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ\nمَوۡتِهَاۚ كَذَٰلِكَ ٱلنُّشُورُ\u{a0}٩\u{2}  \n          \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ\nٱلۡحَمِيدُ\u{a0}١٥\u{2}        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}3\u{2}وَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ\nإِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ\u{a0}٢٢\u{2}    \n          \u{a0}\u{1}\u{2}3\u{2}\u{2}إِنۡ\nأَنتَ إِلَّا نَذِيرٌ\u{a0}٢٣\u{2}\n  \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۚ وَإِن مِّنۡ\nأُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٞ\u{a0}٢٤\u{2}      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِينَ\nمِن قَبۡلِهِمۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَٰبِ\nٱلۡمُنِيرِ\u{a0}٢٥\u{2}    \n      \n\u{a0}\u{1}\u{2}\u{2}7\u{2}ثُمَّ أَخَذۡتُ ٱلَّذِينَ كَفَرُواْۖ فَكَيۡفَ كَانَ نَكِيرِ\u{a0}٢٦\n\u{2}      \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا\nأَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا\nوَغَرَابِيبُ سُودٞ\u{a0}٢٧\u{2}           \n       \n \u{a0}\u{1}\u{2}10\u{2}\u{2}وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ\nمُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ\nإِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ\u{a0}٢٨\u{2}   \n        \n   \u{a0}\u{1}\u{2}12\u{2}\u{2}إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ\nوَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ\nيَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ\u{a0}٢٩\u{2}    \n      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}لِيُوَفِّيَهُمۡ أُجُورَهُمۡ\nوَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ\u{a0}٣٠\n\u{2} \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِنَّ ٱللَّهَ يُمۡسِكُ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَئِن زَالَتَآ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدٖ مِّنۢ بَعۡدِهِۦٓۚ\nإِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا\u{a0}٤١\u{2}   \n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن\nجَآءَهُمۡ نَذِيرٞ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرٞ\nمَّا زَادَهُمۡ إِلَّا نُفُورًا\u{a0}٤٢\u{2}    \n         \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ\nظَهۡرِهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ\nفَإِذَا جَآءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرَۢا\u{a0}٤٥\n\u{2}        \n       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لِتُنذِرَ قَوۡمٗا مَّآ\nأُنذِرَ ءَابَآؤُهُمۡ فَهُمۡ غَٰفِلُونَ\u{a0}٦\u{2}  \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ\nمَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ\u{a0}١٢\n\u{2}    \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثٖ فَقَالُوٓاْ إِنَّآ\nإِلَيۡكُم مُّرۡسَلُونَ\u{a0}١٤\u{2}        \n \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ مَآ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا وَمَآ أَنزَلَ\nٱلرَّحۡمَٰنُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ\u{a0}١٥\u{2}       \n      \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}قَالُواْ رَبُّنَا يَعۡلَمُ إِنَّآ\nإِلَيۡكُمۡ لَمُرۡسَلُونَ\u{a0}١٦\u{2}   \n \u{a0}\u{1}\u{2}\u{2}5\u{2}وَمَا عَلَيۡنَآ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ\u{a0}١٧\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالُوٓاْ إِنَّا تَطَيَّرۡنَا بِكُمۡۖ لَئِن لَّمۡ تَنتَهُواْ لَنَرۡجُمَنَّكُمۡ وَلَيَمَسَّنَّكُم\nمِّنَّا عَذَابٌ أَلِيمٞ\u{a0}١٨\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قَالُواْ طَٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ\nبَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ\u{a0}١٩\u{2}    \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ\nيَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ\u{a0}٢٠\u{2}    \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ٱتَّبِعُواْ مَن\nلَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ\u{a0}٢١\u{2} \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا لِيَ لَآ أَعۡبُدُ ٱلَّذِي\nفَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ\u{a0}٢٢\u{2}    \n  \u{a0}\u{1}\u{2}\u{2}\u{2}ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن\nيُرِدۡنِ ٱلرَّحۡمَٰنُ بِضُرّٖ لَّا تُغۡنِ عَنِّي شَفَٰعَتُهُمۡ شَيۡـٔٗا وَلَا\nيُنقِذُونِ\u{a0}٢٣\u{2}    \n        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا\nكُنَّا مُنزِلِينَ\u{a0}٢٨\u{2}          \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}5\u{2}وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ\u{a0}٤٦\n\u{2}          \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُمۡ أَنفِقُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُواْ\nلِلَّذِينَ ءَامَنُوٓاْ أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ إِنۡ أَنتُمۡ إِلَّا فِي\nضَلَٰلٖ مُّبِينٖ\u{a0}٤٧\u{2}         \n           \n \u{a0}\u{1}\u{2}\u{2}8\u{2}وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}٤٨\n\u{2}      \u{a0}\n\u{1}\u{2}\u{2}9\u{2}مَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ\u{a0}٤٩\n\u{2}       \u{a0}\n\u{1}\u{2}\u{2}10\u{2}فَلَا يَسۡتَطِيعُونَ تَوۡصِيَةٗ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ\u{a0}٥٠\n\u{2}      \u{a0}\n\u{1}\u{2}\u{2}11\u{2}وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ يَنسِلُونَ\u{a0}٥١\n\u{2}         \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ\nوَصَدَقَ ٱلۡمُرۡسَلُونَ\u{a0}٥٢\u{2}         \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَهُمۡ فِيهَا فَٰكِهَةٞ وَلَهُم\nمَّا يَدَّعُونَ\u{a0}٥٧\u{2}   \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱمۡتَٰزُواْ ٱلۡيَوۡمَ\nأَيُّهَا ٱلۡمُجۡرِمُونَ\u{a0}٥٩\u{2} \n \u{a0}\u{1}\u{2}\u{2}\u{2}۞ أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا\nتَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ\u{a0}٦٠\u{2}      \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَنِ ٱعۡبُدُونِيۚ\nهَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ\u{a0}٦١\u{2} \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلّٗا كَثِيرًاۖ\nأَفَلَمۡ تَكُونُواْ تَعۡقِلُونَ\u{a0}٦٢\u{2}    \n  \u{a0}\u{1}\u{2}\u{2}7\u{2}هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي كُنتُمۡ تُوعَدُونَ\u{a0}٦٣\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱصۡلَوۡهَا ٱلۡيَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ\u{a0}٦٤\u{2}    \u{a0}\u{1}\u{2}8\u{2}\u{2}ٱلۡيَوۡمَ نَخۡتِمُ\nعَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ\nيَكۡسِبُونَ\u{a0}٦٥\u{2} \n       \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلَوۡ نَشَآءُ لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ فَٱسۡتَبَقُواْ\nٱلصِّرَٰطَ فَأَنَّىٰ يُبۡصِرُونَ\u{a0}٦٦\u{2}     \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ أَفَلَا يَعۡقِلُونَ\u{a0}٦٨\n\u{2}      \u{a0}\n\u{1}\u{2}14\u{2}\u{2}وَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ وَقُرۡءَانٞ مُّبِينٞ\u{a0}٦٩\n\u{2}           \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا\nمَٰلِكُونَ\u{a0}٧١\u{2}          \n\u{a0}\u{1}\u{2}\u{2}2\u{2}وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُلُونَ\u{a0}٧٢\n\u{2}     \u{a0}\n\u{1}\u{2}\u{2}3\u{2}وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ\u{a0}٧٣\u{2}     \u{a0}\u{1}\u{2}3\u{2}4\u{2}وَٱتَّخَذُواْ\nمِن دُونِ ٱللَّهِ ءَالِهَةٗ لَّعَلَّهُمۡ يُنصَرُونَ\u{a0}٧٤\u{2}\n     \u{a0}\u{1}\u{2}4\u{2}5\u{2}لَا يَسۡتَطِيعُونَ\nنَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندٞ مُّحۡضَرُونَ\u{a0}٧٥\u{2} \n    \u{a0}\u{1}'
    '\u{2}5\u{2}6\u{2}فَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ\nإِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ\u{a0}٧٦\u{2}  \n     \u{a0}\u{1}\u{2}6\u{2}7\u{2}أَوَلَمۡ يَرَ ٱلۡإِنسَٰنُ أَنَّا\nخَلَقۡنَٰهُ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ\u{a0}٧٧\u{2}   \n      \u{a0}\u{1}\u{2}7\u{2}8\u{1}\u{2}9\u{2}9\u{1}\u{2}10\u{2}11\u{1}\u{2}11\u{2}12\u{1}\u{2}13\u{2}13\u{1}\u{2}14\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}2\u{2}فَٱلتَّٰلِيَٰتِ ذِكۡرًا\u{a0}٣\n\u{2} \u{a0}\n\u{1}\u{2}\u{2}3\u{2}إِنَّ إِلَٰهَكُمۡ لَوَٰحِدٞ\u{a0}٤\u{2}  \u{a0}\u{1}\u{2}3\u{2}\u{2}رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ\nٱلۡمَشَٰرِقِ\u{a0}٥\u{2}     \n\u{a0}\u{1}\u{2}\u{2}4\u{2}إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ\u{a0}٦\u{2}     \u{a0}\u{1}\u{2}4\u{2}\u{2}وَحِفۡظٗا\nمِّن كُلِّ شَيۡطَٰنٖ مَّارِدٖ\u{a0}٧\u{2}\n   \u{a0}\u{1}\u{2}5\u{2}\u{2}لَّا يَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَيُقۡذَفُونَ\nمِن كُلِّ جَانِبٖ\u{a0}٨\u{2}     \n  \u{a0}\u{1}\u{2}\u{2}6\u{2}دُحُورٗاۖ وَلَهُمۡ عَذَابٞ وَاصِبٌ\u{a0}٩\u{2}   \u{a0}\u{1}\u{2}6\u{2}\u{2}إِلَّا مَنۡ خَطِفَ\nٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابٞ ثَاقِبٞ\u{a0}١٠\u{2}  \n   \u{a0}\u{1}\u{2}7\u{2}\u{2}فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا\nأَم مَّنۡ خَلَقۡنَآۚ إِنَّا خَلَقۡنَٰهُم مِّن طِينٖ لَّازِبِۭ\u{a0}١١\u{2}   \n       \u{a0}\u{1}\u{2}8\u{2}\u{2}بَلۡ عَجِبۡتَ\nوَيَسۡخَرُونَ\u{a0}١٢\u{2} \n\u{a0}\u{1}\u{1}\u{2}\u{2}9\u{2}وَإِذَا رَأَوۡاْ ءَايَةٗ يَسۡتَسۡخِرُونَ\u{a0}١٤\n\u{2}   \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا\nأَءِنَّا لَمَبۡعُوثُونَ\u{a0}١٦\u{2}    \n \u{a0}\u{1}\u{1}\u{2}\u{2}11\u{2}قُلۡ نَعَمۡ وَأَنتُمۡ دَٰخِرُونَ\u{a0}١٨\n\u{2}   \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالُواْ يَٰوَيۡلَنَا هَٰذَا\nيَوۡمُ ٱلدِّينِ\u{a0}٢٠\u{2}  \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ\u{a0}٢٢\u{2}      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}5\u{2}فَإِنَّهُمۡ يَوۡمَئِذٖ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ\u{a0}٣٣\n\u{2}    \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّهُمۡ كَانُوٓاْ إِذَا قِيلَ لَهُمۡ\nلَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسۡتَكۡبِرُونَ\u{a0}٣٥\u{2}    \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ لَهُمۡ رِزۡقٞ مَّعۡلُومٞ\u{a0}٤١\n\u{2}   \u{a0}\n\u{1}\u{2}11\u{2}\u{2}فَوَٰكِهُ وَهُم مُّكۡرَمُونَ\u{a0}٤٢\u{2}  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّهَا شَجَرَةٞ\nتَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ\u{a0}٦٤\u{2} \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّهُۥ مِنۡ\nعِبَادِنَا ٱلۡمُؤۡمِنِينَ\u{a0}٨١\u{2} \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَإِنَّ مِن\nشِيعَتِهِۦ لَإِبۡرَٰهِيمَ\u{a0}٨٣\u{2} \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَ\nلِأَبِيهِ وَقَوۡمِهِۦ مَاذَا تَعۡبُدُونَ\u{a0}٨٥\u{2} \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ\nيَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ\nيَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ\u{a0}١٠٢\n\u{2}    \n          \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَنَٰدَيۡنَٰهُ أَن يَٰٓإِبۡرَٰهِيمُ\u{a0}١٠٤\u{2}  \u{a0}\u{1}\u{2}1\u{2}\u{2}قَدۡ\nصَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ\u{a0}١٠٥\u{2}\n     \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ هَٰذَا لَهُوَ\nٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ\u{a0}١٠٦\u{2}  \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَتَرَكۡنَا عَلَيۡهِ فِي\nٱلۡأٓخِرِينَ\u{a0}١٠٨\u{2}  \n\u{a0}\u{1}\u{1}\u{2}\u{2}4\u{2}كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ\u{a0}١١٠\n\u{2}  \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيّٗا مِّنَ\nٱلصَّٰلِحِينَ\u{a0}١١٢\u{2}   \n\u{a0}\u{1}'
    '\u{2}\u{2}\u{2}وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا\nمُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ\u{a0}١١٣\u{2}     \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ مَنَنَّا عَلَىٰ مُوسَىٰ\nوَهَٰرُونَ\u{a0}١١٤\u{2}   \n\u{a0}\u{1}\u{2}\u{2}8\u{2}وَنَجَّيۡنَٰهُمَا وَقَوۡمَهُمَا مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ\u{a0}١١٥\n\u{2}    \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَءَاتَيۡنَٰهُمَا ٱلۡكِتَٰبَ\nٱلۡمُسۡتَبِينَ\u{a0}١١٧\u{2} \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَهَدَيۡنَٰهُمَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ\u{a0}١١٨\u{2}  \u{a0}\u{1}\u{2}10\u{2}\u{2}وَتَرَكۡنَا\nعَلَيۡهِمَا فِي ٱلۡأٓخِرِينَ\u{a0}١١٩\u{2}\n  \u{a0}\u{1}\u{2}\u{2}11\u{2}سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ\u{a0}١٢٠\n\u{2}   \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّهُمَا مِنۡ\nعِبَادِنَا ٱلۡمُؤۡمِنِينَ\u{a0}١٢٢\u{2} \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّا كَذَٰلِكَ\nنَجۡزِي ٱلۡمُحۡسِنِينَ\u{a0}١٣١\u{2} \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ\u{a0}١٣٢\u{2}   \u{a0}\u{1}\u{2}3\u{2}\u{2}وَإِنَّ لُوطٗا\nلَّمِنَ ٱلۡمُرۡسَلِينَ\u{a0}١٣٣\u{2} \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ نَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ\u{a0}١٣٤\u{2}   \u{a0}\u{1}\u{2}4\u{2}\u{2}إِلَّا عَجُوزٗا\nفِي ٱلۡغَٰبِرِينَ\u{a0}١٣٥\u{2} \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم\nمُّصۡبِحِينَ\u{a0}١٣٧\u{2}  \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِنَّ يُونُسَ لَمِنَ\nٱلۡمُرۡسَلِينَ\u{a0}١٣٩\u{2}  \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ\u{a0}١٤٠\u{2}    \u{a0}\u{1}\u{2}7\u{2}\u{2}فَسَاهَمَ فَكَانَ\nمِنَ ٱلۡمُدۡحَضِينَ\u{a0}١٤١\u{2} \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ\u{a0}١٤٢\u{2}   \u{a0}\u{1}\u{2}8\u{2}\u{2}فَلَوۡلَآ أَنَّهُۥ\nكَانَ مِنَ ٱلۡمُسَبِّحِينَ\u{a0}١٤٣\u{2} \n  \u{a0}\u{1}\u{2}\u{2}9\u{2}لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ\u{a0}١٤٤\n\u{2}     \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ\u{a0}١٤٥\u{2}   \u{a0}\u{1}\u{2}\u{2}\u{2}وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ\nمِّن يَقۡطِينٖ\u{a0}١٤٦\u{2}  \n \u{a0}\u{1}\u{2}\u{2}11\u{2}وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ\u{a0}١٤٧\n\u{2}     \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}فَٱسۡتَفۡتِهِمۡ أَلِرَبِّكَ ٱلۡبَنَاتُ\nوَلَهُمُ ٱلۡبَنُونَ\u{a0}١٤٩\u{2}  \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ خَلَقۡنَا ٱلۡمَلَٰٓئِكَةَ إِنَٰثٗا وَهُمۡ\nشَٰهِدُونَ\u{a0}١٥٠\u{2}    \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}1\u{2}أَمۡ لَكُمۡ سُلۡطَٰنٞ مُّبِينٞ\u{a0}١٥٦\n\u{2}   \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَجَعَلُواْ بَيۡنَهُۥ وَبَيۡنَ ٱلۡجِنَّةِ\nنَسَبٗاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ\u{a0}١٥٨\u{2}   \n     \u{a0}\u{1}\u{2}3\u{2}\u{2}سُبۡحَٰنَ ٱللَّهِ عَمَّا\nيَصِفُونَ\u{a0}١٥٩\u{2}  \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ\u{a0}١٦٠\u{2}   \u{a0}\u{1}\u{2}4\u{2}4\u{2}فَإِنَّكُمۡ وَمَا تَعۡبُدُونَ\u{a0}١٦١\n\u{2}  \u{a0}\n\u{1}\u{2}\u{2}\u{2}مَآ أَنتُمۡ عَلَيۡهِ بِفَٰتِنِينَ\u{a0}١٦٢\u{2}   \u{a0}\u{1}\u{2}5\u{2}5\u{1}\u{2}5\u{2}\u{2}وَمَا مِنَّآ إِلَّا\nلَهُۥ مَقَامٞ مَّعۡلُومٞ\u{a0}١٦٤\u{2}  \n  \u{a0}\u{1}\u{2}6\u{2}6\u{1}\u{2}6\u{2}6\u{1}\u{2}7\u{2}7\u{1}\u{2}7\u{2}7\u{2}لَوۡ أَنَّ عِندَنَا ذِكۡرٗا مِّنَ ٱلۡأَوَّلِينَ\u{a0}١٦٨\u{2}     \u{a0}\u{1}\u{2}7\u{2}8\u{2}لَكُنَّا\nعِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ\u{a0}١٦٩\u{2}\n  \u{a0}\u{1}\u{2}8\u{2}8\u{1}\u{2}8\u{2}9\u{1}\u{2}9\u{2}9\u{2}إِنَّهُمۡ لَهُمُ ٱلۡمَنصُورُونَ\u{a0}١٧٢\u{2}  \u{a0}\u{1}'
    '\u{2}9\u{2}10\u{2}وَإِنَّ\nجُندَنَا لَهُمُ ٱلۡغَٰلِبُونَ\u{a0}١٧٣\u{2}\n  \u{a0}\u{1}\u{2}10\u{2}10\u{1}\u{2}10\u{2}11\u{2}وَأَبۡصِرۡهُمۡ فَسَوۡفَ\nيُبۡصِرُونَ\u{a0}١٧٥\u{2} \n\u{a0}\u{1}\u{2}11\u{2}11\u{1}\u{2}11\u{2}12\u{2}فَإِذَا نَزَلَ بِسَاحَتِهِمۡ فَسَآءَ\nصَبَاحُ ٱلۡمُنذَرِينَ\u{a0}١٧٧\u{2}   \n \u{a0}\u{1}\u{2}12\u{2}12\u{1}\u{2}12\u{2}13\u{2}وَأَبۡصِرۡ فَسَوۡفَ\nيُبۡصِرُونَ\u{a0}١٧٩\u{2} \n\u{a0}\u{1}\u{2}13\u{2}13\u{1}\u{2}14\u{2}14\u{1}\u{2}14\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}2\u{1}\u{2}3\u{2}3\u{1}\u{2}3\u{2}4\u{2}وَعَجِبُوٓاْ\nأَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرٞ كَذَّابٌ\u{a0}٤\n\u{2}\n        \u{a0}\n\u{1}\u{2}\u{2}5\u{2}أَجَعَلَ ٱلۡأٓلِهَةَ إِلَٰهٗا وَٰحِدًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عُجَابٞ\u{a0}٥\u{2}       \u{a0}\u{1}\u{2}5\u{2}6\u{2}وَٱنطَلَقَ ٱلۡمَلَأُ\nمِنۡهُمۡ أَنِ ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءٞ يُرَادُ\u{a0}٦\n\u{2} \n         \u{a0}\n\u{1}\u{2}\u{2}7\u{2}مَا سَمِعۡنَا بِهَٰذَا فِي ٱلۡمِلَّةِ ٱلۡأٓخِرَةِ إِنۡ هَٰذَآ إِلَّا ٱخۡتِلَٰقٌ\u{a0}٧\u{2}         \u{a0}\u{1}\u{2}7\u{2}8\u{2}أَءُنزِلَ\nعَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكّٖ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ\u{a0}٨\n\u{2}\n             \u{a0}\n\u{1}\u{2}\u{2}9\u{2}أَمۡ عِندَهُمۡ خَزَآئِنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِيزِ ٱلۡوَهَّابِ\u{a0}٩\u{2}      \u{a0}\u{1}\u{2}9\u{2}10\u{2}أَمۡ لَهُم\nمُّلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ فَلۡيَرۡتَقُواْ فِي ٱلۡأَسۡبَٰبِ\u{a0}١٠\n\u{2} \n       \u{a0}\n\u{1}\u{2}\u{2}11\u{2}جُندٞ مَّا هُنَالِكَ مَهۡزُومٞ مِّنَ ٱلۡأَحۡزَابِ\u{a0}١١\u{2}     \u{a0}\u{1}\u{2}11\u{2}\u{2}كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ\nنُوحٖ وَعَادٞ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ\u{a0}١٢\u{2}  \n    \u{a0}\u{1}\u{2}12\u{2}\u{2}وَثَمُودُ وَقَوۡمُ لُوطٖ وَأَصۡحَٰبُ\nلۡـَٔيۡكَةِۚ أُوْلَٰٓئِكَ ٱلۡأَحۡزَابُ\u{a0}١٣\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}\u{2}إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ\nفَحَقَّ عِقَابِ\u{a0}١٤\u{2}    \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ مَّا لَهَا\nمِن فَوَاقٖ\u{a0}١٥\u{2}       \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ\u{a0}١٧\n\u{2}          \u{a0}\n\u{1}\u{2}2\u{2}\u{2}إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ\u{a0}١٨\u{2}      \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَهَلۡ أَتَىٰكَ نَبَؤُاْ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُواْ\nٱلۡمِحۡرَابَ\u{a0}٢١\u{2}     \n\u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ\nلَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي\nبَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلٞ\nمَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩\u{a0}٢٤\n\u{2}\n          \n        \n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ\nبِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ\nعَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ\u{a0}٢٦\n\u{2}        \n          \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا بَٰطِلٗاۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُواْۚ\nفَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِنَ ٱلنَّارِ\u{a0}٢٧\u{2}          \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَقَالَ إِنِّيٓ\nأَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ\u{a0}٣٢\n\u{2} \n        \u{a0}\n\u{1}\u{2}8\u{2}\u{2}رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ\u{a0}٣٣\u{2}     \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ فَتَنَّا\nسُلَيۡمَٰنَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدٗا ثُمَّ أَنَابَ\u{a0}٣٤\u{2} \n      \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ رَبِّ ٱغۡفِرۡ\nلِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ\u{a0}٣٥\n\u{2}  \n           \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ\nنِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ\u{a0}٤٤\u{2}         \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ\nأُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ\u{a0}٤٥\u{2}    \n  \u{a0}\u{1}\u{2}\u{2}5\u{2}إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةٖ ذِكۡرَى\nٱلدَّارِ\u{a0}٤٦\u{2}   \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱذۡكُرۡ\nإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ\u{a0}٤٨\u{2}\n      \u{a0}\u{1}\u{2}\u{2}\u{2}هَٰذَا ذِكۡرٞۚ\nوَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٖ\u{a0}٤٩\u{2} \n   \u{a0}\u{1}\u{2}\u{2}\u{2}جَنَّٰتِ عَدۡنٖ مُّفَتَّحَةٗ لَّهُمُ ٱلۡأَبۡوَٰبُ\u{a0}٥٠\n\u{2}    \u{a0}\n\u{1}'
    '\u{2}8\u{2}\u{2}مُتَّكِـِٔينَ فِيهَا يَدۡعُونَ فِيهَا بِفَٰكِهَةٖ كَثِيرَةٖ وَشَرَابٖ\u{a0}٥١\n\u{2}      \u{a0}\n\u{1}\u{2}9\u{2}\u{2}۞ وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ\u{a0}٥٢\u{2}   \u{a0}\u{1}\u{2}\u{2}10\u{2}هَٰذَا مَا تُوعَدُونَ لِيَوۡمِ\nٱلۡحِسَابِ\u{a0}٥٣\u{2}   \n\u{a0}\u{1}\u{2}10\u{2}\u{2}إِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ\u{a0}٥٤\u{2}      \u{a0}\u{1}\u{2}\u{2}11\u{2}هَٰذَاۚ وَإِنَّ\nلِلطَّٰغِينَ لَشَرَّ مَـَٔابٖ\u{a0}٥٥\u{2} \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}هَٰذَا\nفَلۡيَذُوقُوهُ حَمِيمٞ وَغَسَّاقٞ\u{a0}٥٧\u{2}\n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَءَاخَرُ مِن شَكۡلِهِۦٓ أَزۡوَٰجٌ\u{a0}٥٨\n\u{2}   \u{a0}\n\u{1}\u{2}13\u{2}\u{2}هَٰذَا فَوۡجٞ مُّقۡتَحِمٞ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُواْ ٱلنَّارِ\u{a0}٥٩\n\u{2}         \u{a0}\n\u{1}\u{2}14\u{2}\u{2}قَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ\u{a0}٦٠\n\u{2}          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِذۡ قَالَ رَبُّكَ\nلِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن طِينٖ\u{a0}٧١\u{2}  \n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ\nمِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ\u{a0}٧٢\u{2}   \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}11\u{2}قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ\u{a0}٧٦\n\u{2}         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ\nمِنۡهُمۡ أَجۡمَعِينَ\u{a0}٨٥\u{2}    \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَا\nلِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ\nمَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ بَيۡنَهُمۡ\nفِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ\nكَفَّارٞ\u{a0}٣\u{2}\n       \n          \n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا\nيَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ\u{a0}٤\n\u{2}       \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ\nوَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ\nكُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ\u{a0}٥\n\u{2}       \n      \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}11\u{2}۞ وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ\nنِعۡمَةٗ مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادٗا\nلِّيُضِلَّ عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ\nٱلنَّارِ\u{a0}٨\u{2}          \n           \n         \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ\nٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ\nلَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ\u{a0}٩\u{2}       \n         \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}2\u{2}قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ\u{a0}١٣\n\u{2}        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}فَٱعۡبُدُواْ مَا شِئۡتُم مِّن دُونِهِۦۗ\nقُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَا\nذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ\u{a0}١٥\u{2}    \n         \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}14\u{2}إِنَّكَ مَيِّتٞ وَإِنَّهُم مَّيِّتُونَ\u{a0}٣٠\n\u{2}   \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ\nإِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ\u{a0}٣٢\u{2}       \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَلَيۡسَ ٱللَّهُ بِكَافٍ\nعَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ\nٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ\u{a0}٣٦\u{2}  \n      \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ\nمِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ\nأَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِيَ\nٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ\u{a0}٣٨\u{2}   \n       \n          \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ\nعَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ\u{a0}٣٩\n\u{2}  \n     \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي\nلَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ\nوَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ\nلِّقَوۡمٖ يَتَفَكَّرُونَ\u{a0}٤٢\u{2}     \n        \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ\nقُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ\u{a0}٤٣\n\u{2}     \n       \u{a0}\n\u{1}\u{2}8\u{2}\u{2}قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ\nإِلَيۡهِ تُرۡجَعُونَ\u{a0}٤٤\u{2}        \n \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ\nمَا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ\nيَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ\u{a0}٤٧\n\u{2}   \n          \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قَدۡ قَالَهَا ٱلَّذِينَ مِن قَبۡلِهِمۡ فَمَآ أَغۡنَىٰ\nعَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ\u{a0}٥٠\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْۚ\nوَٱلَّذِينَ ظَلَمُواْ مِنۡ هَٰٓؤُلَآءِ سَيُصِيبُهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ\nوَمَا هُم بِمُعۡجِزِينَ\u{a0}٥١\u{2}   \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ\nلِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ\u{a0}٥٢\n\u{2}     \n        \u{a0}\n\u{1}\u{2}\u{2}10\u{2}۞ قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن\nرَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ\u{a0}٥٣\n\u{2}        \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُواْ لَهُۥ مِن قَبۡلِ أَن يَأۡتِيَكُمُ\nٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ\u{a0}٥٤\u{2}        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱتَّبِعُوٓاْ أَحۡسَنَ مَآ أُنزِلَ\nإِلَيۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ\nبَغۡتَةٗ وَأَنتُمۡ لَا تَشۡعُرُونَ\u{a0}٥٥\u{2}   \n       \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ\u{a0}٥٧\n\u{2}        \u{a0}\n\u{1}\u{2}2\u{2}3\u{2}أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ\nمِنَ ٱلۡمُحۡسِنِينَ\u{a0}٥٨\u{2}         \n \u{a0}\u{1}\u{2}\u{2}\u{2}بَلَىٰ قَدۡ جَآءَتۡكَ ءَايَٰتِي فَكَذَّبۡتَ بِهَا\nوَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَٰفِرِينَ\u{a0}٥٩\u{2}     \n   \u{a0}\u{1}\u{2}\u{2}6\u{2}وَيَوۡمَ ٱلۡقِيَٰمَةِ\nتَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي\nجَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ\u{a0}٦٠\u{2} \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ\nبِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ\u{a0}٦١\u{2}   \n      \u{a0}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ\nخَٰلِقُ كُلِّ شَيۡءٖۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ\u{a0}٦٢\u{2}\n       \u{a0}\u{1}\u{2}\u{2}10\u{2}لَّهُۥ مَقَالِيدُ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ أُوْلَٰٓئِكَ\nهُمُ ٱلۡخَٰسِرُونَ\u{a0}٦٣\u{2} \n      \n \u{a0}\u{1}\u{2}10\u{2}11\u{2}قُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا\nٱلۡجَٰهِلُونَ\u{a0}٦٤\u{2}     \n\u{a0}\u{1}\u{2}11\u{2}\u{2}وَلَقَدۡ أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ\nأَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ\u{a0}٦٥\u{2}       \n     \u{a0}\u{1}\u{2}\u{2}\u{2}بَلِ ٱللَّهَ\nفَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ\u{a0}٦٦\u{2} \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦ\nوَٱلۡأَرۡضُ جَمِيعٗا قَبۡضَتُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ\nمَطۡوِيَّٰتُۢ بِيَمِينِهِۦۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ\u{a0}٦٧\n\u{2}    \n     \n     \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى\nٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ\nخَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ\u{a0}٧٣\n\u{2}    \n        \n     \u{a0}\n\u{1}\u{2}14\u{2}\u{2}وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ\nنَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَيۡثُ نَشَآءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ\u{a0}٧٤\n\u{2}       \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}غَافِرِ\nٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِۖ لَآ إِلَٰهَ إِلَّا هُوَۖ\nإِلَيۡهِ ٱلۡمَصِيرُ\u{a0}٣\u{2}\n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ\nفَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ\u{a0}٤\u{2}       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ\nنُوحٖ وَٱلۡأَحۡزَابُ مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ\nلِيَأۡخُذُوهُۖ وَجَٰدَلُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ\nفَكَيۡفَ كَانَ عِقَابِ\u{a0}٥\u{2}  \n       \n      \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَكَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى\nٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ أَصۡحَٰبُ ٱلنَّارِ\u{a0}٦\u{2}    \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ\nوَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ وَيَسۡتَغۡفِرُونَ\nلِلَّذِينَ ءَامَنُواْۖ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا\nفَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ\u{a0}٧\n\u{2}  \n       \n       \n       \u{a0}\n\u{1}'
    '\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ\nٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ\nأَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ\u{a0}١٠\n\u{2}\n       \n     \u{a0}\n\u{1}\u{2}7\u{2}\u{2}قَالُواْ رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا\nفَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ\u{a0}١١\u{2}       \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ\nٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن يُشۡرَكۡ بِهِۦ تُؤۡمِنُواْۚ فَٱلۡحُكۡمُ لِلَّهِ\nٱلۡعَلِيِّ ٱلۡكَبِيرِ\u{a0}١٢\u{2}   \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِي يُرِيكُمۡ ءَايَٰتِهِۦ وَيُنَزِّلُ\nلَكُم مِّنَ ٱلسَّمَآءِ رِزۡقٗاۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ\u{a0}١٣\n\u{2}    \n        \u{a0}\n\u{1}\u{2}12\u{2}\u{2}فَٱدۡعُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ\u{a0}١٤\n\u{2}       \u{a0}\n\u{1}\u{2}13\u{2}\u{2}رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلۡعَرۡشِ يُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن\nيَشَآءُ مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ\u{a0}١٥\u{2}         \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ\u{a0}١٩\n\u{2}     \u{a0}\n\u{1}\u{2}5\u{2}\u{2}وَٱللَّهُ يَقۡضِي بِٱلۡحَقِّۖ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَقۡضُونَ\nبِشَيۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ\u{a0}٢٠\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}\u{2}۞ أَوَلَمۡ يَسِيرُواْ فِي\nٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡۚ\nكَانُواْ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ\nبِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ\u{a0}٢١\u{2}  \n        \n         \n       \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّهُمۡ\nكَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَكَفَرُواْ فَأَخَذَهُمُ ٱللَّهُۚ إِنَّهُۥ\nقَوِيّٞ شَدِيدُ ٱلۡعِقَابِ\u{a0}٢٢\u{2} \n       \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ\nلَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ\u{a0}٢٧\u{2}        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ\nفِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ\nٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبٗا\nفَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي\nيَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ\u{a0}٢٨\u{2}    \n       \n        \n       \n        \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰقَوۡمِ\nلَكُمُ ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ\nبَأۡسِ ٱللَّهِ إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ\nأَهۡدِيكُمۡ إِلَّا سَبِيلَ ٱلرَّشَادِ\u{a0}٢٩\u{2}\n        \n           \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ\nأَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ\u{a0}٣٠\u{2}    \n    \u{a0}\u{1}\u{2}\u{2}\u{2}مِثۡلَ دَأۡبِ قَوۡمِ نُوحٖ\nوَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعِبَادِ\u{a0}٣١\n\u{2}   \n         \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ\nمِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ\nمِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ\nمُّرۡتَابٌ\u{a0}٣٤\u{2}         \n         \n        \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِيٓ\nءَامَنَ يَٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِيلَ ٱلرَّشَادِ\u{a0}٣٨\n\u{2} \n     \u{a0}\n\u{1}\u{2}12\u{2}\u{2}يَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعٞ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ\nدَارُ ٱلۡقَرَارِ\u{a0}٣٩\u{2}        \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَنۡ عَمِلَ سَيِّئَةٗ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَاۖ\nوَمَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ\nفَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابٖ\u{a0}٤٠\n\u{2}      \n        \n      \u{a0}\n\u{1}\u{2}\u{2}2\u{2}۞ وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى\nٱلنَّارِ\u{a0}٤١\u{2}       \n\u{a0}\u{1}\u{2}\u{2}\u{2}تَدۡعُونَنِي لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَيۡسَ\nلِي بِهِۦ عِلۡمٞ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِيزِ ٱلۡغَفَّٰرِ\u{a0}٤٢\u{2}      \n       \u{a0}\u{1}\u{2}\u{2}\u{2}لَا جَرَمَ\nأَنَّمَا تَدۡعُونَنِيٓ إِلَيۡهِ لَيۡسَ لَهُۥ دَعۡوَةٞ فِي ٱلدُّنۡيَا وَلَا فِي ٱلۡأٓخِرَةِ\nوَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِينَ هُمۡ أَصۡحَٰبُ ٱلنَّارِ\u{a0}٤٣\n\u{2} \n          \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَسَتَذۡكُرُونَ مَآ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِيٓ إِلَى\nٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ\u{a0}٤٤\u{2}      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ\nمَا مَكَرُواْۖ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ\u{a0}٤٥\u{2}  \n      \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلنَّارُ\nيُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ\nءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ\u{a0}٤٦\u{2}\n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ يَتَحَآجُّونَ فِي\nٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا\nلَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبٗا مِّنَ ٱلنَّارِ\u{a0}٤٧\n\u{2}  \n      \n        \u{a0}\n\u{1}\u{2}13\u{2}\u{2}قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلّٞ فِيهَآ إِنَّ ٱللَّهَ\nقَدۡ حَكَمَ بَيۡنَ ٱلۡعِبَادِ\u{a0}٤٨\u{2}       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ\nجَهَنَّمَ ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمٗا مِّنَ ٱلۡعَذَابِ\u{a0}٤٩\n\u{2}    \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالُوٓاْ أَوَلَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ\nبَلَىٰۚ قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ\u{a0}٥٠\n\u{2}      \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ\nٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ\nمَّا هُم بِبَٰلِغِيهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ\nٱلۡبَصِيرُ\u{a0}٥٦\u{2}    \n        \n       \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ\nفِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ\nوَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ\u{a0}٦١\u{2}     \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكُمُ\nٱللَّهُ رَبُّكُمۡ خَٰلِقُ كُلِّ شَيۡءٖ لَّآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ\u{a0}٦٢\n\u{2}\n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارٗا وَٱلسَّمَآءَ\nبِنَآءٗ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ\nٱلطَّيِّبَٰتِۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ\nٱلۡعَٰلَمِينَ\u{a0}٦٤\u{2}      \n     \n      \n\u{a0}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلۡحَيُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدۡعُوهُ\nمُخۡلِصِينَ لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ\u{a0}٦٥\u{2}      \n      \u{a0}\u{1}\u{2}\u{2}\u{2}۞ قُلۡ\nإِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِيَ\nٱلۡبَيِّنَٰتُ مِن رَّبِّي وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ\u{a0}٦٦\n\u{2}\n          \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِي خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ\nيُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ ثُمَّ لِتَكُونُواْ\nشُيُوخٗاۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوٓاْ أَجَلٗا مُّسَمّٗى\nوَلَعَلَّكُمۡ تَعۡقِلُونَ\u{a0}٦٧\u{2}           \n      \n        \n \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}هُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُۖ فَإِذَا\nقَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ\u{a0}٦٨\u{2}    \n      \u{a0}\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ إِلَى ٱلَّذِينَ\nيُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصۡرَفُونَ\u{a0}٦٩\u{2}   \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ كَذَّبُواْ\nبِٱلۡكِتَٰبِ وَبِمَآ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ يَعۡلَمُونَ\u{a0}٧٠\n\u{2} \n      \u{a0}\n\u{1}\u{2}8\u{2}\u{2}إِذِ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ\u{a0}٧١\n\u{2}     \u{a0}\n\u{1}\u{2}9\u{2}\u{2}فِي ٱلۡحَمِيمِ ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ\u{a0}٧٢\u{2}     \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ قِيلَ لَهُمۡ أَيۡنَ\nمَا كُنتُمۡ تُشۡرِكُونَ\u{a0}٧٣\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}\u{2}مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ\nنَكُن نَّدۡعُواْ مِن قَبۡلُ شَيۡـٔٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ\u{a0}٧٤\n\u{2}       \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ\nمَثۡوَى ٱلۡمُتَكَبِّرِينَ\u{a0}٧٦\u{2}     \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۚ فَإِمَّا\nنُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ\u{a0}٧٧\n\u{2}     \n       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَكُمۡ فِيهَا\nمَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى\nٱلۡفُلۡكِ تُحۡمَلُونَ\u{a0}٨٠\u{2} \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَيُرِيكُمۡ ءَايَٰتِهِۦ فَأَيَّ ءَايَٰتِ\nٱللَّهِ تُنكِرُونَ\u{a0}٨١\u{2}   \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم\nمِّنَ ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\u{a0}٨٣\u{2}      \n       \u{a0}\u{1}\u{2}\u{2}\u{2}فَلَمَّا\nرَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ\nمُشۡرِكِينَ\u{a0}٨٤\u{2}\n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}كِتَٰبٞ فُصِّلَتۡ\nءَايَٰتُهُۥ قُرۡءَانًا عَرَبِيّٗا لِّقَوۡمٖ يَعۡلَمُونَ\u{a0}٣\u{2} \n    \u{a0}\u{1}\u{2}\u{2}\u{2}بَشِيرٗا وَنَذِيرٗا فَأَعۡرَضَ\nأَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَعُونَ\u{a0}٤\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}7\u{2}وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ\nمِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ\nفَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ\u{a0}٥\u{2}   \n         \n  \u{a0}\u{1}\u{2}\u{2}9\u{2}قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ\nأَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلٞ\nلِّلۡمُشۡرِكِينَ\u{a0}٦\u{2}      \n       \n\u{a0}\u{1}\u{2}9\u{2}10\u{2}ٱلَّذِينَ لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ\nهُمۡ كَٰفِرُونَ\u{a0}٧\u{2}     \n \u{a0}\u{1}\u{2}10\u{2}11\u{2}إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ\nأَجۡرٌ غَيۡرُ مَمۡنُونٖ\u{a0}٨\u{2}     \n  \u{a0}\u{1}\u{2}11\u{2}\u{2}۞ قُلۡ أَئِنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ\nٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادٗاۚ ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ\u{a0}٩\n\u{2}    \n        \u{a0}\n\u{1}\u{2}13\u{2}\u{2}وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ\nأَرۡبَعَةِ أَيَّامٖ سَوَآءٗ لِّلسَّآئِلِينَ\u{a0}١٠\u{2}          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِيَ دُخَانٞ\nفَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِيَا طَوۡعًا أَوۡ كَرۡهٗا قَالَتَآ أَتَيۡنَا طَآئِعِينَ\u{a0}١١\n\u{2}     \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}فَإِنۡ أَعۡرَضُواْ فَقُلۡ أَنذَرۡتُكُمۡ صَٰعِقَةٗ مِّثۡلَ صَٰعِقَةِ\nعَادٖ وَثَمُودَ\u{a0}١٣\u{2}      \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ يُحۡشَرُ\nأَعۡدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ\u{a0}١٩\u{2} \n     \u{a0}\u{1}\u{2}\u{2}\u{2}حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ\nعَلَيۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ\u{a0}٢٠\n\u{2}    \n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَإِن يَصۡبِرُواْ فَٱلنَّارُ مَثۡوٗى لَّهُمۡۖ وَإِن\nيَسۡتَعۡتِبُواْ فَمَا هُم مِّنَ ٱلۡمُعۡتَبِينَ\u{a0}٢٤\u{2}     \n    \u{a0}\u{1}\u{2}\u{2}10\u{2}۞ وَقَيَّضۡنَا لَهُمۡ\nقُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَيۡهِمُ\nٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ\nكَانُواْ خَٰسِرِينَ\u{a0}٢٥\u{2} \n         \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ\nوَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ\u{a0}٢٦\u{2}      \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُواْ عَذَابٗا\nشَدِيدٗا وَلَنَجۡزِيَنَّهُمۡ أَسۡوَأَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ\u{a0}٢٧\u{2}   \n     \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ جَزَآءُ\nأَعۡدَآءِ ٱللَّهِ ٱلنَّارُۖ لَهُمۡ فِيهَا دَارُ ٱلۡخُلۡدِ جَزَآءَۢ بِمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ\u{a0}٢٨\n\u{2} \n           \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}نَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ\nٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَلَكُمۡ فِيهَا مَا تَشۡتَهِيٓ أَنفُسُكُمۡ\nوَلَكُمۡ فِيهَا مَا تَدَّعُونَ\u{a0}٣١\u{2}   \n       \n   \u{a0}\u{1}\u{2}\u{2}\u{2}نُزُلٗا مِّنۡ غَفُورٖ رَّحِيمٖ\u{a0}٣٢\n\u{2}   \u{a0}\n\u{1}\u{2}6\u{2}\u{2}وَمَنۡ أَحۡسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ\nإِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ\u{a0}٣٣\u{2}         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ\nٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ\nوَلِيٌّ حَمِيمٞ\u{a0}٣٤\u{2}    \n         \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}وَلَوۡ جَعَلۡنَٰهُ قُرۡءَانًا أَعۡجَمِيّٗا لَّقَالُواْ لَوۡلَا فُصِّلَتۡ ءَايَٰتُهُۥٓۖ ءَا۬عۡجَمِيّٞ\nوَعَرَبِيّٞۗ قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ وَٱلَّذِينَ\nلَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرٞ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَٰٓئِكَ\nيُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدٖ\u{a0}٤٤\u{2}        \n       \n        \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ إِلَيۡهِ يُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَٰتٖ مِّنۡ أَكۡمَامِهَا\nوَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَيَوۡمَ يُنَادِيهِمۡ أَيۡنَ\nشُرَكَآءِي قَالُوٓاْ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٖ\u{a0}٤٧\u{2}         \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}وَضَلَّ\nعَنۡهُم مَّا كَانُواْ يَدۡعُونَ مِن قَبۡلُۖ وَظَنُّواْ مَا لَهُم مِّن مَّحِيصٖ\u{a0}٤٨\n\u{2}\n          \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}10\u{2}وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ\nأَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٖ\u{a0}٥١\n\u{2}   \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم\nبِهِۦ مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِي شِقَاقِۭ بَعِيدٖ\u{a0}٥٢\u{2}        \n       \u{a0}\u{1}\u{2}\u{2}\u{2}سَنُرِيهِمۡ\nءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ\nأَوَلَمۡ يَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ\u{a0}٥٣\u{2}\n         \n       \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ\nٱلۡعَلِيُّ ٱلۡعَظِيمُ\u{a0}٤\u{2}       \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُدۡخِلُ\nمَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِيّٖ وَلَا نَصِيرٍ\u{a0}٨\n\u{2}       \n          \u{a0}\n\u{1}\u{2}13\u{2}\u{2}أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِيُّ وَهُوَ يُحۡيِ ٱلۡمَوۡتَىٰ وَهُوَ\nعَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٩\u{2}           \n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا\nوَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجٗا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ\nوَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ\u{a0}١١\u{2}       \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nيَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَيۡءٍ عَلِيمٞ\u{a0}١٢\n\u{2}   \n        \u{a0}\n\u{1}\u{2}5\u{2}\u{2}۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ\nإِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ\nوَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ\nيَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ\u{a0}١٣\u{2}         \n         \n         \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَا\nتَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ وَلَوۡلَا كَلِمَةٞ\nسَبَقَتۡ مِن رَّبِّكَ إِلَىٰٓ أَجَلٖ مُّسَمّٗى لَّقُضِيَ بَيۡنَهُمۡۚ وَإِنَّ ٱلَّذِينَ\nأُورِثُواْ ٱلۡكِتَٰبَ مِنۢ بَعۡدِهِمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ\u{a0}١٤\n\u{2}\n          \n         \n       \u{a0}\n\u{1}\u{2}12\u{2}\u{2}فَلِذَٰلِكَ فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَآ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ\nوَقُلۡ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٖۖ وَأُمِرۡتُ لِأَعۡدِلَ\nبَيۡنَكُمُۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡۖ\nلَا حُجَّةَ بَيۡنَنَا وَبَيۡنَكُمُۖ ٱللَّهُ يَجۡمَعُ بَيۡنَنَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ\u{a0}١٥\n\u{2}       \n        \n       \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ وَمَن\nكَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِن\nنَّصِيبٍ\u{a0}٢٠\u{2}         \n          \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}تَرَى ٱلظَّٰلِمِينَ\nمُشۡفِقِينَ مِمَّا كَسَبُواْ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِينَ\nءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ\nلَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ\u{a0}٢٢\n\u{2} \n      \n     \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۗ قُل لَّآ\nأَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِي ٱلۡقُرۡبَىٰۗ وَمَن يَقۡتَرِفۡ حَسَنَةٗ نَّزِدۡ\nلَهُۥ فِيهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورٞ شَكُورٌ\u{a0}٢٣\u{2}          \n          \n      \u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ يَقُولُونَ ٱفۡتَرَىٰ عَلَى ٱللَّهِ\nكَذِبٗاۖ فَإِن يَشَإِ ٱللَّهُ يَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَيَمۡحُ ٱللَّهُ ٱلۡبَٰطِلَ وَيُحِقُّ ٱلۡحَقَّ\nبِكَلِمَٰتِهِۦٓۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\u{a0}٢٤\u{2}    \n           \n    \u{a0}\u{1}\u{2}5\u{2}6\u{2}وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ\nعَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ\u{a0}٢٥\n\u{2}   \n       \u{a0}\n\u{1}\u{2}\u{2}8\u{2}وَيَسۡتَجِيبُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضۡلِهِۦۚ\nوَٱلۡكَٰفِرُونَ لَهُمۡ عَذَابٞ شَدِيدٞ\u{a0}٢٦\u{2}       \n   \u{a0}\u{1}\u{2}8\u{2}\u{2}۞ وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ\nلِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ\nخَبِيرُۢ بَصِيرٞ\u{a0}٢٧\u{2}   \n          \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ\nوَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ\u{a0}٢٨\u{2}       \n    \u{a0}\u{1}\u{2}11\u{2}\u{2}وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٖۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ\nإِذَا يَشَآءُ قَدِيرٞ\u{a0}٢٩\u{2}  \n         \n  \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ\nيَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَٰٓئِكَ لَهُمۡ\nعَذَابٌ أَلِيمٞ\u{a0}٤٢\u{2}   \n        \n \u{a0}\u{1}\u{2}\u{2}13\u{2}وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ\u{a0}٤٣\n\u{2}       \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِيّٖ مِّنۢ بَعۡدِهِۦۗ وَتَرَى ٱلظَّٰلِمِينَ\nلَمَّا رَأَوُاْ ٱلۡعَذَابَ يَقُولُونَ هَلۡ إِلَىٰ مَرَدّٖ مِّن سَبِيلٖ\u{a0}٤٤\n\u{2}          \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{2}\u{2}\u{2}۞ وَمَا كَانَ\nلِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡيًا أَوۡ مِن وَرَآيِٕ حِجَابٍ أَوۡ يُرۡسِلَ\nرَسُولٗا فَيُوحِيَ بِإِذۡنِهِۦ مَا يَشَآءُۚ إِنَّهُۥ عَلِيٌّ حَكِيمٞ\u{a0}٥١\n\u{2} \n           \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}بَلۡ قَالُوٓاْ\nإِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهۡتَدُونَ\u{a0}٢٢\n\u{2} \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ قَٰلَ أَوَلَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَيۡهِ ءَابَآءَكُمۡۖ قَالُوٓاْ\nإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ\u{a0}٢٤\u{2}        \n    \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ\nإِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ\u{a0}٢٦\u{2}    \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفَأَنتَ تُسۡمِعُ\nٱلصُّمَّ أَوۡ تَهۡدِي ٱلۡعُمۡيَ وَمَن كَانَ فِي ضَلَٰلٖ مُّبِينٖ\u{a0}٤٠\n\u{2} \n        \u{a0}\n\u{1}\u{2}9\u{2}\u{2}فَإِمَّا نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ\u{a0}٤١\u{2}     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ أَرۡسَلۡنَا\nمُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ\nرَبِّ ٱلۡعَٰلَمِينَ\u{a0}٤٦\u{2} \n       \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا كَشَفۡنَا عَنۡهُمُ\nٱلۡعَذَابَ إِذَا هُمۡ يَنكُثُونَ\u{a0}٥٠\u{2}  \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}۞ وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡيَمَ\nمَثَلًا إِذَا قَوۡمُكَ مِنۡهُ يَصِدُّونَ\u{a0}٥٧\u{2}   \n    \u{a0}\u{1}\u{2}\u{2}\u{2}وَقَالُوٓاْ ءَأَٰلِهَتُنَا\nخَيۡرٌ أَمۡ هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ\u{a0}٥٨\n\u{2} \n           \u{a0}\n\u{1}\u{2}14\u{2}\u{2}إِنۡ هُوَ إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَيۡهِ وَجَعَلۡنَٰهُ مَثَلٗا لِّبَنِيٓ إِسۡرَٰٓءِيلَ\u{a0}٥٩\n\u{2}         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ\nمُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ\u{a0}٣\u{2}   \n   \u{a0}\u{1}\u{2}\u{2}\u{2}فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ\u{a0}٤\n\u{2}    \u{a0}\n\u{1}\u{2}5\u{2}\u{2}أَمۡرٗا مِّنۡ عِندِنَآۚ إِنَّا كُنَّا مُرۡسِلِينَ\u{a0}٥\u{2}     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَغۡشَى\nٱلنَّاسَۖ هَٰذَا عَذَابٌ أَلِيمٞ\u{a0}١١\u{2}\n   \u{a0}\u{1}\u{2}\u{2}11\u{2}رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ\nإِنَّا مُؤۡمِنُونَ\u{a0}١٢\u{2}   \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَآءَهُمۡ رَسُولٞ مُّبِينٞ\u{a0}١٣\n\u{2}      \u{a0}\n\u{1}\u{2}12\u{2}\u{2}ثُمَّ تَوَلَّوۡاْ عَنۡهُ وَقَالُواْ مُعَلَّمٞ مَّجۡنُونٌ\u{a0}١٤\u{2}     \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّا كَاشِفُواْ ٱلۡعَذَابِ قَلِيلًاۚ\nإِنَّكُمۡ عَآئِدُونَ\u{a0}١٥\u{2}   \n \u{a0}\u{1}\u{1}\u{2}\u{2}15\u{2}۞ وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولٞ\nكَرِيمٌ\u{a0}١٧\u{2}      \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ\u{a0}٢١\u{2}    \u{a0}\u{1}\u{2}2\u{2}\u{2}فَدَعَا\nرَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوۡمٞ مُّجۡرِمُونَ\u{a0}٢٢\u{2}\n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا قَوۡمًا ءَاخَرِينَ\u{a0}٢٨\n\u{2}   \u{a0}\n\u{1}\u{2}7\u{2}\u{2}فَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ\u{a0}٢٩\u{2}       \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنۡ هِيَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا\nنَحۡنُ بِمُنشَرِينَ\u{a0}٣٥\u{2}     \n \u{a0}\u{1}\u{1}\u{2}\u{2}13\u{2}أَهُمۡ\nخَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ\u{a0}٣٧\n\u{2}\n          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَوۡمَ لَا يُغۡنِي مَوۡلًى\nعَن مَّوۡلٗى شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ\u{a0}٤١\u{2}   \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ\u{a0}٤٥\u{2}   \u{a0}\u{1}\u{2}4\u{2}\u{2}كَغَلۡيِ\nٱلۡحَمِيمِ\u{a0}٤٦\u{2}\n\u{a0}\u{1}\u{2}\u{2}5\u{2}خُذُوهُ فَٱعۡتِلُوهُ إِلَىٰ سَوَآءِ ٱلۡجَحِيمِ\u{a0}٤٧\u{2}    \u{a0}\u{1}\u{2}5\u{2}6\u{2}ثُمَّ\nصُبُّواْ فَوۡقَ رَأۡسِهِۦ مِنۡ عَذَابِ ٱلۡحَمِيمِ\u{a0}٤٨\u{2}\n     \u{a0}\u{1}\u{2}6\u{2}\u{2}ذُقۡ إِنَّكَ\nأَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ\u{a0}٤٩\u{2} \n  \u{a0}\u{1}\u{2}7\u{2}7\u{2}إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمۡتَرُونَ\u{a0}٥٠\n\u{2}     \u{a0}\n\u{1}\u{2}\u{2}8\u{2}إِنَّ ٱلۡمُتَّقِينَ فِي مَقَامٍ أَمِينٖ\u{a0}٥١\u{2}    \u{a0}\u{1}\u{2}8\u{2}8\u{2}فِي جَنَّٰتٖ وَعُيُونٖ\u{a0}٥٢\n\u{2}  \u{a0}\n\u{1}\u{2}\u{2}9\u{2}يَلۡبَسُونَ مِن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَقَٰبِلِينَ\u{a0}٥٣\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}10\u{2}كَذَٰلِكَ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ\u{a0}٥٤\u{2}   \u{a0}\u{1}\u{2}10\u{2}11\u{1}\u{2}11\u{2}12\u{2}لَا يَذُوقُونَ فِيهَا ٱلۡمَوۡتَ\nإِلَّا ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِيمِ\u{a0}٥٦\u{2}   \n     \u{a0}\u{1}\u{2}12\u{2}13\u{2}فَضۡلٗا\nمِّن رَّبِّكَۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}٥٧\u{2}\n     \u{a0}\u{1}\u{2}13\u{2}14\u{1}\u{2}14\u{2}14\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}3\u{1}\u{2}3\u{2}4\u{2}وَفِي خَلۡقِكُمۡ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٞ\nلِّقَوۡمٖ يُوقِنُونَ\u{a0}٤\u{2}      \n \u{a0}\u{1}\u{2}4\u{2}\u{2}وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ\nمِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ ٱلرِّيَٰحِ ءَايَٰتٞ لِّقَوۡمٖ\nيَعۡقِلُونَ\u{a0}٥\u{2}       \n          \n\u{a0}\u{1}\u{2}6\u{2}7\u{2}تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَ\nٱللَّهِ وَءَايَٰتِهِۦ يُؤۡمِنُونَ\u{a0}٦\u{2}        \n  \u{a0}\u{1}\u{2}7\u{2}7\u{1}\u{2}7\u{2}8\u{2}يَسۡمَعُ ءَايَٰتِ\nٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ يُصِرُّ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٖ\u{a0}٨\n\u{2} \n           \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا عَلِمَ مِنۡ ءَايَٰتِنَا شَيۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ\nمُّهِينٞ\u{a0}٩\u{2}         \n\u{a0}\u{1}\u{2}\u{2}11\u{2}مِّن وَرَآئِهِمۡ جَهَنَّمُۖ وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـٔٗا\nوَلَا مَا ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ\u{a0}١٠\u{2}        \n         \u{a0}\u{1}\u{2}11\u{2}12\u{2}هَٰذَا\nهُدٗىۖ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَهُمۡ عَذَابٞ مِّن رِّجۡزٍ أَلِيمٌ\u{a0}١١\n\u{2}\n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ ٱللَّهُ ٱلَّذِي سَخَّرَ لَكُمُ ٱلۡبَحۡرَ لِتَجۡرِيَ ٱلۡفُلۡكُ فِيهِ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن\nفَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ\u{a0}١٢\u{2}          \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَسَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي\nٱلۡأَرۡضِ جَمِيعٗا مِّنۡهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ\u{a0}١٣\n\u{2}      \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَءَاتَيۡنَٰهُم بَيِّنَٰتٖ مِّنَ ٱلۡأَمۡرِۖ\nفَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ إِنَّ\nرَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ\u{a0}١٧\n\u{2}   \n          \n        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلِ ٱللَّهُ يُحۡيِيكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يَجۡمَعُكُمۡ إِلَىٰ يَوۡمِ\nٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ\u{a0}٢٦\u{2}        \n        \u{a0}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱلسَّاعَةُ لَا رَيۡبَ فِيهَا قُلۡتُم\nمَّا نَدۡرِي مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنّٗا وَمَا نَحۡنُ بِمُسۡتَيۡقِنِينَ\u{a0}٣٢\n\u{2}          \n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}وَقِيلَ ٱلۡيَوۡمَ نَنسَىٰكُمۡ كَمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا\nلَكُم مِّن نَّٰصِرِينَ\u{a0}٣٤\u{2}          \n  \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذۡتُمۡ ءَايَٰتِ ٱللَّهِ هُزُوٗا وَغَرَّتۡكُمُ\nٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ لَا يُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ يُسۡتَعۡتَبُونَ\u{a0}٣٥\n\u{2}      \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ\u{a0}٣٦\u{2}       \u{a0}\u{1}\u{2}5\u{2}\u{2}وَلَهُ\nٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٣٧\n\u{2}\n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَرَءَيۡتُم مَّا تَدۡعُونَ مِن\nدُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِۖ\nٱئۡتُونِي بِكِتَٰبٖ مِّن قَبۡلِ هَٰذَآ أَوۡ أَثَٰرَةٖ مِّنۡ عِلۡمٍ إِن كُنتُمۡ\nصَٰدِقِينَ\u{a0}٤\u{2}    \n           \n          \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ\nكُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ\nأَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ\nعَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي\nذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ\u{a0}١٥\u{2}       \n         \n         \n         \n      \u{a0}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ\nنَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُواْ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمۡ فِيٓ أَصۡحَٰبِ\nٱلۡجَنَّةِۖ وَعۡدَ ٱلصِّدۡقِ ٱلَّذِي كَانُواْ يُوعَدُونَ\u{a0}١٦\u{2} \n         \n     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ\nٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ\nخَٰسِرِينَ\u{a0}١٨\u{2}   \n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۖ وَلِيُوَفِّيَهُمۡ أَعۡمَٰلَهُمۡ وَهُمۡ\nلَا يُظۡلَمُونَ\u{a0}١٩\u{2}      \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ\nفِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا فَٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ\nبِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ\u{a0}٢٠\n\u{2}       \n        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ\nمِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ\nعَذَابَ يَوۡمٍ عَظِيمٖ\u{a0}٢١\u{2}         \n           \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ\nوَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ\u{a0}٢٣\n\u{2}    \n       \u{a0}\n\u{1}\u{2}6\u{2}\u{2}فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ\nبَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ\u{a0}٢٤\u{2}        \n        \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ مَكَّنَّٰهُمۡ فِيمَآ إِن مَّكَّنَّٰكُمۡ فِيهِ\nوَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ\nوَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ\nبِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\u{a0}٢٦\u{2}     \n        \n        \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَلَقَدۡ\nأَهۡلَكۡنَا مَا حَوۡلَكُم مِّنَ ٱلۡقُرَىٰ وَصَرَّفۡنَا ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَرۡجِعُونَ\u{a0}٢٧\n\u{2}\n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}2\u{2}وَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرٗا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا\nحَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ\u{a0}٢٩\n\u{2}        \n        \u{a0}\n\u{1}\u{2}\u{2}4\u{2}قَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ\nمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقٖ مُّسۡتَقِيمٖ\u{a0}٣٠\n\u{2}        \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ يَغۡفِرۡ لَكُم مِّن\nذُنُوبِكُمۡ وَيُجِرۡكُم مِّنۡ عَذَابٍ أَلِيمٖ\u{a0}٣١\u{2}        \n    \u{a0}\u{1}\u{2}6\u{2}\u{2}وَمَن لَّا يُجِبۡ دَاعِيَ ٱللَّهِ\nفَلَيۡسَ بِمُعۡجِزٖ فِي ٱلۡأَرۡضِ وَلَيۡسَ لَهُۥ مِن دُونِهِۦٓ أَوۡلِيَآءُۚ أُوْلَٰٓئِكَ\nفِي ضَلَٰلٖ مُّبِينٍ\u{a0}٣٢\u{2}    \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضَ وَلَمۡ يَعۡيَ بِخَلۡقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰۚ بَلَىٰٓۚ\nإِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ\u{a0}٣٣\u{2}      \n         \n    \u{a0}\u{1}\u{2}10\u{2}\u{2}وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ\nأَلَيۡسَ هَٰذَا بِٱلۡحَقِّۖ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا\nكُنتُمۡ تَكۡفُرُونَ\u{a0}٣٤\u{2}     \n         \n \u{a0}\u{1}\u{2}12\u{2}14\u{2}فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ\nوَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا\nسَاعَةٗ مِّن نَّهَارِۭۚ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ\u{a0}٣٥\n\u{2}      \n          \n        \u{a0}\n\u{1}\u{2}2\u{2}2\u{1}\u{2}2\u{2}4\u{2}وَٱلَّذِينَ\nءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَءَامَنُواْ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٖ وَهُوَ ٱلۡحَقُّ مِن\nرَّبِّهِمۡ كَفَّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ\u{a0}٢\u{2}\n          \n     \u{a0}\u{1}\u{2}4\u{2}\u{2}ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُواْ\nٱتَّبَعُواْ ٱلۡبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُواْ ٱتَّبَعُواْ ٱلۡحَقَّ مِن رَّبِّهِمۡۚ كَذَٰلِكَ يَضۡرِبُ\nٱللَّهُ لِلنَّاسِ أَمۡثَٰلَهُمۡ\u{a0}٣\u{2}   \n          \n  \u{a0}\u{1}\u{2}6\u{2}9\u{2}فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰٓ\nإِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ\nأَوۡزَارَهَاۚ ذَٰلِكَۖ وَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم\nبِبَعۡضٖۗ وَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعۡمَٰلَهُمۡ\u{a0}٤\u{2}      \n           \n         \n        \u{a0}\u{1}\u{2}9\u{2}\u{2}سَيَهۡدِيهِمۡ\nوَيُصۡلِحُ بَالَهُمۡ\u{a0}٥\u{2}\n \u{a0}\u{1}\u{2}\u{2}\u{2}وَيُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ\u{a0}٦\u{2}   \u{a0}\u{1}\u{2}10\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ\u{a0}٧\u{2} \n      \u{a0}\u{1}\u{2}11\u{2}\u{2}وَٱلَّذِينَ كَفَرُواْ\nفَتَعۡسٗا لَّهُمۡ وَأَضَلَّ أَعۡمَٰلَهُمۡ\u{a0}٨\u{2} \n   \u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّهُمۡ كَرِهُواْ مَآ أَنزَلَ ٱللَّهُ\nفَأَحۡبَطَ أَعۡمَٰلَهُمۡ\u{a0}٩\u{2}     \n \u{a0}\u{1}\u{2}\u{2}\u{2}۞ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ\nكَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَيۡهِمۡۖ وَلِلۡكَٰفِرِينَ أَمۡثَٰلُهَا\u{a0}١٠\n\u{2}     \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ\nمِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم\u{a0}١٤\u{2}   \n        \u{a0}\u{1}\u{2}\u{2}\u{2}مَّثَلُ ٱلۡجَنَّةِ\nٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ فِيهَآ أَنۡهَٰرٞ مِّن مَّآءٍ غَيۡرِ ءَاسِنٖ وَأَنۡهَٰرٞ مِّن لَّبَنٖ لَّمۡ\nيَتَغَيَّرۡ طَعۡمُهُۥ وَأَنۡهَٰرٞ مِّنۡ خَمۡرٖ لَّذَّةٖ لِّلشَّٰرِبِينَ وَأَنۡهَٰرٞ مِّنۡ عَسَلٖ مُّصَفّٗىۖ\nوَلَهُمۡ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغۡفِرَةٞ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَٰلِدٞ فِي ٱلنَّارِ\nوَسُقُواْ مَآءً حَمِيمٗا فَقَطَّعَ أَمۡعَآءَهُمۡ\u{a0}١٥\u{2} \n            \n          \n            \n    \u{a0}\u{1}'
    '\u{2}\u{2}\u{2}وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَ\nحَتَّىٰٓ إِذَا خَرَجُواْ مِنۡ عِندِكَ قَالُواْ لِلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مَاذَا قَالَ ءَانِفًاۚ\nأُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡ\u{a0}١٦\u{2}   \n           \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ\nٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ\u{a0}١٧\u{2}\n    \u{a0}\u{1}\u{2}\u{2}\u{2}فَهَلۡ يَنظُرُونَ إِلَّا\nٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗۖ فَقَدۡ جَآءَ أَشۡرَاطُهَاۚ فَأَنَّىٰ لَهُمۡ إِذَا جَآءَتۡهُمۡ\nذِكۡرَىٰهُمۡ\u{a0}١٨\u{2}  \n          \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ\nفَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ\u{a0}٢٣\u{2}   \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لِلَّذِينَ كَرِهُواْ مَا نَزَّلَ\nٱللَّهُ سَنُطِيعُكُمۡ فِي بَعۡضِ ٱلۡأَمۡرِۖ وَٱللَّهُ يَعۡلَمُ إِسۡرَارَهُمۡ\u{a0}٢٦\n\u{2}      \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}5\u{2}إِنَّ ٱلَّذِينَ\nكَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ وَشَآقُّواْ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ\nلَهُمُ ٱلۡهُدَىٰ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗا وَسَيُحۡبِطُ أَعۡمَٰلَهُمۡ\u{a0}٣٢\n\u{2} \n          \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَلَا تُبۡطِلُوٓاْ\nأَعۡمَٰلَكُمۡ\u{a0}٣٣\u{2}        \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُواْ\nوَهُمۡ كُفَّارٞ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡ\u{a0}٣٤\u{2}        \n     \u{a0}\u{1}\u{2}\u{2}9\u{2}فَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ\nوَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ وَلَن يَتِرَكُمۡ أَعۡمَٰلَكُمۡ\u{a0}٣٥\u{2}    \n      \u{a0}\u{1}\u{2}9\u{2}\u{2}إِنَّمَا\nٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ\nوَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ\u{a0}٣٦\u{2}\n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}إِن يَسۡـَٔلۡكُمُوهَا فَيُحۡفِكُمۡ\nتَبۡخَلُواْ وَيُخۡرِجۡ أَضۡغَٰنَكُمۡ\u{a0}٣٧\u{2}  \n  \u{a0}\u{1}\u{2}\u{2}\u{2}هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ تُدۡعَوۡنَ\nلِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ\nفَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن\nتَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم\u{a0}٣٨\n\u{2}  \n        \n        \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّآ أَرۡسَلۡنَٰكَ\nشَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا\u{a0}٨\u{2} \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوۡقَ أَيۡدِيهِمۡۚ\nفَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَٰهَدَ عَلَيۡهُ\nٱللَّهَ فَسَيُؤۡتِيهِ أَجۡرًا عَظِيمٗا\u{a0}١٠\u{2}         \n          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}سَيَقُولُ لَكَ ٱلۡمُخَلَّفُونَ\nمِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَآ أَمۡوَٰلُنَا وَأَهۡلُونَا فَٱسۡتَغۡفِرۡ لَنَاۚ يَقُولُونَ\nبِأَلۡسِنَتِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ قُلۡ فَمَن يَمۡلِكُ لَكُم مِّنَ ٱللَّهِ\nشَيۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ\nخَبِيرَۢا\u{a0}١١\u{2}  \n       \n          \n             \n\u{a0}\u{1}\u{2}\u{2}\u{2}بَلۡ ظَنَنتُمۡ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰٓ\nأَهۡلِيهِمۡ أَبَدٗا وَزُيِّنَ ذَٰلِكَ فِي قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ\nوَكُنتُمۡ قَوۡمَۢا بُورٗا\u{a0}١٢\u{2}       \n        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَن لَّمۡ يُؤۡمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ\nأَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَعِيرٗا\u{a0}١٣\u{2}     \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ\nيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَكَانَ ٱللَّهُ غَفُورٗا\nرَّحِيمٗا\u{a0}١٤\u{2}   \n        \n\u{a0}\u{1}\u{2}\u{2}\u{2}سَيَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ\nمَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ يُرِيدُونَ أَن يُبَدِّلُواْ\nكَلَٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ\nفَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُواْ لَا يَفۡقَهُونَ إِلَّا قَلِيلٗا\u{a0}١٥\n\u{2}    \n      \n         \n        \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}لَّيۡسَ\nعَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞۗ\nوَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nوَمَن يَتَوَلَّ يُعَذِّبۡهُ عَذَابًا أَلِيمٗا\u{a0}١٧\u{2}\n          \n         \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ\nٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ\nفَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا\u{a0}١٨\u{2}   \n        \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلَوۡ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُواْ\nلَوَلَّوُاْ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا\u{a0}٢٢\u{2}   \n       \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَهُوَ ٱلَّذِي كَفَّ أَيۡدِيَهُمۡ عَنكُمۡ وَأَيۡدِيَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ\nبَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا\u{a0}٢٤\u{2}         \n        \u{a0}\u{1}\u{2}2\u{2}\u{2}هُمُ\nٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡيَ\nمَعۡكُوفًا أَن يَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ\nلَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَيۡرِ عِلۡمٖۖ\nلِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ\nكَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا\u{a0}٢٥\u{2}\n      \n        \n        \n         \n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ\nتَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ سِيمَاهُمۡ\nفِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ\nفِي ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ\nعَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ\nءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمَۢا\u{a0}٢٩\n\u{2}         \n        \n         \n       \n         \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}۞يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ\nإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ\u{a0}١\u{2}          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ\nفَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ\nلِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ\u{a0}٢\u{2}     \n        \n      \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ\nيَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ ٱللَّهُ\nقُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٌ\u{a0}٣\u{2} \n        \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ\nأَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ\u{a0}٦\n\u{2}       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ\nوَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ\nٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ\u{a0}٧\n\u{2}           \n         \n     \u{a0}\n\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ\nوَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن\nيَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ\nرَّحِيمٞ\u{a0}١٢\u{2}          \n        \n         \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}۞ قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن\nقُولُوٓاْ أَسۡلَمۡنَا وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ وَإِن تُطِيعُواْ ٱللَّهَ\nوَرَسُولَهُۥ لَا يَلِتۡكُم مِّنۡ أَعۡمَٰلِكُمۡ شَيۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ\u{a0}١٤\n\u{2}      \n         \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ وَٱللَّهُ\nيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ\u{a0}١٦\n\u{2}    \n          \u{a0}\n\u{1}\u{2}13\u{2}\u{2}يَمُنُّونَ عَلَيۡكَ أَنۡ أَسۡلَمُواْۖ قُل لَّا تَمُنُّواْ عَلَيَّ إِسۡلَٰمَكُمۖ بَلِ ٱللَّهُ\nيَمُنُّ عَلَيۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِيمَٰنِ إِن كُنتُمۡ صَٰدِقِينَ\u{a0}١٧\u{2}          \n       \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱللَّهَ\nيَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}١٨\n\u{2} \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ\u{a0}١٠\n\u{2}    \u{a0}\n\u{1}\u{2}12\u{2}\u{2}رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ\u{a0}١١\u{2}       \u{a0}\u{1}\u{2}\u{2}\u{2}كَذَّبَتۡ\nقَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ\u{a0}١٢\u{2}\n     \u{a0}\u{1}\u{2}\u{2}14\u{2}وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ\nلُوطٖ\u{a0}١٣\u{2}  \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}2\u{2}إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٞ\u{a0}١٧\n\u{2}       \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ\nيَوۡمُ ٱلۡوَعِيدِ\u{a0}٢٠\u{2}   \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}لَّقَدۡ\nكُنتَ فِي غَفۡلَةٖ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدٞ\u{a0}٢٢\n\u{2}\n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}8\u{2}أَلۡقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ\nعَنِيدٖ\u{a0}٢٤\u{2}    \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِي جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا\nءَاخَرَ فَأَلۡقِيَاهُ فِي ٱلۡعَذَابِ ٱلشَّدِيدِ\u{a0}٢٦\u{2}    \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطۡغَيۡتُهُۥ\nوَلَٰكِن كَانَ فِي ضَلَٰلِۭ بَعِيدٖ\u{a0}٢٧\u{2}    \n    \u{a0}\u{1}\u{2}\u{2}\u{2}قَالَ لَا تَخۡتَصِمُواْ لَدَيَّ وَقَدۡ قَدَّمۡتُ\nإِلَيۡكُم بِٱلۡوَعِيدِ\u{a0}٢٨\u{2}     \n \u{a0}\u{1}\u{2}\u{2}\u{2}مَا يُبَدَّلُ ٱلۡقَوۡلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّٰمٖ لِّلۡعَبِيدِ\u{a0}٢٩\n\u{2}       \u{a0}\n\u{1}\u{2}12\u{2}\u{2}يَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدٖ\u{a0}٣٠\u{2}        \u{a0}\u{1}\u{2}\u{2}\u{2}وَأُزۡلِفَتِ\nٱلۡجَنَّةُ لِلۡمُتَّقِينَ غَيۡرَ بَعِيدٍ\u{a0}٣١\u{2}\n   \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشٗا فَنَقَّبُواْ فِي\nٱلۡبِلَٰدِ هَلۡ مِن مَّحِيصٍ\u{a0}٣٦\u{2}          \n   \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ\nلَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ\u{a0}٣٧\u{2}     \n      \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}ٱلَّذِينَ هُمۡ فِي غَمۡرَةٖ سَاهُونَ\u{a0}١١\n\u{2}    \u{a0}\n\u{1}\u{2}3\u{2}\u{2}يَسۡـَٔلُونَ أَيَّانَ يَوۡمُ ٱلدِّينِ\u{a0}١٢\u{2}   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}ذُوقُواْ\nفِتۡنَتَكُمۡ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ\u{a0}١٤\u{2}\n     \u{a0}\u{1}\u{2}\u{2}5\u{2}إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ\nوَعُيُونٍ\u{a0}١٥\u{2}   \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ\u{a0}٢٤\n\u{2}     \u{a0}\n\u{1}\u{2}11\u{2}\u{2}إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ\u{a0}٢٥\u{2}        \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}۞ قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ\u{a0}٣١\u{2}    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}1\u{2}كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُواْ سَاحِرٌ أَوۡ مَجۡنُونٌ\u{a0}٥٢\n\u{2}            \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}فَتَوَلَّ عَنۡهُمۡ فَمَآ أَنتَ\nبِمَلُومٖ\u{a0}٥٤\u{2}   \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}6\u{2}فَإِنَّ لِلَّذِينَ ظَلَمُواْ ذَنُوبٗا مِّثۡلَ ذَنُوبِ أَصۡحَٰبِهِمۡ فَلَا يَسۡتَعۡجِلُونِ\u{a0}٥٩\n\u{2}        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا\nبِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءٖۚ كُلُّ ٱمۡرِيِٕۭ بِمَا كَسَبَ\nرَهِينٞ\u{a0}٢١\u{2}     \n           \n\u{a0}\u{1}\u{2}\u{2}\u{2}وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ وَلَحۡمٖ مِّمَّا يَشۡتَهُونَ\u{a0}٢٢\u{2}    \u{a0}\u{1}\u{2}8\u{2}\u{2}يَتَنَٰزَعُونَ\nفِيهَا كَأۡسٗا لَّا لَغۡوٞ فِيهَا وَلَا تَأۡثِيمٞ\u{a0}٢٣\u{2}\n      \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَانٞ\nلَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤٞ مَّكۡنُونٞ\u{a0}٢٤\u{2}  \n   \u{a0}\u{1}\u{2}\u{2}10\u{2}وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ\u{a0}٢٥\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}\u{2}قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ\u{a0}٢٦\u{2}      \u{a0}\u{1}\u{2}11\u{2}\u{2}فَمَنَّ ٱللَّهُ\nعَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ\u{a0}٢٧\u{2} \n   \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّا كُنَّا مِن قَبۡلُ\nنَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ\u{a0}٢٨\u{2}   \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ\nبَل لَّا يُؤۡمِنُونَ\u{a0}٣٣\u{2}  \n  \u{a0}\u{1}\u{2}\u{2}2\u{2}فَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ\u{a0}٣٤\n\u{2}     \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ\u{a0}٣٥\u{2}       \u{a0}\u{1}\u{2}3\u{2}\u{2}أَمۡ خَلَقُواْ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ\u{a0}٣٦\u{2} \n    \u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ عِندَهُمۡ خَزَآئِنُ\nرَبِّكَ أَمۡ هُمُ ٱلۡمُصَۜيۡطِرُونَ\u{a0}٣٧\u{2} 