    '\u{2}8\u{2}8\u{1}\u{2}8\u{2}9\u{2}لَقَدۡ رَأَىٰ\nمِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ\u{a0}١٨\u{2} \n   \u{a0}\u{1}\u{2}9\u{2}9\u{1}\u{2}9\u{2}\u{2}وَمَنَوٰةَ\nٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ\u{a0}٢٠\u{2}\n \u{a0}\u{1}\u{2}10\u{2}10\u{1}\u{2}10\u{2}\u{2}تِلۡكَ إِذٗا قِسۡمَةٞ\nضِيزَىٰٓ\u{a0}٢٢\u{2}  \n\u{a0}\u{1}\u{2}\u{2}\u{2}إِنۡ هِيَ إِلَّآ أَسۡمَآءٞ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ\nٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ\nوَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ\u{a0}٢٣\u{2}        \n          \n    \u{a0}\u{1}\u{2}\u{2}13\u{2}أَمۡ لِلۡإِنسَٰنِ مَا تَمَنَّىٰ\u{a0}٢٤\u{2}   \u{a0}\u{1}\u{2}13\u{2}\u{2}فَلِلَّهِ\nٱلۡأٓخِرَةُ وَٱلۡأُولَىٰ\u{a0}٢٥\u{2}\n \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَكَم مِّن مَّلَكٖ فِي ٱلسَّمَٰوَٰتِ لَا تُغۡنِي\nشَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ\u{a0}٢٦\n\u{2}      \n          \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا\nفِي ٱلۡأَرۡضِ لِيَجۡزِيَ ٱلَّذِينَ أَسَٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ\nبِٱلۡحُسۡنَى\u{a0}٣١\u{2}    \n         \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}14\u{2}وَأَنَّ سَعۡيَهُۥ سَوۡفَ\nيُرَىٰ\u{a0}٤٠\u{2}  \n\u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ\u{a0}٤٦\u{2}   \u{a0}\u{1}\u{2}1\u{2}\u{2}وَأَنَّ\nعَلَيۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ\u{a0}٤٧\u{2}\n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}وَأَنَّهُۥ هُوَ رَبُّ\nٱلشِّعۡرَىٰ\u{a0}٤٩\u{2}  \n\u{a0}\u{1}\u{1}\u{2}\u{2}3\u{2}وَثَمُودَاْ فَمَآ أَبۡقَىٰ\u{a0}٥١\n\u{2}  \u{a0}\n\u{1}\