    '\u{1}\u{2}\u{2}7\u{2}أَفَرَءَيۡتُم مَّا تَحۡرُثُونَ\u{a0}٦٣\n\u{2}  \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}9\u{2}بَلۡ نَحۡنُ مَحۡرُومُونَ\u{a0}٦٧\n\u{2}  \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ\nأَمۡ نَحۡنُ ٱلۡمُنزِلُونَ\u{a0}٦٩\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}11\u{2}لَوۡ نَشَآءُ جَعَلۡنَٰهُ أُجَاجٗا فَلَوۡلَا تَشۡكُرُونَ\u{a0}٧٠\n\u{2}     \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}ءَأَنتُمۡ أَنشَأۡتُمۡ شَجَرَتَهَآ أَمۡ\nنَحۡنُ ٱلۡمُنشِـُٔونَ\u{a0}٧٢\u{2}   \n \u{a0}\u{1}\u{2}\u{2}13\u{2}نَحۡنُ جَعَلۡنَٰهَا تَذۡكِرَةٗ وَمَتَٰعٗا لِّلۡمُقۡوِينَ\u{a0}٧٣\n\u{2}    \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ فَلَآ أُقۡسِمُ\nبِمَوَٰقِعِ ٱلنُّجُومِ\u{a0}٧٥\u{2} \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لَهُۥ مُلۡكُ\nٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ\u{a0}٢\n\u{2} \n        \u{a0}\n\u{1}\u{2}15\u{2}\u{2}هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ\u{a0}٣\n\u{2}        \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۖ\nبُشۡرَىٰكُمُ ٱلۡيَوۡمَ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ\nهُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}١٢\u{2}        \n         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}يَوۡمَ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ لِلَّذِينَ\nءَامَنُواْ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِيلَ ٱرۡجِعُواْ وَرَآءَكُمۡ فَٱلۡتَمِسُواْ نُورٗاۖ\nفَضُرِبَ بَيۡنَهُم بِسُورٖ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ٱلرَّحۡمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ\nٱلۡعَذَابُ\u{a0}١٣\u{2}    \n         \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}يُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُواْ بَلَىٰ وَلَٰكِنَّكُمۡ فَتَنتُمۡ\nأَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِيُّ حَتَّىٰ جَآءَ أَمۡرُ\nٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ\u{a0}١٤\u{2}       \n       \n   \u{a0}\u{1}\u{2}\u{2}9\u{2}فَٱلۡيَوۡمَ لَا يُؤۡخَذُ مِنكُمۡ فِدۡيَةٞ وَلَا\nمِنَ ٱلَّذِينَ كَفَرُواْۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِيَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِيرُ\u{a0}١٥\n\u{2}     \n        \u{a0}\n\u{1}\u{2}\u{2}12\u{2}۞ أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ\nوَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ\nفَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ\u{a0}١٦\n\u{2}        \n          \n       \u{a0}\n\u{1}\u{2}\u{2}\u{2}ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِ\nلَعَلَّكُمۡ تَعۡقِلُونَ\u{a0}١٧\u{2}          \n \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلۡمُصَّدِّقِينَ وَٱلۡمُصَّدِّقَٰتِ وَأَقۡرَضُواْ\nٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرٞ كَرِيمٞ\u{a0}١٨\n\u{2}   \n       \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مَآ أَصَابَ\nمِن مُّصِيبَةٖ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبٖ\nمِّن قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ\u{a0}٢٢\u{2} \n         \n        \u{a0}\u{1}\u{1}\u{1}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}ثُمَّ قَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم\nبِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى ٱبۡنِ مَرۡيَمَ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَۖ\nوَجَعَلۡنَا فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةٗ وَرَحۡمَةٗۚ وَرَهۡبَانِيَّةً\nٱبۡتَدَعُوهَا مَا كَتَبۡنَٰهَا عَلَيۡهِمۡ إِلَّا ٱبۡتِغَآءَ رِضۡوَٰنِ ٱللَّهِ فَمَا\nرَعَوۡهَا حَقَّ رِعَايَتِهَاۖ فَـَٔاتَيۡنَا ٱلَّذِينَ ءَامَنُواْ مِنۡهُمۡ أَجۡرَهُمۡۖ\nوَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ\u{a0}٢٧\u{2}   \n      \n       \n        \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ\nوَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ وَيَجۡعَل لَّكُمۡ\nنُورٗا تَمۡشُونَ بِهِۦ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ\u{a0}٢٨\u{2}    \n       \n       \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ\nكَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۭ بَيِّنَٰتٖۚ وَلِلۡكَٰفِرِينَ\nعَذَابٞ مُّهِينٞ\u{a0}٥\u{2}     \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا\nعَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ\u{a0}٦\n\u{2}     \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ\nمِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ\nوَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم\nبِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ\u{a0}٧\u{2}            \n          \n             \n        \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا\nتَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوۡاْ\nبِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ\u{a0}٩\u{2}   \n       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}إِنَّمَا ٱلنَّجۡوَىٰ\nمِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ وَلَيۡسَ بِضَآرِّهِمۡ شَيۡـًٔا\nإِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\u{a0}١٠\u{2} \n       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ\nءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ\nٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ\nمِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ\u{a0}١١\n\u{2} \n        \n         \n        \u{a0}\n\u{1}\u{2}\u{2}2\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيۡتُمُ ٱلرَّسُولَ فَقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ\nصَدَقَةٗۚ ذَٰلِكَ خَيۡرٞ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ\u{a0}١٢\n\u{2}         \n           \u{a0}\n\u{1}\u{2}\u{2}\u{2}ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَٰتٖۚ فَإِذۡ لَمۡ تَفۡعَلُواْ\nوَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱللَّهَ\nوَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}١٣\u{2}         \n        \n    \u{a0}\u{1}\u{2}\u{2}\u{2}۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا\nغَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى ٱلۡكَذِبِ\nوَهُمۡ يَعۡلَمُونَ\u{a0}١٤\u{2}     \n          \n \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَوۡمَ يَبۡعَثُهُمُ\nٱللَّهُ جَمِيعٗا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ\nإِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ\u{a0}١٨\u{2} \n           \n  \u{a0}\u{1}\u{2}\u{2}13\u{2}ٱسۡتَحۡوَذَ عَلَيۡهِمُ ٱلشَّيۡطَٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ\nٱللَّهِۚ أُوْلَٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ أَلَآ إِنَّ حِزۡبَ ٱلشَّيۡطَٰنِ هُمُ ٱلۡخَٰسِرُونَ\u{a0}١٩\n\u{2}    \n         \u{a0}\n\u{1}\u{2}\u{2}14\u{2}إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِي ٱلۡأَذَلِّينَ\u{a0}٢٠\n\u{2}       \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ\nحَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوٓاْ ءَابَآءَهُمۡ أَوۡ أَبۡنَآءَهُمۡ\nأَوۡ إِخۡوَٰنَهُمۡ أَوۡ عَشِيرَتَهُمۡۚ أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ\nٱلۡإِيمَٰنَ وَأَيَّدَهُم بِرُوحٖ مِّنۡهُۖ وَيُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي\nمِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ رَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ\nعَنۡهُۚ أُوْلَٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ\u{a0}٢٢\n\u{2}        \n       \n       \n      \n        \n         \u{a0}\n\u{1}\u{2}\u{2}9\u{2}سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}١\n\u{2}          \u{a0}\n\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ\nلِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ\nحُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ\nفِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ\nفَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ\u{a0}٢\u{2}         \n        \n         \n       \n  \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً\nعَلَىٰٓ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ\u{a0}٥\u{2}      \n     \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ\nيَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَٰٓئِكَ\nهُمُ ٱلصَّٰدِقُونَ\u{a0}٨\u{2}      \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ\nيُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ\nمِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ\nوَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ\u{a0}٩\n\u{2}     \n        \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا\nوَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا\nغِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ\u{a0}١٠\u{2}       \n       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}۞ أَلَمۡ تَرَ إِلَى\nٱلَّذِينَ نَافَقُواْ يَقُولُونَ لِإِخۡوَٰنِهِمُ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ\nٱلۡكِتَٰبِ لَئِنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِيعُ فِيكُمۡ\nأَحَدًا أَبَدٗا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ\u{a0}١١\n\u{2}  \n       \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}لَئِنۡ أُخۡرِجُواْ لَا يَخۡرُجُونَ مَعَهُمۡ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمۡ\nوَلَئِن نَّصَرُوهُمۡ لَيُوَلُّنَّ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يُنصَرُونَ\u{a0}١٢\n\u{2}        \n      \u{a0}\n\u{1}\u{2}9\u{2}\u{2}لَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ\nلَّا يَفۡقَهُونَ\u{a0}١٣\u{2}         \n \u{a0}\u{1}\u{2}\u{2}\u{2}لَا يُقَٰتِلُونَكُمۡ جَمِيعًا إِلَّا فِي قُرٗى\nمُّحَصَّنَةٍ أَوۡ مِن وَرَآءِ جُدُرِۭۚ بَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ\nجَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ\u{a0}١٤\n\u{2}     \n        \n       \u{a0}\n\u{1}\u{2}13\u{2}\u{2}كَمَثَلِ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَرِيبٗاۖ ذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ\nأَلِيمٞ\u{a0}١٥\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}كَمَثَلِ ٱلشَّيۡطَٰنِ إِذۡ قَالَ لِلۡإِنسَٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ\nقَالَ إِنِّي بَرِيٓءٞ مِّنكَ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ\u{a0}١٦\n\u{2}       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِي ٱلنَّارِ خَٰلِدَيۡنِ فِيهَاۚ وَذَٰلِكَ جَزَٰٓؤُاْ\nٱلظَّٰلِمِينَ\u{a0}١٧\u{2}        \n\u{a0}\u{1}\u{2}\u{2}3\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ\nنَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}١٨\n\u{2}     \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَٰٓئِكَ\nهُمُ ٱلۡفَٰسِقُونَ\u{a0}١٩\u{2}       \n \u{a0}\u{1}\u{2}5\u{2}6\u{2}لَا يَسۡتَوِيٓ أَصۡحَٰبُ ٱلنَّارِ وَأَصۡحَٰبُ\nٱلۡجَنَّةِۚ أَصۡحَٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَآئِزُونَ\u{a0}٢٠\u{2}    \n    \u{a0}\u{1}\u{2}6\u{2}8\u{2}لَوۡ أَنزَلۡنَا هَٰذَا\nٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ\nٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ يَتَفَكَّرُونَ\u{a0}٢١\n\u{2}  \n       \n      \u{a0}\n\u{1}\u{2}9\u{2}10\u{1}\u{2}10\u{2}12\u{2}هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ\nٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَيۡمِنُ ٱلۡعَزِيزُ\nٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ\u{a0}٢٣\n\u{2}      \n     \n     \u{a0}\n\u{1}\u{2}\u{2}14\u{2}هُوَ ٱللَّهُ ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ\nيُسَبِّحُ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٢٤\n\u{2}       \n        \u{a0}\n\u{1}\u{2}2\u{2}6\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ\nإِلَيۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ\nوَإِيَّاكُمۡ أَن تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدٗا فِي سَبِيلِي\nوَٱبۡتِغَآءَ مَرۡضَاتِيۚ تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ\nوَمَآ أَعۡلَنتُمۡۚ وَمَن يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ\u{a0}١\u{2}        \n         \n          \n        \n        \u{a0}\u{1}\u{2}6\u{2}\u{2}إِن\nيَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم\nبِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ\u{a0}٢\u{2}\n       \n   \u{a0}\u{1}\u{2}8\u{2}9\u{2}لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ\nيَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ\u{a0}٣\u{2}    \n       \u{a0}\u{1}\u{2}9\u{2}\u{2}قَدۡ\nكَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ\nإِنَّا بُرَءَٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا\nوَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا\nقَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَيۡءٖۖ\nرَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ\u{a0}٤\u{2}\n          \n           \n        \n           \n      \u{a0}\u{1}\u{2}\u{2}\u{2}رَبَّنَا لَا تَجۡعَلۡنَا\nفِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\u{a0}٥\n\u{2}  \n         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}۞ عَسَى ٱللَّهُ أَن يَجۡعَلَ\nبَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةٗۚ وَٱللَّهُ قَدِيرٞۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ\u{a0}٧\n\u{2}   \n          \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّمَا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمۡ فِي ٱلدِّينِ وَأَخۡرَجُوكُم\nمِّن دِيَٰرِكُمۡ وَظَٰهَرُواْ عَلَىٰٓ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن يَتَوَلَّهُمۡ فَأُوْلَٰٓئِكَ\nهُمُ ٱلظَّٰلِمُونَ\u{a0}٩\u{2}        \n         \n \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ\nمُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِيمَٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ\nفَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم\nمَّآ أَنفَقُواْۚ وَلَا جُنَاحَ عَلَيۡكُمۡ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّۚ\nوَلَا تُمۡسِكُواْ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُواْ مَآ أَنفَقۡتُمۡ وَلۡيَسۡـَٔلُواْ مَآ أَنفَقُواْۚ\nذَٰلِكُمۡ حُكۡمُ ٱللَّهِ يَحۡكُمُ بَيۡنَكُمۡۖ وَٱللَّهُ عَلِيمٌ حَكِيمٞ\u{a0}١٠\u{2}     \n       \n            \n         \n         \n       \u{a0}\u{1}'
    '\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا جَآءَكَ ٱلۡمُؤۡمِنَٰتُ يُبَايِعۡنَكَ عَلَىٰٓ أَن لَّا يُشۡرِكۡنَ\nبِٱللَّهِ شَيۡـٔٗا وَلَا يَسۡرِقۡنَ وَلَا يَزۡنِينَ وَلَا يَقۡتُلۡنَ أَوۡلَٰدَهُنَّ وَلَا يَأۡتِينَ\nبِبُهۡتَٰنٖ يَفۡتَرِينَهُۥ بَيۡنَ أَيۡدِيهِنَّ وَأَرۡجُلِهِنَّ وَلَا يَعۡصِينَكَ\nفِي مَعۡرُوفٖ فَبَايِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ\u{a0}١٢\n\u{2}         \n          \n      \n         \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِمۡ\nقَدۡ يَئِسُواْ مِنَ ٱلۡأٓخِرَةِ كَمَا يَئِسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَٰبِ ٱلۡقُبُورِ\u{a0}١٣\n\u{2}        \n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ لِمَ\nتُؤۡذُونَنِي وَقَد تَّعۡلَمُونَ أَنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡۖ فَلَمَّا\nزَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ\u{a0}٥\n\u{2}     \n       \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذۡ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُم مُّصَدِّقٗا\nلِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ فَلَمَّا\nجَآءَهُم بِٱلۡبَيِّنَٰتِ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ\u{a0}٦\u{2}           \n            \n     \u{a0}\u{1}\u{2}\u{2}\u{2}وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ\nعَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ يُدۡعَىٰٓ إِلَى ٱلۡإِسۡلَٰمِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ\u{a0}٧\n\u{2}   \n           \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ هَلۡ أَدُلُّكُمۡ\nعَلَىٰ تِجَٰرَةٖ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمٖ\u{a0}١٠\u{2}    \n     \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّـۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ\nعَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ\nمِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ\u{a0}٢\u{2}       \n       \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}قُلۡ إِنَّ\nٱلۡمَوۡتَ ٱلَّذِي تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَٰقِيكُمۡۖ ثُمَّ تُرَدُّونَ\nإِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\u{a0}٨\n\u{2} \n       \n       \u{a0}\n\u{1}\u{2}\u{2}3\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ\nفَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ\nتَعۡلَمُونَ\u{a0}٩\u{2}        \n          \n\u{a0}\u{1}\u{2}\u{2}\u{2}فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ\nوَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ\u{a0}١٠\n\u{2}     \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ\nمَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّٰزِقِينَ\u{a0}١١\n\u{2}         \n          \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ\nإِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ\u{a0}١\n\u{2}         \n      \u{a0}\n\u{1}\u{2}11\u{2}\u{2}ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ\nيَعۡمَلُونَ\u{a0}٢\u{2}          \n\u{a0}\u{1}\u{2}\u{2}\u{2}ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ\nفَهُمۡ لَا يَفۡقَهُونَ\u{a0}٣\u{2}       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}۞ وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ\nوَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبٞ مُّسَنَّدَةٞۖ يَحۡسَبُونَ كُلَّ\nصَيۡحَةٍ عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ\u{a0}٤\n\u{2}   \n        \n        \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡاْ رُءُوسَهُمۡ\nوَرَأَيۡتَهُمۡ يَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ\u{a0}٥\u{2}         \n   \u{a0}\u{1}\u{2}2\u{2}\u{2}سَوَآءٌ عَلَيۡهِمۡ\nأَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ\nٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ\u{a0}٦\u{2} \n          \n    \u{a0}\u{1}\u{2}4\u{2}6\u{2}هُمُ ٱلَّذِينَ يَقُولُونَ\nلَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّواْۗ وَلِلَّهِ\nخَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ\u{a0}٧\n\u{2}  \n         \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ\nمِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ\nٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ\u{a0}٨\u{2}      \n      \n  \u{a0}\u{1}\u{2}9\u{2}11\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ\nأَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ\nذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ\u{a0}٩\u{2}    \n       \n   \u{a0}\u{1}\u{2}11\u{2}13\u{2}وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم\nمِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ\nإِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ\u{a0}١٠\u{2}   \n         \n      \u{a0}\u{1}\u{2}13\u{2}14\u{2}وَلَن\nيُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ\u{a0}١١\n\u{2}\n         \u{a0}\n\u{1}\u{2}2\u{2}3\u{2}يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ\nوَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ\u{a0}١\u{2}           \n    \u{a0}\u{1}\u{2}3\u{2}4\u{2}هُوَ ٱلَّذِي خَلَقَكُمۡ فَمِنكُمۡ كَافِرٞ\nوَمِنكُم مُّؤۡمِنٞۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ\u{a0}٢\u{2}    \n     \u{a0}\u{1}\u{2}4\u{2}5\u{2}خَلَقَ ٱلسَّمَٰوَٰتِ\nوَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ\u{a0}٣\n\u{2} \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ\nعَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\u{a0}٤\u{2}          \n  \u{a0}\u{1}\u{2}7\u{2}8\u{2}أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُ\nفَذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ\u{a0}٥\u{2}      \n     \u{a0}\u{1}\u{2}8\u{2}\u{2}ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأۡتِيهِمۡ\nرُسُلُهُم بِٱلۡبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرٞ يَهۡدُونَنَا فَكَفَرُواْ وَتَوَلَّواْۖ وَّٱسۡتَغۡنَى\nٱللَّهُۚ وَٱللَّهُ غَنِيٌّ حَمِيدٞ\u{a0}٦\u{2}   \n       \n   \u{a0}\u{1}\u{2}\u{2}11\u{2}زَعَمَ ٱلَّذِينَ كَفَرُوٓاْ أَن لَّن يُبۡعَثُواْۚ قُلۡ بَلَىٰ وَرَبِّي\nلَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ\u{a0}٧\u{2}        \n        \u{a0}\u{1}\u{2}11\u{2}12\u{2}فَـَٔامِنُواْ بِٱللَّهِ\nوَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِيٓ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ\u{a0}٨\u{2} \n       \u{a0}\u{1}\u{2}12\u{2}\u{2}يَوۡمَ\nيَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ\nصَٰلِحٗا يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا\nٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\u{a0}٩\n\u{2}\n         \n        \n      \u{a0}\n\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ\nٱلنَّارِ خَٰلِدِينَ فِيهَاۖ وَبِئۡسَ ٱلۡمَصِيرُ\u{a0}١٠\u{2}     \n    \u{a0}\u{1}\u{2}2\u{2}\u{2}مَآ أَصَابَ مِن\nمُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ\nشَيۡءٍ عَلِيمٞ\u{a0}١١\u{2}  \n          \n \u{a0}\u{1}\u{2}\u{2}5\u{2}وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۚ فَإِن\nتَوَلَّيۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ\u{a0}١٢\u{2}    \n     \u{a0}\u{1}\u{2}5\u{2}6\u{2}ٱللَّهُ لَآ إِلَٰهَ\nإِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\u{a0}١٣\u{2}  \n     \u{a0}\u{1}\u{2}6\u{2}\u{2}يَٰٓأَيُّهَا\nٱلَّذِينَ ءَامَنُوٓاْ إِنَّ مِنۡ أَزۡوَٰجِكُمۡ وَأَوۡلَٰدِكُمۡ عَدُوّٗا\nلَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُواْ وَتَصۡفَحُواْ وَتَغۡفِرُواْ\nفَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ\u{a0}١٤\u{2}\n      \n     \n   \u{a0}\u{1}\u{2}\u{2}10\u{2}إِنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ\nفِتۡنَةٞۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ\u{a0}١٥\u{2}  \n    \u{a0}\u{1}\u{2}10\u{2}12\u{2}فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ\nوَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن\nيُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ\u{a0}١٦\u{2}   \n     \n     \u{a0}\u{1}\u{2}12\u{2}14\u{2}إِن تُقۡرِضُواْ\nٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ\nحَلِيمٌ\u{a0}١٧\u{2} \n        \n\u{a0}\u{1}\u{2}14\u{2}14\u{1}\u{2}2\u{2}\u{2}۞يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ\nٱلۡعِدَّةَۖ وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ\nوَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَتِلۡكَ حُدُودُ\nٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ\nٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرٗا\u{a0}١\u{2}       \n       \n        \n          \n    \u{a0}\u{1}\u{2}6\u{2}\u{2}فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ\nبِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ\nوَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ\nبِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا\u{a0}٢\u{2}   \n       \n        \n        \u{a0}\u{1}\u{2}9\u{2}\u{2}وَيَرۡزُقۡهُ\nمِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ\nبَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا\u{a0}٣\u{2}\n           \n       \u{a0}\u{1}'
    '\u{1}\u{1}\u{2}\u{2}\u{2}أَسۡكِنُوهُنَّ مِنۡ حَيۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ\nعَلَيۡهِنَّۚ وَإِن كُنَّ أُوْلَٰتِ حَمۡلٖ فَأَنفِقُواْ عَلَيۡهِنَّ حَتَّىٰ يَضَعۡنَ حَمۡلَهُنَّۚ\nفَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ وَإِن\nتَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ\u{a0}٦\u{2}        \n         \n        \n   \u{a0}\u{1}\u{2}\u{2}\u{2}لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ\nوَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا\nإِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا\u{a0}٧\u{2}    \n           \n       \u{a0}\u{1}\u{2}\u{2}\u{2}وَكَأَيِّن مِّن قَرۡيَةٍ\nعَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابٗا شَدِيدٗا وَعَذَّبۡنَٰهَا\nعَذَابٗا نُّكۡرٗا\u{a0}٨\u{2}  \n        \n \u{a0}\u{1}\u{2}\u{2}\u{2}فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا\u{a0}٩\n\u{2}      \u{a0}\n\u{1}\u{2}9\u{2}\u{2}أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدٗاۖ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ٱلَّذِينَ ءَامَنُواْۚ\nقَدۡ أَنزَلَ ٱللَّهُ إِلَيۡكُمۡ ذِكۡرٗا\u{a0}١٠\u{2}          \n    \u{a0}\u{1}\u{2}\u{2}\u{2}رَّسُولٗا يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٖ\nلِّيُخۡرِجَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ\nوَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا\nٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا\u{a0}١١\u{2}     \n        \n         \n        \u{a0}\u{1}\u{2}\u{2}\u{2}ٱللَّهُ ٱلَّذِي خَلَقَ\nسَبۡعَ سَمَٰوَٰتٖ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ لِتَعۡلَمُوٓاْ أَنَّ\nٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا\u{a0}١٢\n\u{2}  \n         \n           \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ\nوَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ\u{a0}٢\u{2}       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا\nفَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ\nفَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ\u{a0}٣\n\u{2}      \n          \n          \u{a0}\n\u{1}\u{2}8\u{2}\u{2}إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ\nفَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَٰٓئِكَةُ\nبَعۡدَ ذَٰلِكَ ظَهِيرٌ\u{a0}٤\u{2}         \n       \n  \u{a0}\u{1}\u{2}\u{2}\u{2}عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا\nخَيۡرٗا مِّنكُنَّ مُسۡلِمَٰتٖ مُّؤۡمِنَٰتٖ قَٰنِتَٰتٖ تَٰٓئِبَٰتٍ عَٰبِدَٰتٖ سَٰٓئِحَٰتٖ\nثَيِّبَٰتٖ وَأَبۡكَارٗا\u{a0}٥\u{2}      \n       \n \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ\nنَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَٰٓئِكَةٌ غِلَاظٞ شِدَادٞ\nلَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ\u{a0}٦\u{2}     \n       \n       \u{a0}\u{1}\u{2}\u{2}\u{2}يَٰٓأَيُّهَا\nٱلَّذِينَ كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ\u{a0}٧\n\u{2}\n         \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَٱعۡتَرَفُواْ بِذَنۢبِهِمۡ فَسُحۡقٗا لِّأَصۡحَٰبِ ٱلسَّعِيرِ\u{a0}١١\n\u{2}    \u{a0}\n\u{1}\u{2}15\u{2}\u{2}إِنَّ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ\u{a0}١٢\n\u{2}        \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}هُوَ ٱلَّذِي جَعَلَ لَكُمُ\nٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ\u{a0}١٥\n\u{2}   \n         \u{a0}\n\u{1}\u{2}\u{2}5\u{2}ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ\nتَمُورُ\u{a0}١٦\u{2}         \n\u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗاۖ\nفَسَتَعۡلَمُونَ كَيۡفَ نَذِيرِ\u{a0}١٧\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}7\u{2}وَلَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَكَيۡفَ\nكَانَ نَكِيرِ\u{a0}١٨\u{2}     \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَٰٓفَّٰتٖ وَيَقۡبِضۡنَۚ مَا\nيُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ\u{a0}١٩\u{2}       \n      \u{a0}\u{1}\u{2}\u{2}\u{2}أَمَّنۡ هَٰذَا ٱلَّذِي\nهُوَ جُندٞ لَّكُمۡ يَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَٰنِۚ إِنِ ٱلۡكَٰفِرُونَ إِلَّا فِي غُرُورٍ\u{a0}٢٠\n\u{2}  \n           \u{a0}\n\u{1}\u{2}10\u{2}11\u{2}أَمَّنۡ هَٰذَا ٱلَّذِي يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّواْ فِي عُتُوّٖ\nوَنُفُورٍ\u{a0}٢١\u{2}          \n\u{a0}\u{1}\u{2}11\u{2}\u{2}أَفَمَن يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا\nعَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ\u{a0}٢٢\u{2}        \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ\nوَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ\u{a0}٢٣\u{2}      \n    \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ هُوَ ٱلَّذِي ذَرَأَكُمۡ\nفِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ\u{a0}٢٤\u{2}   \n   \u{a0}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا رَأَوۡهُ زُلۡفَةٗ سِيٓـَٔتۡ وُجُوهُ ٱلَّذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ٱلَّذِي\nكُنتُم بِهِۦ تَدَّعُونَ\u{a0}٢٧\u{2}         \n  \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِيَ ٱللَّهُ وَمَن مَّعِيَ\nأَوۡ رَحِمَنَا فَمَن يُجِيرُ ٱلۡكَٰفِرِينَ مِنۡ عَذَابٍ أَلِيمٖ\u{a0}٢٨\u{2}      \n       \u{a0}\u{1}\u{2}\u{2}\u{2}قُلۡ هُوَ\nٱلرَّحۡمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ\u{a0}٢٩\n\u{2} \n          \u{a0}\n\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}مَآ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونٖ\u{a0}٢\n\u{2}    \u{a0}\n\u{1}\u{2}9\u{2}\u{2}وَإِنَّ لَكَ لَأَجۡرًا غَيۡرَ مَمۡنُونٖ\u{a0}٣\u{2}    \u{a0}\u{1}\u{2}\u{2}\u{2}وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٖ\u{a0}٤\n\u{2}   \u{a0}\n\u{1}\u{2}10\u{2}\u{2}فَسَتُبۡصِرُ وَيُبۡصِرُونَ\u{a0}٥\u{2} \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}إِنَّ رَبَّكَ هُوَ\nأَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ\u{a0}٧\u{2}  \n       \u{a0}\u{1}\u{2}\u{2}12\u{2}فَلَا تُطِعِ\nٱلۡمُكَذِّبِينَ\u{a0}٨\u{2} \n\u{a0}\u{1}\u{1}'
    '\u{2}\u{2}13\u{2}وَلَا تُطِعۡ كُلَّ\nحَلَّافٖ مَّهِينٍ\u{a0}١٠\u{2}  \n \u{a0}\u{1}\u{1}\u{2}\u{2}14\u{2}مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٍ\nأَثِيمٍ\u{a0}١٢\u{2}  \n\u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَن كَانَ ذَا مَالٖ وَبَنِينَ\u{a0}١٤\n\u{2}    \u{a0}\n\u{1}\u{2}15\u{2}\u{2}إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ\u{a0}١٥\n\u{2}      \u{a0}\n\u{1}565\u{2}1\u{2}1\u{2}سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ\u{a0}١٦\u{2}  \u{a0}\u{1}\u{2}\u{2}2\u{2}إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ\nلَيَصۡرِمُنَّهَا مُصۡبِحِينَ\u{a0}١٧\u{2}       \n \u{a0}\u{1}\u{2}2\u{2}\u{2}وَلَا يَسۡتَثۡنُونَ\u{a0}١٨\u{2} \u{a0}\u{1}\u{2}\u{2}3\u{2}فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ\nوَهُمۡ نَآئِمُونَ\u{a0}١٩\u{2}    \n \u{a0}\u{1}\u{2}3\u{2}\u{2}فَأَصۡبَحَتۡ كَٱلصَّرِيمِ\u{a0}٢٠\u{2} \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَنِ\nٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ\u{a0}٢٢\u{2}\n     \u{a0}\u{1}\u{2}\u{2}\u{2}فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ\u{a0}٢٣\n\u{2}  \u{a0}\n\u{1}\u{2}5\u{2}\u{2}أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ\u{a0}٢٤\u{2}     \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَلَمَّا\nرَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ\u{a0}٢٦\u{2}\n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل\nلَّكُمۡ لَوۡلَا تُسَبِّحُونَ\u{a0}٢٨\u{2}   \n  \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}فَأَقۡبَلَ\nبَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ\u{a0}٣٠\u{2}\n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}عَسَىٰ\nرَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ\u{a0}٣٢\u{2}\n        \u{a0}\u{1}\u{2}\u{2}\u{2}كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ\nٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ\u{a0}٣٣\u{2}  \n    \u{a0}\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}\u{2}أَمۡ\nلَكُمۡ كِتَٰبٞ فِيهِ تَدۡرُسُونَ\u{a0}٣٧\u{2}\n   \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَمۡ لَكُمۡ أَيۡمَٰنٌ\nعَلَيۡنَا بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ\u{a0}٣٩\u{2}  \n        \u{a0}\u{1}\u{2}\u{2}\u{2}سَلۡهُمۡ أَيُّهُم\nبِذَٰلِكَ زَعِيمٌ\u{a0}٤٠\u{2} \n \u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ\u{a0}٤١\n\u{2}       \u{a0}\n\u{1}\u{2}15\u{2}\u{2}يَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ\u{a0}٤٢\n\u{2}        \u{a0}\n\u{1}\u{2}\u{2}1\u{2}خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ\u{a0}٤٣\n\u{2}          \u{a0}\n\u{1}\u{2}\u{2}\u{2}فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ\nلَا يَعۡلَمُونَ\u{a0}٤٤\u{2}       \n \u{a0}\u{1}\u{1}\u{2}\u{2}\u{2}أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم\nمِّن مَّغۡرَمٖ مُّثۡقَلُونَ\u{a0}٤٦\u{2}   \n  \u{a0}\u{1}\u{2}\u{2}\u{2}أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ\u{a0}٤٧\u{2}    \u{a0}\u{1}\u{2}4\u{2}5\u{2}فَٱصۡبِرۡ\nلِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ\u{a0}٤٨\u{2}\n         \u{a0}\u{1}\u{2}5\u{2}6\u{2}لَّوۡلَآ\nأَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ\u{a0}٤٩\u{2}\n        \u{a0}\u{1}\u{2}6\u{2}\u{2}فَٱجۡتَبَٰهُ رَبُّهُۥ\nفَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ\u{a0}٥٠\u{2} \n  \u{a0}\u{1}\u{2}7\u{2}8\u{2}وَإِن يَكَادُ