    '\u{2}\u{2}8\u{2}وَٱلَّذِينَ يُصَدِّقُونَ\nبِيَوۡمِ ٱلدِّينِ\u{a0}٢٦\u{2} \n \u{a0}\u{1}\u{2}8\u{2}\u{2}وَٱلَّذِينَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ\u{a0}٢٧\u{2}     \u{a0}\u{1}\u{2}\u{2}9\u{2}إِنَّ عَذَابَ\nرَبِّهِمۡ غَيۡرُ مَأۡمُونٖ\u{a0}٢٨\u{2} \n  \u{a0}\u{1}\u{2}9\u{2}\u{2}وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ\u{a0}٢٩\u{2}   \u{a0}\u{1}\u{2}\u{2}\u{2}إِلَّا عَلَىٰٓ\nأَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ\u{a0}٣٠\u{2} \n       \u{a0}\u{1}\u{2}\u{2}11\u{2}فَمَنِ ٱبۡتَغَىٰ وَرَآءَ\nذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ\u{a0}٣١\u{2}  \n   \u{a0}\u{1}\u{2}11\u{2}\u{2}وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ\u{a0}٣٢\n\u{2}    \u{a0}\n\u{1}\u{2}12\u{2}12\u{2}وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ\u{a0}٣٣\u{2}   \u{a0}\u{1}\u{2}\u{2}\u{2}وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ\u{a0}٣٤\n\u{2}    \u{a0}\n\u{1}\u{2}13\u{2}13\u{2}أُوْلَٰٓئِكَ فِي جَنَّٰتٖ مُّكۡرَمُونَ\u{a0}٣٥\u{2}   \u{a0}\u{1}\u{2}\u{2}\u{2}فَمَالِ ٱلَّذِينَ كَفَرُواْ قِبَلَكَ مُهۡطِعِينَ\u{a0}٣٦\n\u{2}    \u{a0}\n\u{1}\u{2}14\u{2}\u{2}عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ\u{a0}٣٧\u{2}    \u{a0}\u{1}\u{2}\u{2}15\u{2}أَيَطۡمَعُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ\nأَن يُدۡخَلَ جَنَّةَ نَعِيمٖ\u{a0}٣٨\u{2}   \n   \u{a0}\u{1}\u{2}15\u{2}\u{2}كـَلَّآۖ إِنَّا خَلَقۡنَٰهُم مِّمَّا يَعۡلَمُونَ\u{a0}٣٩\n\u{2}    \u{a0}\n\u{1}570\u{2}1\u{2}1\u{2}فَلَآ أُقۡسِمُ بِرَبِّ ٱلۡمَشَٰرِقِ وَٱلۡمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ\u{a0}٤٠\u{2}      \u{a0}\u{1}\u{2}\u{2}2\u{2}عَلَىٰٓ أَن نُّبَدِّلَ خَيۡرٗا مِّنۡهُمۡ\nوَمَا نَحۡنُ بِمَسۡبُوقِينَ\u{a0}٤١\u{2}    \n  \u{a0}\