    '\u{2}\u{2}\u{2}إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمَسَاقُ\u{a0}٣٠\u{2}   \u{a0}\u{1}\u{2}4\u{2}4\u{2}فَلَا صَدَّقَ وَلَا صَلَّىٰ\u{a0}٣١\n\u{2}   \u{a0}\n\u{1}\u{1}\u{2}\u{2}5\u{2}ثُمَّ ذَهَبَ إِلَىٰٓ أَهۡلِهِۦ يَتَمَطَّىٰٓ\u{a0}٣٣\u{2}    \u{a0}\u{1}\u{2}5\u{2}\u{2}أَوۡلَىٰ لَكَ\nفَأَوۡلَىٰ\u{a0}٣٤\u{2} \n\u{a0}\u{1}\u{1}\u{2}\u{2}6\u{2}أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَن يُتۡرَكَ سُدًى\u{a0}٣٦\n\u{2}    \u{a0}\n\u{1}\u{2}\u{2}\u{2}أَلَمۡ يَكُ نُطۡفَةٗ مِّن مَّنِيّٖ يُمۡنَىٰ\u{a0}٣٧\u{2}     \u{a0}\u{1}\u{2}7\u{2}7\u{1}\u{2}7\u{2}8\u{2}فَجَعَلَ مِنۡهُ\nٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ\u{a0}٣٩\u{2} \n  \u{a0}\u{1}\u{2}8\u{2}8\u{1}\u{2}11\u{2}11\u{2}هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـٔٗا مَّذۡكُورًا\u{a0}١\n\u{2}          \u{a0}\n\u{1}\u{2}\u{2}\u{2}إِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا\nبَصِيرًا\u{a0}٢\u{2}        \n\u{a0}\u{1}\u{2}\u{2}13\u{2}إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا\u{a0}٣\n\u{2}      \u{a0}\n\u{1}\u{2}\u{2}14\u{2}إِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَلَٰسِلَاْ وَأَغۡلَٰلٗا وَسَعِيرًا\u{a0}٤\u{2}     \u{a0}\u{1}\u{2}14\u{2}\u{2}إِنَّ\nٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا\u{a0}٥\n\u{2}\n      \u{a0}\n\u{1}\u{1}\u{1}\u{1}\u{2}\u{2}3\u{2}إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا\u{a0}٩\n\u{2}         \u{a0}\n\u{1}\u{1}\u{2}\u{2}\u{2}فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ\nٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا\u{a0}١١\u{2}   \n   \u{a0}\u{1}\u{2}\u{2}5\u{2}وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا\u{a0}١٢\n\u{2} 